impl SpecOracleService {
    async fn create_universe(&self, req: Request<CreateUniverseRequest>)
        -> Result<Response<CreateUniverseResponse>, Status> {
        let req = req.into_inner();
        let mut pm = self.project_manager.lock().unwrap();
        let project = pm.get_current_or_named_mut(&req.project)?;

        let universe_id = project.udaf_model.add_universe(
            req.layer,
            req.name,
            req.description,
        )?;

        project.save(pm.base_path())?;

        Ok(Response::new(CreateUniverseResponse {
            universe: Some(/* serialize universe */),
        }))
    }

    async fn construct_u0(&self, req: Request<ConstructU0Request>)
        -> Result<Response<ConstructU0Response>, Status> {
        let req = req.into_inner();
        let mut pm = self.project_manager.lock().unwrap();
        let project = pm.get_current_or_named_mut(&req.project)?;

        let root = deserialize_root_space(req.root_space)?;
        let specs = project.udaf_model.construct_u0(&root, &project.repository)?;

        if req.execute_transforms {
            // Actually execute extractors and populate U0
            for spec in &specs {
                project.repository.add_node(/* ... */)?;
            }
            project.save(pm.base_path())?;
        }

        Ok(Response::new(ConstructU0Response {
            specs: specs.into_iter().map(serialize_inferred_spec).collect(),
            ingestion_report: /* ... */,
        }))
    }

    async fn prove_property(&self, req: Request<ProvePropertyRequest>)
        -> Result<Response<ProvePropertyResponse>, Status> {
        #[cfg(feature = "z3-solver")]
        {
            let req = req.into_inner();
            let pm = self.project_manager.lock().unwrap();
            let project = pm.get_current_or_named(&req.project)?;

            let prover = Z3Backend::new()?;
            let result = prover.prove(&project.udaf_model, req.property)?;

            Ok(Response::new(ProvePropertyResponse {
                status: result.status.into(),
                proof: Some(serialize_proof(result.proof)),
                counterexample: result.counterexample.unwrap_or_default(),
            }))
        }
        #[cfg(not(feature = "z3-solver"))]
        {
            Err(Status::unimplemented("Z3 solver not enabled"))
        }
    }
}
