fn find_legacy_spec_dir() -> Option<PathBuf> {
    let mut dir = std::env::current_dir().ok()?;
    loop {
        let spec_dir = dir.join(".spec");
        if spec_dir.exists() && spec_dir.is_dir() {
            return Some(spec_dir);
        }
        if !dir.pop() {
            break;
        }
    }
    None
}
