spec project create my-app --storage local --path ~/.specd/projects

# Local filesystem - project-local .spec/ (existing pattern, still supported)
cd /path/to/my-project
spec project create my-app --storage local --path ./.spec

# Database (future)
spec project create my-app --storage postgres \
  --connection "postgresql://localhost/specd"

# S3 (future)
