   153→    async fn create_project(
   154→        &self,
   155→        request: Request<proto::CreateProjectRequest>,
   156→    ) -> Result<Response<proto::CreateProjectResponse>, Status> {
   157→        let req = request.into_inner();
   158→
   159→        let storage = match req.storage_backend() {
   160→            proto::StorageBackend::LocalFile | proto::StorageBackend::Unspecified => {
   161→                let pm = self.project_manager.lock()
   162→                    .map_err(|e| Status::internal(format!("Lock error: {}", e)))?;
   163→                crate::config::StorageConfig::LocalFile {
   164→                    base_path: pm.base_path().to_path_buf(),
   165→                }
   166→            }
   167→            proto::StorageBackend::Database => {
   168→                return Err(Status::unimplemented("Database storage not yet implemented"));
   169→            }
   170→            proto::StorageBackend::S3 => {
   171→                return Err(Status::unimplemented("S3 storage not yet implemented"));
   172→            }
   173→            proto::StorageBackend::Git => {
   174→                return Err(Status::unimplemented("Git storage not yet implemented"));
   175→            }
   176→        };
   177→
   178→        let mut pm = self.project_manager.lock()
   179→            .map_err(|e| Status::internal(format!("Lock error: {}", e)))?;
   180→
   181→        pm.create_project(req.name.clone(), req.description, storage)
   182→            .map_err(|e| Status::already_exists(format!("Failed to create project: {}", e)))?;
   183→
   184→        let project_info = pm.list_projects()
   185→            .map_err(|e| Status::internal(format!("Failed to list projects: {}", e)))?
   186→            .into_iter()
   187→            .find(|p| p.name == req.name)
   188→            .ok_or_else(|| Status::internal("Project created but not found"))?;
   189→
   190→        Ok(Response::new(proto::CreateProjectResponse {
   191→            project: Some(proto::Project {
   192→                name: project_info.name,
   193→                description: project_info.description,
   194→                created_at: project_info.created_at,
   195→                node_count: project_info.node_count as u32,
   196→                edge_count: project_info.edge_count as u32,
   197→                storage: to_proto_storage_backend(&project_info.storage).into(),
   198→            }),
   199→        }))
   200→    }
