     1→/// UDAF Model: The complete multi-universe specification model
     2→///
     3→/// This is the core data structure that implements the theoretical foundation
     4→/// of specORACLE as described in conversation.md and motivation.md.
     5→use serde::{Deserialize, Serialize};
     6→use std::collections::{HashMap, HashSet};
     7→use crate::formal::*;
     8→use crate::formal::projection::RootSpace;
     9→use crate::formal::transform::ObserverKind;
    10→use crate::{InferredSpecification, RustExtractor};
    11→use crate::data::SpecRepository;
    12→
    13→#[derive(Debug, Clone, Serialize, Deserialize)]
    14→pub struct UDAFModel {
    15→    /// All universes in the model (keyed by UniverseId)
    16→    #[serde(with = "super::serde_helpers::universe_map_serde")]
    17→    pub universes: HashMap<UniverseId, Universe>,
    18→
    19→    /// All domains across all universes (keyed by DomainId)
    20→    #[serde(with = "super::serde_helpers::domain_map_serde")]
