    fn test_switch_project() {
        let temp_dir = TempDir::new().unwrap();
        let mut pm = ProjectManager::new(temp_dir.path().to_path_buf());

        pm.create_project(
            "project1".to_string(),
            "Project 1".to_string(),
            StorageConfig::LocalFile {
                base_path: temp_dir.path().to_path_buf(),
            },
        )
        .unwrap();

        pm.create_project(
            "project2".to_string(),
            "Project 2".to_string(),
            StorageConfig::LocalFile {
                base_path: temp_dir.path().to_path_buf(),
