    async fn create_project(
        &self,
        request: Request<proto::CreateProjectRequest>,
    ) -> Result<Response<proto::CreateProjectResponse>, Status> {
        let req = request.into_inner();

        let storage = match req.storage_backend() {
            proto::StorageBackend::LocalFile | proto::StorageBackend::Unspecified => {
                let pm = self.project_manager.lock()
                    .map_err(|e| Status::internal(format!("Lock error: {}", e)))?;
                crate::config::StorageConfig::LocalFile {
                    base_path: pm.base_path().to_path_buf(),
                }
            }
            proto::StorageBackend::Database => {
                return Err(Status::unimplemented("Database storage not yet implemented"));
            }
            proto::StorageBackend::S3 => {
                return Err(Status::unimplemented("S3 storage not yet implemented"));
            }
            proto::StorageBackend::Git => {
                return Err(Status::unimplemented("Git storage not yet implemented"));
            }
        };

        let mut pm = self.project_manager.lock()
            .map_err(|e| Status::internal(format!("Lock error: {}", e)))?;

        pm.create_project(req.name.clone(), req.description, storage)
            .map_err(|e| Status::already_exists(format!("Failed to create project: {}", e)))?;

        let project_info = pm.list_projects()
            .map_err(|e| Status::internal(format!("Failed to list projects: {}", e)))?
            .into_iter()
            .find(|p| p.name == req.name)
            .ok_or_else(|| Status::internal("Project created but not found"))?;

        Ok(Response::new(proto::CreateProjectResponse {
            project: Some(proto::Project {
                name: project_info.name,
                description: project_info.description,
                created_at: project_info.created_at,
                node_count: project_info.node_count as u32,
                edge_count: project_info.edge_count as u32,
                storage: to_proto_storage_backend(&project_info.storage).into(),
            }),
        }))
    }

    async fn list_projects(
        &self,
        _request: Request<proto::ListProjectsRequest>,
    ) -> Result<Response<proto::ListProjectsResponse>, Status> {
        let pm = self.project_manager.lock()
            .map_err(|e| Status::internal(format!("Lock error: {}", e)))?;

        let projects = pm.list_projects()
            .map_err(|e| Status::internal(format!("Failed to list projects: {}", e)))?
            .into_iter()
            .map(|p| proto::Project {
                name: p.name,
