    fn test_detect_directory_store() {
        let temp_dir = TempDir::new().unwrap();
        let spec_dir = temp_dir.path().join(".spec");
        std::fs::create_dir_all(spec_dir.join("nodes")).unwrap();
        std::fs::write(spec_dir.join("edges.yaml"), "edges: []").unwrap();

