    async fn import_project(
        &self,
        request: Request<proto::ImportProjectRequest>,
    ) -> Result<Response<proto::ImportProjectResponse>, Status> {
        let req = request.into_inner();

        let spec_dir = PathBuf::from(&req.spec_directory_path);
        if !spec_dir.exists() {
            return Err(Status::not_found(format!(
                "Directory not found: {}",
                req.spec_directory_path
            )));
        }

        let mut pm = self
            .project_manager
            .lock()
            .map_err(|e| Status::internal(format!("Lock error: {}", e)))?;

        let report = migration::import_legacy_spec_directory(
            &spec_dir,
            req.name.clone(),
            req.description.clone(),
            &mut pm,
        )
        .map_err(|e| Status::internal(format!("Import failed: {}", e)))?;

        let project_info = pm
            .list_projects()
            .map_err(|e| Status::internal(format!("Failed to list projects: {}", e)))?
            .into_iter()
            .find(|p| p.name == req.name)
            .ok_or_else(|| Status::internal("Imported project not found"))?;

        Ok(Response::new(proto::ImportProjectResponse {
            project: Some(proto::Project {
                name: project_info.name,
                description: project_info.description,
                created_at: project_info.created_at,
                node_count: project_info.node_count as u32,
                edge_count: project_info.edge_count as u32,
                storage: to_proto_storage_backend(&project_info.storage).into(),
            }),
            nodes_imported: report.nodes_imported as u32,
            edges_imported: report.edges_imported as u32,
            universes_created: report.universes_created as u32,
        }))
    }
