use config::SpecdConfig;
use migration::{import_legacy_spec_directory, find_legacy_spec_dir};
use project::ProjectManager;
use service::SpecOracleService;
use tonic::transport::Server;
use tracing_subscriber::EnvFilter;

pub mod proto {
    tonic::include_proto!("spec_oracle");
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Load configuration
    let config = SpecdConfig::load_or_default()?;

    // Initialize logging
    tracing_subscriber::fmt()
        .with_env_filter(
            EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| EnvFilter::new(&config.log_level))
        )
        .init();

    tracing::info!("Starting specd...");
    tracing::info!("Projects directory: {}", config.default_path.display());

    // Initialize project manager
    let mut project_manager = ProjectManager::new(config.default_path.clone());

    // Discover existing projects
    project_manager.discover_projects()?;

    // Auto-detect legacy .spec/ directory and offer to import
    if let Some(spec_dir) = find_legacy_spec_dir() {
        tracing::info!("Found legacy .spec/ directory: {}", spec_dir.display());

        // Check if it's already imported
        let spec_dir_name = spec_dir
            .parent()
            .and_then(|p| p.file_name())
            .and_then(|n| n.to_str())
            .unwrap_or("imported-project");

        if !project_manager.list_projects()?.iter().any(|p| p.name == spec_dir_name) {
            eprintln!("\n📦 Detected legacy .spec/ directory: {}", spec_dir.display());
            eprintln!("   Would you like to import it as a project? (y/n) ");

            use std::io::{self, BufRead};
            let stdin = io::stdin();
            if let Some(Ok(input)) = stdin.lock().lines().next() {
                if input.trim().eq_ignore_ascii_case("y") || input.trim().eq_ignore_ascii_case("yes") {
                    eprintln!("   Enter project name (default: {}): ", spec_dir_name);
                    let project_name = if let Some(Ok(name)) = stdin.lock().lines().next() {
