//! Integration tests for specd project lifecycle
//!
//! These tests verify the complete workflow:
//! 1. Project creation
//! 2. Node/edge operations
//! 3. Project switching
//! 4. Project deletion

use specd::proto::spec_oracle_client::SpecOracleClient;
use specd::proto::*;
use tonic::Request;

/// Helper to create a test client connected to specd
async fn create_test_client() -> SpecOracleClient<tonic::transport::Channel> {
    // Assuming specd is running on default address
    SpecOracleClient::connect("http://[::1]:50051")
        .await
        .expect("Failed to connect to specd")
}

#[tokio::test]
async fn test_project_lifecycle() {
    let mut client = create_test_client().await;

    // 1. Create project
    let create_resp = client
        .create_project(Request::new(CreateProjectRequest {
            name: "integration-test".to_string(),
            description: "Integration test project".to_string(),
        }))
        .await
        .expect("Failed to create project");

    let project = create_resp.into_inner().project.expect("No project returned");
    assert_eq!(project.name, "integration-test");

    // 2. List projects - should contain our new project
    let list_resp = client
        .list_projects(Request::new(ListProjectsRequest {}))
        .await
        .expect("Failed to list projects");

    let projects = list_resp.into_inner().projects;
    assert!(
        projects.iter().any(|p| p.name == "integration-test"),
        "Created project not found in list"
    );

    // 3. Switch to the new project
    client
        .switch_project(Request::new(SwitchProjectRequest {
            name: "integration-test".to_string(),
        }))
        .await
        .expect("Failed to switch project");

    // 4. Add a node to the project
    let add_resp = client
        .add_node(Request::new(AddNodeRequest {
            project: "integration-test".to_string(),
            content: "Test specification".to_string(),
            kind: SpecNodeKind::Assertion as i32,
            formality_layer: 0,
            metadata: std::collections::HashMap::new(),
        }))
        .await
        .expect("Failed to add node");

    let node_id = add_resp.into_inner().node_id;
    assert!(!node_id.is_empty());

    // 5. List nodes - should contain our new node
    let list_nodes_resp = client
        .list_nodes(Request::new(ListNodesRequest {
            project: "integration-test".to_string(),
            kind_filter: None,
            formality_layer: None,
        }))
        .await
        .expect("Failed to list nodes");

    let nodes = list_nodes_resp.into_inner().nodes;
    assert_eq!(nodes.len(), 1, "Expected exactly one node");
    assert_eq!(nodes[0].content, "Test specification");

    // 6. Delete project
    client
        .delete_project(Request::new(DeleteProjectRequest {
            name: "integration-test".to_string(),
        }))
        .await
        .expect("Failed to delete project");

    // 7. Verify project is deleted
    let list_resp = client
        .list_projects(Request::new(ListProjectsRequest {}))
        .await
        .expect("Failed to list projects");

    let projects = list_resp.into_inner().projects;
    assert!(
        !projects.iter().any(|p| p.name == "integration-test"),
        "Deleted project still in list"
    );
}

#[tokio::test]
async fn test_project_isolation() {
    let mut client = create_test_client().await;

    // Create two projects
    client
        .create_project(Request::new(CreateProjectRequest {
            name: "project-a".to_string(),
            description: "Project A".to_string(),
        }))
        .await
        .expect("Failed to create project A");

    client
        .create_project(Request::new(CreateProjectRequest {
            name: "project-b".to_string(),
            description: "Project B".to_string(),
        }))
        .await
        .expect("Failed to create project B");

    // Add node to project-a
    client
        .add_node(Request::new(AddNodeRequest {
            project: "project-a".to_string(),
            content: "Spec A".to_string(),
            kind: SpecNodeKind::Assertion as i32,
            formality_layer: 0,
            metadata: std::collections::HashMap::new(),
        }))
        .await
        .expect("Failed to add node to project A");

    // Add node to project-b
    client
        .add_node(Request::new(AddNodeRequest {
            project: "project-b".to_string(),
            content: "Spec B".to_string(),
            kind: SpecNodeKind::Assertion as i32,
            formality_layer: 0,
            metadata: std::collections::HashMap::new(),
        }))
        .await
        .expect("Failed to add node to project B");

    // List nodes in project-a - should only see "Spec A"
    let nodes_a = client
        .list_nodes(Request::new(ListNodesRequest {
            project: "project-a".to_string(),
            kind_filter: None,
            formality_layer: None,
        }))
        .await
        .expect("Failed to list nodes in project A")
        .into_inner()
        .nodes;

    assert_eq!(nodes_a.len(), 1);
    assert_eq!(nodes_a[0].content, "Spec A");

    // List nodes in project-b - should only see "Spec B"
    let nodes_b = client
        .list_nodes(Request::new(ListNodesRequest {
            project: "project-b".to_string(),
            kind_filter: None,
            formality_layer: None,
        }))
        .await
        .expect("Failed to list nodes in project B")
        .into_inner()
        .nodes;

    assert_eq!(nodes_b.len(), 1);
    assert_eq!(nodes_b[0].content, "Spec B");

    // Cleanup
    client
        .delete_project(Request::new(DeleteProjectRequest {
            name: "project-a".to_string(),
        }))
        .await
        .ok();

    client
        .delete_project(Request::new(DeleteProjectRequest {
            name: "project-b".to_string(),
        }))
        .await
        .ok();
}

