    let result = client
        .import_project(Request::new(ImportProjectRequest {
            name: "imported-test".to_string(),
            description: "Imported project".to_string(),
            spec_directory_path: "/tmp/nonexistent-spec".to_string(),
        }))
        .await;

    assert!(
        result.is_err(),
        "Import should fail for nonexistent directory"
    );
}

