//! Unit tests for storage backends
//!
//! Tests verify:
//! - UDAFModel persistence and loading
//! - Repository persistence and loading
//! - Project existence checks
//! - Project deletion

use specd::storage::{LocalFileBackend, StorageBackend};
use spec_core::data::SpecRepository;
use spec_core::formal::UDAFModel;
use tempfile::TempDir;

#[test]
fn test_local_file_backend_udaf_model() {
    let temp_dir = TempDir::new().expect("Failed to create temp dir");
    let backend = LocalFileBackend::new(temp_dir.path().to_path_buf());

    // Create a UDAFModel with some content
    let mut model = UDAFModel::new(); // Creates U0 automatically
    model
        .add_universe(1, "U1".to_string(), "Layer 1".to_string())
        .expect("Failed to add universe");

    // Save the model
    backend
        .save_udaf_model("test-project", &model)
        .expect("Failed to save UDAFModel");

    // Load it back
    let loaded_model = backend
        .load_udaf_model("test-project")
        .expect("Failed to load UDAFModel");

    // Verify content
    assert_eq!(loaded_model.list_universes().len(), 2); // U0 + U1
}

#[test]
fn test_local_file_backend_repository() {
    let temp_dir = TempDir::new().expect("Failed to create temp dir");
    let backend = LocalFileBackend::new(temp_dir.path().to_path_buf());

    // Create a repository with some nodes
    let mut repo = SpecRepository::new();
    let node_id = repo
        .add_node(
            "Test spec".to_string(),
            spec_core::data::NodeKind::Assertion,
            0,
            std::collections::HashMap::new(),
        )
        .expect("Failed to add node");

    // Save the repository
    backend
        .save_repository("test-project", &repo)
        .expect("Failed to save repository");

    // Load it back
    let loaded_repo = backend
        .load_repository("test-project")
        .expect("Failed to load repository");

    // Verify content
    assert_eq!(loaded_repo.node_count(), 1);
    let nodes = loaded_repo.list_nodes(None);
    assert_eq!(nodes[0].content, "Test spec");
}

#[test]
fn test_local_file_backend_project_existence() {
