//! Unit tests for ProjectManager
//!
//! Tests verify:
//! - Project creation with different storage configs
//! - Project loading and saving
//! - Project switching
//! - Project deletion
//! - Concurrent access safety

use specd::config::StorageConfig;
use specd::project::ProjectManager;
use tempfile::TempDir;

#[test]
fn test_create_and_load_project() {
    let temp_dir = TempDir::new().expect("Failed to create temp dir");
    let mut pm = ProjectManager::new(temp_dir.path().to_path_buf());

    // Create project
    let storage = StorageConfig::LocalFile {
        base_path: temp_dir.path().to_path_buf(),
    };

    pm.create_project(
        "test-project".to_string(),
        "Test description".to_string(),
        storage,
    )
    .expect("Failed to create project");

    // Load project
    let project = pm
        .load_project("test-project")
        .expect("Failed to load project");

    assert_eq!(project.name, "test-project");
    assert_eq!(project.description, "Test description");
    assert_eq!(project.udaf_model.list_universes().len(), 1); // U0
}

#[test]
fn test_switch_project() {
    let temp_dir = TempDir::new().expect("Failed to create temp dir");
    let mut pm = ProjectManager::new(temp_dir.path().to_path_buf());

    let storage = StorageConfig::LocalFile {
        base_path: temp_dir.path().to_path_buf(),
    };

    // Create two projects
    pm.create_project("project-a".to_string(), "A".to_string(), storage.clone())
        .expect("Failed to create project A");
    pm.create_project("project-b".to_string(), "B".to_string(), storage.clone())
        .expect("Failed to create project B");

    // Switch to project A
    pm.switch_project("project-a")
        .expect("Failed to switch to project A");
    assert_eq!(pm.current_project(), Some("project-a"));

    // Switch to project B
    pm.switch_project("project-b")
        .expect("Failed to switch to project B");
    assert_eq!(pm.current_project(), Some("project-b"));

    // Try to switch to nonexistent project
    let result = pm.switch_project("nonexistent");
    assert!(result.is_err());
}

#[test]
fn test_list_projects() {
    let temp_dir = TempDir::new().expect("Failed to create temp dir");
    let mut pm = ProjectManager::new(temp_dir.path().to_path_buf());

    let storage = StorageConfig::LocalFile {
        base_path: temp_dir.path().to_path_buf(),
    };

    // Create multiple projects
    pm.create_project("project-1".to_string(), "1".to_string(), storage.clone())
        .expect("Failed to create project 1");
    pm.create_project("project-2".to_string(), "2".to_string(), storage.clone())
        .expect("Failed to create project 2");
    pm.create_project("project-3".to_string(), "3".to_string(), storage.clone())
        .expect("Failed to create project 3");

    // List projects
    let projects = pm.list_projects().expect("Failed to list projects");

    assert_eq!(projects.len(), 3);
    assert!(projects.iter().any(|p| p.name == "project-1"));
    assert!(projects.iter().any(|p| p.name == "project-2"));
    assert!(projects.iter().any(|p| p.name == "project-3"));
}

#[test]
fn test_delete_project() {
    let temp_dir = TempDir::new().expect("Failed to create temp dir");
    let mut pm = ProjectManager::new(temp_dir.path().to_path_buf());

    let storage = StorageConfig::LocalFile {
        base_path: temp_dir.path().to_path_buf(),
    };

    // Create project
    pm.create_project("test-project".to_string(), "Test".to_string(), storage)
        .expect("Failed to create project");

    // Verify it exists
    assert_eq!(pm.list_projects().unwrap().len(), 1);

    // Delete project
    pm.delete_project("test-project")
        .expect("Failed to delete project");

    // Verify deletion
    assert_eq!(pm.list_projects().unwrap().len(), 0);
}

#[test]
fn test_save_and_reload_project() {
    let temp_dir = TempDir::new().expect("Failed to create temp dir");
    let mut pm = ProjectManager::new(temp_dir.path().to_path_buf());

    let storage = StorageConfig::LocalFile {
        base_path: temp_dir.path().to_path_buf(),
    };

    // Create project
    pm.create_project("test-project".to_string(), "Test".to_string(), storage)
        .expect("Failed to create project");

    // Load project
    let mut project = pm
        .load_project("test-project")
        .expect("Failed to load project");

    // Modify project
    project
        .repository
        .add_node(
            "Test spec".to_string(),
            spec_core::data::NodeKind::Assertion,
            0,
            std::collections::HashMap::new(),
        )
        .expect("Failed to add node");

    // Save project
    pm.save_project(&project)
        .expect("Failed to save project");

    // Reload project
    let reloaded = pm
        .load_project("test-project")
        .expect("Failed to reload project");

    // Verify changes persisted
    assert_eq!(reloaded.repository.node_count(), 1);
}

#[test]
fn test_ensure_default() {
    let temp_dir = TempDir::new().expect("Failed to create temp dir");
    let mut pm = ProjectManager::new(temp_dir.path().to_path_buf());

    // Ensure default project exists
    pm.ensure_default().expect("Failed to ensure default");

    // Should have created "default" project
    let projects = pm.list_projects().expect("Failed to list projects");
    assert!(projects.iter().any(|p| p.name == "default"));

    // Calling again should not fail
    pm.ensure_default().expect("Failed on second call");

