//! UDA/f Model Operations Commands
//!
//! Implements CLI commands for Universe, Domain, AdmissibleSet, and Transform operations.

use crate::proto::spec_oracle_client::SpecOracleClient;
use crate::proto::*;
use anyhow::{Context, Result};
use tonic::Request;

// ==========================================
// Universe Operations
// ==========================================

pub async fn execute_universe_create(
    client: &mut SpecOracleClient<tonic::transport::Channel>,
    layer: u32,
    name: String,
    description: String,
) -> Result<()> {
    let req = CreateUniverseRequest {
        layer,
        name: name.clone(),
        description: description.clone(),
    };

    let resp = client
        .create_universe(Request::new(req))
        .await
        .context("Failed to create universe")?;

    let universe = resp
        .into_inner()
        .universe
        .context("No universe returned")?;

    println!("✅ Created Universe:");
    println!("  ID: {}", universe.id);
    println!("  Layer: U{}", universe.layer);
    println!("  Name: {}", universe.name);
    println!("  Description: {}", universe.description);

    Ok(())
}

pub async fn execute_universe_get(
    client: &mut SpecOracleClient<tonic::transport::Channel>,
    id: String,
) -> Result<()> {
    let req = GetUniverseRequest { id: id.clone() };

    let resp = client
        .get_universe(Request::new(req))
        .await
        .context("Failed to get universe")?;

    let universe = resp
        .into_inner()
        .universe
        .context("Universe not found")?;

    println!("Universe {}:", universe.id);
    println!("  Layer: U{}", universe.layer);
    println!("  Name: {}", universe.name);
    println!("  Description: {}", universe.description);

    if !universe.metadata.is_empty() {
        println!("  Metadata:");
        for (key, value) in &universe.metadata {
            println!("    {}: {}", key, value);
        }
    }

    Ok(())
}

pub async fn execute_universe_list(
    client: &mut SpecOracleClient<tonic::transport::Channel>,
) -> Result<()> {
    let req = ListUniversesRequest {};

    let resp = client
        .list_universes(Request::new(req))
        .await
        .context("Failed to list universes")?;

    let universes = resp.into_inner().universes;

    if universes.is_empty() {
        println!("No universes found (only U0 exists by default)");
        return Ok(());
    }

    println!("Universes ({}):", universes.len());
    for universe in universes {
        println!(
            "  U{} ({}) - {} - {}",
            universe.layer, universe.id, universe.name, universe.description
        );
    }

    Ok(())
}

pub async fn execute_universe_delete(
    client: &mut SpecOracleClient<tonic::transport::Channel>,
    id: String,
) -> Result<()> {
    let req = DeleteUniverseRequest { id: id.clone() };

    client
        .delete_universe(Request::new(req))
        .await
        .context("Failed to delete universe")?;

    println!("✅ Deleted universe: {}", id);

    Ok(())
}

// ==========================================
// Domain Operations
// ==========================================

pub async fn execute_domain_create(
    client: &mut SpecOracleClient<tonic::transport::Channel>,
    universe_id: String,
    name: String,
    description: String,
) -> Result<()> {
    let req = CreateDomainRequest {
        universe_id: universe_id.clone(),
        name: name.clone(),
        description: description.clone(),
        boundary_constraints: vec![], // Empty for now
    };

    let resp = client
        .create_domain(Request::new(req))
        .await
        .context("Failed to create domain")?;

    let domain = resp.into_inner().domain.context("No domain returned")?;

    println!("✅ Created Domain:");
    println!("  ID: {}", domain.id);
    println!("  Universe: {}", domain.universe_id);
    println!("  Name: {}", domain.name);
    println!("  Description: {}", domain.description);

    Ok(())
}

pub async fn execute_domain_get(
    client: &mut SpecOracleClient<tonic::transport::Channel>,
    id: String,
) -> Result<()> {
    let req = GetDomainRequest { id: id.clone() };

    let resp = client
        .get_domain(Request::new(req))
        .await
        .context("Failed to get domain")?;

    let domain = resp.into_inner().domain.context("Domain not found")?;

    println!("Domain {}:", domain.id);
    println!("  Universe: {}", domain.universe_id);
    println!("  Name: {}", domain.name);
    println!("  Description: {}", domain.description);
    println!(
        "  Boundary Constraints: {}",
        domain.boundary_constraints.len()
    );

    Ok(())
}

pub async fn execute_domain_list(
    client: &mut SpecOracleClient<tonic::transport::Channel>,
    universe_id: Option<String>,
) -> Result<()> {
    let req = ListDomainsRequest {
        universe_id: universe_id.clone(),
    };

    let resp = client
        .list_domains(Request::new(req))
        .await
        .context("Failed to list domains")?;

    let domains = resp.into_inner().domains;

    if domains.is_empty() {
        println!("No domains found");
        return Ok(());
    }

    println!("Domains ({}):", domains.len());
    for domain in domains {
        println!("  {} - {} (Universe: {})", domain.id, domain.name, domain.universe_id);
        println!("    {}", domain.description);
    }

    Ok(())
}

// ==========================================
// AdmissibleSet Operations
// ==========================================

pub async fn execute_admissible_set_create(
    client: &mut SpecOracleClient<tonic::transport::Channel>,
    spec_id: String,
    constraints: Vec<String>, // Simplified: just constraint descriptions
) -> Result<()> {
    // Convert string constraints to proto Constraint messages
    let proto_constraints = constraints
        .into_iter()
        .map(|desc| UdafConstraint {
            formal: desc.clone(),
            kind: 0, // UNIVERSAL by default
            description: desc,
        })
        .collect();

    let req = CreateAdmissibleSetRequest {
        spec_id: spec_id.clone(),
        constraints: proto_constraints,
        contradicts: vec![], // Empty for now
    };

    let resp = client
        .create_admissible_set(Request::new(req))
        .await
        .context("Failed to create admissible set")?;

    let admissible_set = resp
        .into_inner()
        .admissible_set
        .context("No admissible set returned")?;

    println!("✅ Created AdmissibleSet:");
    println!("  Spec ID: {}", admissible_set.spec_id);
    println!("  Constraints: {}", admissible_set.constraints.len());

    Ok(())
}

pub async fn execute_admissible_set_get(
    client: &mut SpecOracleClient<tonic::transport::Channel>,
    spec_id: String,
) -> Result<()> {
    let req = GetAdmissibleSetRequest {
        spec_id: spec_id.clone(),
    };

    let resp = client
        .get_admissible_set(Request::new(req))
        .await
        .context("Failed to get admissible set")?;

    let admissible_set = resp
        .into_inner()
        .admissible_set
        .context("AdmissibleSet not found")?;

    println!("AdmissibleSet for {}:", admissible_set.spec_id);
    println!("  Constraints ({}):", admissible_set.constraints.len());
    for constraint in &admissible_set.constraints {
        println!("    - {}", constraint.description);
    }

    if !admissible_set.contradicts.is_empty() {
        println!("  Contradicts:");
        for spec_id in &admissible_set.contradicts {
            println!("    - {}", spec_id);
        }
    }

    Ok(())
}

pub async fn execute_admissible_set_list(
    client: &mut SpecOracleClient<tonic::transport::Channel>,
) -> Result<()> {
    let req = ListAdmissibleSetsRequest {};

    let resp = client
        .list_admissible_sets(Request::new(req))
        .await
        .context("Failed to list admissible sets")?;

    let sets = resp.into_inner().admissible_sets;

    if sets.is_empty() {
        println!("No admissible sets found");
        return Ok(());
    }

    println!("AdmissibleSets ({}):", sets.len());
    for set in sets {
        println!(
            "  Spec {} - {} constraint(s)",
            set.spec_id,
            set.constraints.len()
        );
    }

    Ok(())
}

// ==========================================
// Transform Operations
// ==========================================

pub async fn execute_transform_create(
    client: &mut SpecOracleClient<tonic::transport::Channel>,
    source_universe: String,
    target_universe: String,
    kind: String,
) -> Result<()> {
    // Parse kind string to proto enum
    let kind_value = match kind.to_lowercase().as_str() {
        "forward" => 0,  // FORWARD
        "inverse" => 1,  // INVERSE
        "parallel" => 2, // PARALLEL
        _ => {
            anyhow::bail!("Invalid transform kind: {}. Use forward, inverse, or parallel", kind);
        }
    };

    let req = CreateTransformRequest {
        source_universe_id: source_universe.clone(),
        target_universe_id: target_universe.clone(),
        kind: kind_value,
        strategy: 4, // MANUAL by default
        metadata: std::collections::HashMap::new(),
    };

    let resp = client
        .create_transform(Request::new(req))
        .await
        .context("Failed to create transform")?;

    let transform = resp
        .into_inner()
        .transform
        .context("No transform returned")?;

    println!("✅ Created Transform:");
    println!("  ID: {}", transform.id);
    println!(
        "  {} → {}",
        transform.source_universe_id, transform.target_universe_id
    );
    println!("  Kind: {}", kind);

    Ok(())
}

pub async fn execute_transform_get(
    client: &mut SpecOracleClient<tonic::transport::Channel>,
    id: String,
) -> Result<()> {
    let req = GetTransformRequest { id: id.clone() };

    let resp = client
        .get_transform(Request::new(req))
        .await
        .context("Failed to get transform")?;

    let transform = resp.into_inner().transform.context("Transform not found")?;

    println!("Transform {}:", transform.id);
    println!(
        "  {} → {}",
        transform.source_universe_id, transform.target_universe_id
    );
    println!("  Kind: {}", transform.kind);
    println!("  Strategy: {}", transform.strategy);

    Ok(())
}

pub async fn execute_transform_list(
    client: &mut SpecOracleClient<tonic::transport::Channel>,
) -> Result<()> {
    let req = ListTransformsRequest {};

    let resp = client
        .list_transforms(Request::new(req))
        .await
        .context("Failed to list transforms")?;

    let transforms = resp.into_inner().transforms;

    if transforms.is_empty() {
        println!("No transforms found");
        return Ok(());
    }

    println!("Transforms ({}):", transforms.len());
    for transform in transforms {
        println!(
            "  {} → {} ({})",
            transform.source_universe_id, transform.target_universe_id, transform.id
        );
    }

    Ok(())
}

// ==========================================
// Special Operations
// ==========================================

pub async fn execute_construct_u0(
    client: &mut SpecOracleClient<tonic::transport::Channel>,
    artifacts: Vec<String>,
) -> Result<()> {
    let req = ConstructU0Request {
        root_space: Some(UdafRootSpace {
            id: "artifact-bundle".to_string(),
            kind: 0, // ARTIFACT_BUNDLE
            artifact_paths: artifacts.clone(),
            metadata: std::collections::HashMap::new(),
        }),
        execute_transforms: true,
    };

    let resp = client
        .construct_u0(Request::new(req))
        .await
        .context("Failed to construct U0")?;

    let result = resp.into_inner();

    println!("✅ Constructed U0:");
    println!("  Inferred Specifications: {}", result.specs.len());

    for spec in &result.specs {
        println!("\n  Specification:");
        println!("    Content: {}", spec.content);
        println!("    Source Universe: {}", spec.source_universe);
        println!("    Confidence: {:.2}%", spec.confidence * 100.0);
        println!("    Method: {}", spec.extraction_method);
    }

    if let Some(report) = result.ingestion_report {
        println!("\n  Ingestion Report:");
        println!("    Artifacts Processed: {}", report.artifacts_processed);
        println!("    Specs Created: {}", report.specs_created);
    }

    Ok(())
}

pub async fn execute_sync_model(
    client: &mut SpecOracleClient<tonic::transport::Channel>,
) -> Result<()> {
    let req = SyncModelRequest {};

    let resp = client
        .sync_model(Request::new(req))
        .await
        .context("Failed to sync model")?;

    let result = resp.into_inner();

    println!("✅ Model Synced:");
    println!("  Universes Created: {}", result.universes_created);
    println!("  Domains Created: {}", result.domains_created);
    println!("  Transforms Created: {}", result.transforms_created);

    Ok(())
}

pub async fn execute_validate_model(
    client: &mut SpecOracleClient<tonic::transport::Channel>,
) -> Result<()> {
    let req = ValidateModelRequest {};

    let resp = client
        .validate_model(Request::new(req))
        .await
        .context("Failed to validate model")?;

    let result = resp.into_inner();

    if result.valid {
        println!("✅ Model is valid");
        if !result.warnings.is_empty() {
            println!("\n⚠️  Warnings:");
            for warning in &result.warnings {
                println!("  - {}", warning);
            }
        }
    } else {
        println!("❌ Model is invalid");
        if !result.errors.is_empty() {
            println!("\nErrors:");
            for error in &result.errors {
                println!("  - {}", error);
            }
        }
    }

    Ok(())
}

