    name: String,
    description: String,
) -> Result<()> {
    let req = proto::CreateUniverseRequest {
        layer,
        name: name.clone(),
        description: description.clone(),
    };

    let resp = client.create_universe(Request::new(req)).await?;
    let universe = resp.into_inner().universe.unwrap_or_default();

