/// Dispatch API commands via gRPC
async fn dispatch_rpc(
    client: &mut Client,
    rpc_cmd: RpcCommands,
) -> Result<(), Box<dyn std::error::Error>> {
    match rpc_cmd {
        // === UDA/f Model Operations ===
        RpcCommands::CreateUniverse { layer, name, description } => {
            crate::commands::udaf_rpc::execute_universe_create(client, layer, name, description).await?;
        }
        RpcCommands::GetUniverse { id } => {
            crate::commands::udaf_rpc::execute_universe_get(client, id).await?;
        }
        RpcCommands::ListUniverses => {
            crate::commands::udaf_rpc::execute_universe_list(client).await?;
        }
        RpcCommands::DeleteUniverse { id } => {
            crate::commands::udaf_rpc::execute_universe_delete(client, id).await?;
        }
        RpcCommands::CreateDomain { universe, name, description } => {
            crate::commands::udaf_rpc::execute_domain_create(client, universe, name, description).await?;
        }
        RpcCommands::GetDomain { id } => {
            crate::commands::udaf_rpc::execute_domain_get(client, id).await?;
        }
        RpcCommands::ListDomains { universe } => {
            crate::commands::udaf_rpc::execute_domain_list(client, universe).await?;
        }
        RpcCommands::CreateTransform { source, target, kind } => {
            crate::commands::udaf_rpc::execute_transform_create(client, source, target, kind).await?;
        }
        RpcCommands::GetTransform { id } => {
            crate::commands::udaf_rpc::execute_transform_get(client, id).await?;
        }
        RpcCommands::ListTransforms => {
            crate::commands::udaf_rpc::execute_transform_list(client).await?;
        }
        RpcCommands::CreateAdmissibleSet { spec, constraint } => {
            crate::commands::udaf_rpc::execute_admissible_set_create(client, spec, constraint).await?;
        }
        RpcCommands::GetAdmissibleSet { spec } => {
            crate::commands::udaf_rpc::execute_admissible_set_get(client, spec).await?;
        }
        RpcCommands::ListAdmissibleSets => {
            crate::commands::udaf_rpc::execute_admissible_set_list(client).await?;
        }
        RpcCommands::ConstructU0 { artifact } => {
            crate::commands::udaf_rpc::execute_construct_u0(client, artifact).await?;
        }
        RpcCommands::SyncModel => {
            crate::commands::udaf_rpc::execute_sync_model(client).await?;
        }
        RpcCommands::ValidateModel => {
            crate::commands::udaf_rpc::execute_validate_model(client).await?;
        }

        // === Graph Operations ===
        RpcCommands::AddNode { content, kind } => {
            let proto_kind = parse_node_kind(&kind);
            let resp = client
                .add_node(Request::new(proto::AddNodeRequest {
                    content: content.clone(),
                    kind: proto_kind.into(),
                    metadata: HashMap::new(),
                }))
                .await?;
            let node = resp.into_inner().node.unwrap();
            println!("Added node: {}", node.id);
            println!("  Content: {}", node.content);
            println!("  Kind: {}", node_kind_name(node.kind));
        }
        RpcCommands::GetNode { id } => {
            let resp = client
                .get_node(Request::new(proto::GetNodeRequest { id: id.clone() }))
                .await?;
            if let Some(node) = resp.into_inner().node {
                let layer = format_formality_layer(node.formality_layer as u8);
                println!("Node: {}", node.id);
                println!("  Content: {}", node.content);
                println!("  Kind: {}", node_kind_name(node.kind));
                println!("  Layer: {}", layer);
                if !node.metadata.is_empty() {
                    println!("  Metadata:");
                    for (key, value) in &node.metadata {
                        println!("    {}: {}", key, value);
                    }
                }
            } else {
                eprintln!("Node not found: {}", id);
            }
        }
        RpcCommands::ListNodes { kind, layer, status, full, limit, offset } => {
            let kind_filter = kind.as_ref().map(|k| parse_node_kind(k));
            let resp = client
                .list_nodes(Request::new(proto::ListNodesRequest {
                    kind_filter: kind_filter.map(|k| k.into()).unwrap_or(0),
                }))
                .await?;

