use crate::project::{ProjectManager, Project};
use crate::proto;
use crate::model_service::ModelServiceImpl;
use spec_core::data::{EdgeKind, NodeKind, SpecRepository};
use std::sync::{Arc, Mutex};
use tonic::{Request, Response, Status};

pub struct SpecOracleService {
    project_manager: Arc<Mutex<ProjectManager>>,
    model_svc: ModelServiceImpl,
}

impl SpecOracleService {
    pub fn new(project_manager: ProjectManager) -> Result<Self, Box<dyn std::error::Error>> {
        let pm = Arc::new(Mutex::new(project_manager));
        let udaf = UdafServiceImpl::new(pm.clone());
        Ok(Self {
            project_manager: pm,
            udaf,
        })
    }

    /// Get the current project or use the specified project name
    fn get_project(&self, project_name: &str) -> Result<Project, Status> {
        let pm = self.project_manager.lock()
            .map_err(|e| Status::internal(format!("Lock error: {}", e)))?;

        let name = if project_name.is_empty() {
            pm.current_project()
                .ok_or_else(|| Status::failed_precondition("No current project set. Use SwitchProject or specify project name."))?
        } else {
            project_name.to_string()
        };

        pm.load_project(&name)
            .map_err(|e| Status::not_found(format!("Project not found: {}", e)))
    }

    /// Save a project back to storage
    fn save_project(&self, project: &Project) -> Result<(), Status> {
        let pm = self.project_manager.lock()
            .map_err(|e| Status::internal(format!("Lock error: {}", e)))?;

        pm.save_project(project)
            .map_err(|e| Status::internal(format!("Failed to save project: {}", e)))
    }

    /// Add node with explicit formality layer (helper method)
    fn add_node_with_layer(
        repo: &mut SpecRepository,
        content: String,
        kind: NodeKind,
        formality_layer: u8,
        metadata: std::collections::HashMap<String, String>,
    ) -> spec_core::data::SpecNodeData {
        let node = repo.add_node(content, kind, metadata).clone();
        let node_id = node.id.clone();
        repo.update_node_formality(&node_id, formality_layer);
        repo.get_node(&node_id).unwrap().clone()
    }
}

// ==========================================
// Proto conversion helpers
// ==========================================

fn to_proto_node(n: &spec_core::data::SpecNodeData) -> proto::SpecNode {
    proto::SpecNode {
        id: n.id.clone(),
        content: n.content.clone(),
        kind: to_proto_node_kind(n.kind).into(),
        metadata: n.metadata.clone(),
        created_at: n.created_at,
        modified_at: n.modified_at,
        formality_layer: n.formality_layer as u32,
    }
}

fn to_proto_node_kind(k: NodeKind) -> proto::SpecNodeKind {
    match k {
        NodeKind::Assertion => proto::SpecNodeKind::Assertion,
        NodeKind::Constraint => proto::SpecNodeKind::Constraint,
        NodeKind::Scenario => proto::SpecNodeKind::Scenario,
        NodeKind::Definition => proto::SpecNodeKind::Definition,
        NodeKind::Domain => proto::SpecNodeKind::Domain,
    }
}

fn from_proto_node_kind(k: i32) -> NodeKind {
    match proto::SpecNodeKind::try_from(k) {
        Ok(proto::SpecNodeKind::Assertion) => NodeKind::Assertion,
        Ok(proto::SpecNodeKind::Constraint) => NodeKind::Constraint,
        Ok(proto::SpecNodeKind::Scenario) => NodeKind::Scenario,
        Ok(proto::SpecNodeKind::Definition) => NodeKind::Definition,
        Ok(proto::SpecNodeKind::Domain) => NodeKind::Domain,
        _ => NodeKind::Assertion,
    }
}

fn to_proto_edge(e: &spec_core::data::SpecEdgeData, src: &str, tgt: &str) -> proto::SpecEdge {
    proto::SpecEdge {
        id: e.id.clone(),
        source_id: src.to_string(),
        target_id: tgt.to_string(),
        kind: to_proto_edge_kind(e.kind).into(),
        metadata: e.metadata.clone(),
        created_at: e.created_at,
    }
}

fn to_proto_edge_kind(k: EdgeKind) -> proto::SpecEdgeKind {
    match k {
        EdgeKind::Refines => proto::SpecEdgeKind::Refines,
        EdgeKind::DependsOn => proto::SpecEdgeKind::DependsOn,
        EdgeKind::Contradicts => proto::SpecEdgeKind::Contradicts,
        EdgeKind::DerivesFrom => proto::SpecEdgeKind::DerivesFrom,
        EdgeKind::Synonym => proto::SpecEdgeKind::Synonym,
        EdgeKind::Composes => proto::SpecEdgeKind::Composes,
        EdgeKind::Formalizes => proto::SpecEdgeKind::Formalizes,
        EdgeKind::Transform => proto::SpecEdgeKind::Transform,
    }
}

fn from_proto_edge_kind(k: i32) -> EdgeKind {
    match proto::SpecEdgeKind::try_from(k) {
        Ok(proto::SpecEdgeKind::Refines) => EdgeKind::Refines,
        Ok(proto::SpecEdgeKind::DependsOn) => EdgeKind::DependsOn,
        Ok(proto::SpecEdgeKind::Contradicts) => EdgeKind::Contradicts,
        Ok(proto::SpecEdgeKind::DerivesFrom) => EdgeKind::DerivesFrom,
        Ok(proto::SpecEdgeKind::Synonym) => EdgeKind::Synonym,
        Ok(proto::SpecEdgeKind::Composes) => EdgeKind::Composes,
        Ok(proto::SpecEdgeKind::Formalizes) => EdgeKind::Formalizes,
        Ok(proto::SpecEdgeKind::Transform) => EdgeKind::Transform,
        _ => EdgeKind::DependsOn,
    }
}

fn to_proto_storage_backend(config: &crate::config::StorageConfig) -> proto::StorageBackend {
    use crate::config::StorageConfig;
    match config {
        StorageConfig::LocalFile { .. } => proto::StorageBackend::LocalFile,
        StorageConfig::Database { .. } => proto::StorageBackend::Database,
        StorageConfig::S3 { .. } => proto::StorageBackend::S3,
        StorageConfig::Git { .. } => proto::StorageBackend::Git,
    }
}

// ==========================================
// RPC Implementations
// ==========================================

#[tonic::async_trait]
impl proto::spec_oracle_server::SpecOracle for SpecOracleService {
    // ==========================================
    // Project Management RPCs
    // ==========================================

    async fn create_project(
        &self,
        request: Request<proto::CreateProjectRequest>,
    ) -> Result<Response<proto::CreateProjectResponse>, Status> {
        let req = request.into_inner();

        let storage = match req.storage_backend() {
            proto::StorageBackend::LocalFile | proto::StorageBackend::Unspecified => {
                let pm = self.project_manager.lock()
                    .map_err(|e| Status::internal(format!("Lock error: {}", e)))?;
                crate::config::StorageConfig::LocalFile {
                    base_path: pm.base_path().to_path_buf(),
                }
            }
            proto::StorageBackend::Database => {
                return Err(Status::unimplemented("Database storage not yet implemented"));
            }
            proto::StorageBackend::S3 => {
                return Err(Status::unimplemented("S3 storage not yet implemented"));
            }
            proto::StorageBackend::Git => {
                return Err(Status::unimplemented("Git storage not yet implemented"));
            }
        };

        let mut pm = self.project_manager.lock()
            .map_err(|e| Status::internal(format!("Lock error: {}", e)))?;

        pm.create_project(req.name.clone(), req.description, storage)
            .map_err(|e| Status::already_exists(format!("Failed to create project: {}", e)))?;

        let project_info = pm.list_projects()
            .map_err(|e| Status::internal(format!("Failed to list projects: {}", e)))?
            .into_iter()
            .find(|p| p.name == req.name)
            .ok_or_else(|| Status::internal("Project created but not found"))?;

        Ok(Response::new(proto::CreateProjectResponse {
            project: Some(proto::Project {
                name: project_info.name,
                description: project_info.description,
                created_at: project_info.created_at,
