}

/// UDA/f service implementation
///
/// Holds shared state for the UDA/f model and project manager.
/// All operations are delegated here from SpecOracleService.
#[derive(Debug)]
pub struct UdafServiceImpl {
    project_manager: Arc<Mutex<ProjectManager>>,
