   519→// ==========================================
   520→// UDA/f Model Types (Phase 2)
   521→// ==========================================
   522→
   523→// Universe: The space in which specifications are defined (U0, U1, ...)
   524→message UdafUniverse {
   525→  string id = 1;              // e.g., "U0", "U1", "U2"
   526→  string name = 2;            // Human-readable name
   527→  string description = 3;     // What this universe represents
   528→  uint32 layer = 4;           // Layer number (0=root, 1=formal, 2=interface, 3=impl)
   529→  repeated string spec_ids = 5; // Specification IDs in this universe
   530→  map<string, string> metadata = 6;
   531→}
   532→
   533→// Domain: The region a specification covers
   534→message UdafDomain {
   535→  string id = 1;              // UUID
   536→  string name = 2;            // Human-readable name
   537→  string description = 3;     // What this domain covers
   538→  string universe_id = 4;     // Which universe this domain belongs to
   539→  repeated UdafConstraint constraints = 5;  // Domain boundary constraints
   540→  repeated string covered_by = 6;  // Spec IDs that cover this domain
   541→  repeated string subdomain_ids = 7; // Child domain IDs
   542→  map<string, string> metadata = 8;
   543→}
   544→
   545→// AdmissibleSet: The set of allowed implementations for a specification
   546→message UdafAdmissibleSet {
   547→  string spec_id = 1;         // Specification ID (UUID)
   548→  string universe_id = 2;     // Which universe this belongs to
   549→  repeated UdafConstraint constraints = 3;  // Constraints defining membership
   550→  repeated string contradicts = 4;  // Spec IDs this contradicts
   551→  map<string, string> metadata = 5;
   552→}
   553→
   554→// Constraint: A symbolic membership condition
   555→message UdafConstraint {
   556→  string formal = 1;          // Formal representation (e.g., ">= 8")
   557→  UdafConstraintKind kind = 2;
   558→  string description = 3;     // Natural language description
   559→  map<string, string> metadata = 4;
   560→}
   561→
   562→enum UdafConstraintKind {
   563→  UDAF_CONSTRAINT_KIND_UNSPECIFIED = 0;
   564→  UNIVERSAL = 1;     // Must hold for all cases
   565→  EXISTENTIAL = 2;   // Must hold for at least one case
   566→  IMPLICATION = 3;   // If condition then consequence
   567→  EQUIVALENCE = 4;   // Bidirectional implication
   568→}
   569→
   570→// Transform: Mapping between universes
   571→message UdafTransform {
   572→  string id = 1;              // e.g., "f_U1_to_U0"
   573→  string source_universe = 2; // Source universe ID
   574→  string target_universe = 3; // Target universe ID
   575→  string description = 4;     // Human-readable description
   576→  UdafTransformKind kind = 5;
   577→  UdafTransformStrategy strategy = 6;
   578→  map<string, string> metadata = 7;
   579→}
   580→
   581→enum UdafTransformKind {
   582→  UDAF_TRANSFORM_KIND_UNSPECIFIED = 0;
   583→  FORWARD = 1;       // Ui -> Uj (more concrete)
   584→  INVERSE = 2;       // Ui -> U0 (reverse mapping to root)
   585→  PARALLEL = 3;      // Ui -> Uj (different aspects, same layer)
   586→}
   587→
   588→message UdafTransformStrategy {
   589→  string strategy_type = 1;   // "ast_analysis", "nlp_inference", "formal_verification", "type_analysis", "manual"
   590→  map<string, string> config = 2;  // Strategy-specific configuration
   591→}
   592→
   593→// Proof result from verification operations
   594→message UdafProofResult {
   595→  string id = 1;
   596→  UdafProofStatus status = 2;
   597→  string property_type = 3;   // "consistency", "satisfiability", "implication", "completeness", "soundness"
   598→  repeated UdafProofStep steps = 4;
   599→  string method = 5;          // "constraint_solving", "smt_solver", "heuristic"
   600→  map<string, string> metadata = 6;
   601→}
   602→
   603→enum UdafProofStatus {
   604→  UDAF_PROOF_STATUS_UNSPECIFIED = 0;
   605→  PROVEN = 1;        // Property is proven true
   606→  REFUTED = 2;       // Property is proven false
   607→  UNKNOWN = 3;       // Unable to prove or refute
   608→  PENDING = 4;       // Proof attempt in progress
   609→}
   610→
   611→message UdafProofStep {
   612→  string description = 1;
   613→  string justification = 2;
   614→}
