    QueryAtTimestamp {
        /// Unix timestamp (seconds since epoch)
        timestamp: i64,
    },
    /// Show changes between two timestamps
    DiffTimestamps {
        /// Start timestamp (unix seconds)
        from: i64,
        /// End timestamp (unix seconds)
        to: i64,
