        #[arg(short, long)]
        layer: u32,
        /// Universe name (e.g., "TLA+", "gRPC", "Rust")
        #[arg(short, long)]
        name: String,
        /// Universe description
        #[arg(short, long, default_value = "")]
        description: String,
