    /// Get universe details
    GetUniverse {
        /// Universe ID
        id: String,
    },
    /// List all universes
    ListUniverses,
    /// Delete a universe
    DeleteUniverse {
        /// Universe ID
        id: String,
    },

    /// Create a new domain
    CreateDomain {
        /// Universe ID
        #[arg(short, long)]
        universe: String,
        /// Domain name
        #[arg(short, long)]
        name: String,
        /// Domain description
        #[arg(short, long, default_value = "")]
        description: String,
    },
    /// Get domain details
    GetDomain {
        /// Domain ID
        id: String,
    },
    /// List all domains
    ListDomains {
