        #[arg(short, long)]
        name: String,
        /// Domain description
        #[arg(short, long, default_value = "")]
        description: String,
    },
    /// Get domain details
    GetDomain {
        /// Domain ID
        id: String,
    },
    /// List all domains
    ListDomains {
        /// Filter by universe ID
        #[arg(short, long)]
        universe: Option<String>,
    },
    /// Update domain constraints
    UpdateDomainConstraints {
