    let proto_constraints = constraints
        .into_iter()
        .map(|desc| proto::UdafConstraint {
            formal: desc.clone(),
            kind: 1, // UNIVERSAL by default
            description: desc,
            metadata: std::collections::HashMap::new(),
        })
        .collect();

    let req = proto::UpdateDomainConstraintsRequest {
