    println!("Transform {}:", transform.id);
    println!("  {} → {}", transform.source_universe, transform.target_universe);
    println!("  Description: {}", transform.description);
    println!("  Kind: {}", transform.kind);

    Ok(())
}

pub async fn execute_transform_list(
