    13→impl SpecOracleService {
    14→    pub fn new(project_manager: ProjectManager) -> Result<Self, Box<dyn std::error::Error>> {
    15→        let pm = Arc::new(Mutex::new(project_manager));
    16→        let model_svc = ModelServiceImpl::new(pm.clone());
    17→        Ok(Self {
    18→            project_manager: pm,
    19→            model_svc,
