    21→    }
    22→
    23→    /// Get the current project or use the specified project name
    24→    fn get_project(&self, project_name: &str) -> Result<Project, Status> {
    25→        let pm = self.project_manager.lock()
    26→            .map_err(|e| Status::internal(format!("Lock error: {}", e)))?;
    27→
    28→        let name = if project_name.is_empty() {
    29→            pm.current_project()
    30→                .ok_or_else(|| Status::failed_precondition("No current project set. Use SwitchProject or specify project name."))?
    31→        } else {
    32→            project_name.to_string()
    33→        };
    34→
    35→        pm.load_project(&name)
    36→            .map_err(|e| Status::not_found(format!("Project not found: {}", e)))
    37→    }
    38→
    39→    /// Save a project back to storage
    40→    fn save_project(&self, project: &Project) -> Result<(), Status> {
    41→        let pm = self.project_manager.lock()
    42→            .map_err(|e| Status::internal(format!("Lock error: {}", e)))?;
    43→
    44→        pm.save_project(project)
    45→            .map_err(|e| Status::internal(format!("Failed to save project: {}", e)))
    46→    }
    47→
    48→    /// Add node with explicit formality layer (helper method)
    49→    fn add_node_with_layer(
    50→        repo: &mut SpecRepository,
    51→        content: String,
    52→        kind: NodeKind,
    53→        formality_layer: u8,
    54→        metadata: std::collections::HashMap<String, String>,
    55→    ) -> spec_core::data::SpecNodeData {
    56→        let node = repo.add_node(content, kind, metadata).clone();
    57→        let node_id = node.id.clone();
    58→        repo.update_node_formality(&node_id, formality_layer);
    59→        repo.get_node(&node_id).unwrap().clone()
    60→    }
    61→}
