    63→// ==========================================
    64→// Proto conversion helpers
    65→// ==========================================
    66→
    67→fn to_proto_node(n: &spec_core::data::SpecNodeData) -> proto::SpecNode {
    68→    proto::SpecNode {
    69→        id: n.id.clone(),
    70→        content: n.content.clone(),
    71→        kind: to_proto_node_kind(n.kind).into(),
    72→        metadata: n.metadata.clone(),
    73→        created_at: n.created_at,
    74→        modified_at: n.modified_at,
    75→        formality_layer: n.formality_layer as u32,
    76→    }
    77→}
    78→
    79→fn to_proto_node_kind(k: NodeKind) -> proto::SpecNodeKind {
    80→    match k {
    81→        NodeKind::Assertion => proto::SpecNodeKind::Assertion,
    82→        NodeKind::Constraint => proto::SpecNodeKind::Constraint,
    83→        NodeKind::Scenario => proto::SpecNodeKind::Scenario,
    84→        NodeKind::Definition => proto::SpecNodeKind::Definition,
    85→        NodeKind::Domain => proto::SpecNodeKind::Domain,
    86→    }
    87→}
    88→
    89→fn from_proto_node_kind(k: i32) -> NodeKind {
    90→    match proto::SpecNodeKind::try_from(k) {
    91→        Ok(proto::SpecNodeKind::Assertion) => NodeKind::Assertion,
    92→        Ok(proto::SpecNodeKind::Constraint) => NodeKind::Constraint,
    93→        Ok(proto::SpecNodeKind::Scenario) => NodeKind::Scenario,
    94→        Ok(proto::SpecNodeKind::Definition) => NodeKind::Definition,
    95→        Ok(proto::SpecNodeKind::Domain) => NodeKind::Domain,
    96→        _ => NodeKind::Assertion,
    97→    }
    98→}
    99→
   100→fn to_proto_edge(e: &spec_core::data::SpecEdgeData, src: &str, tgt: &str) -> proto::SpecEdge {
   101→    proto::SpecEdge {
   102→        id: e.id.clone(),
   103→        source_id: src.to_string(),
   104→        target_id: tgt.to_string(),
   105→        kind: to_proto_edge_kind(e.kind).into(),
   106→        metadata: e.metadata.clone(),
   107→        created_at: e.created_at,
   108→    }
   109→}
   110→
   111→fn to_proto_edge_kind(k: EdgeKind) -> proto::SpecEdgeKind {
   112→    match k {
   113→        EdgeKind::Refines => proto::SpecEdgeKind::Refines,
   114→        EdgeKind::DependsOn => proto::SpecEdgeKind::DependsOn,
   115→        EdgeKind::Contradicts => proto::SpecEdgeKind::Contradicts,
   116→        EdgeKind::DerivesFrom => proto::SpecEdgeKind::DerivesFrom,
   117→        EdgeKind::Synonym => proto::SpecEdgeKind::Synonym,
   118→        EdgeKind::Composes => proto::SpecEdgeKind::Composes,
   119→        EdgeKind::Formalizes => proto::SpecEdgeKind::Formalizes,
   120→        EdgeKind::Transform => proto::SpecEdgeKind::Transform,
   121→    }
   122→}
   123→
   124→fn from_proto_edge_kind(k: i32) -> EdgeKind {
   125→    match proto::SpecEdgeKind::try_from(k) {
   126→        Ok(proto::SpecEdgeKind::Refines) => EdgeKind::Refines,
   127→        Ok(proto::SpecEdgeKind::DependsOn) => EdgeKind::DependsOn,
   128→        Ok(proto::SpecEdgeKind::Contradicts) => EdgeKind::Contradicts,
   129→        Ok(proto::SpecEdgeKind::DerivesFrom) => EdgeKind::DerivesFrom,
   130→        Ok(proto::SpecEdgeKind::Synonym) => EdgeKind::Synonym,
   131→        Ok(proto::SpecEdgeKind::Composes) => EdgeKind::Composes,
   132→        Ok(proto::SpecEdgeKind::Formalizes) => EdgeKind::Formalizes,
   133→        Ok(proto::SpecEdgeKind::Transform) => EdgeKind::Transform,
   134→        _ => EdgeKind::DependsOn,
   135→    }
   136→}
