   158→    async fn create_project(
   159→        &self,
   160→        request: Request<proto::CreateProjectRequest>,
   161→    ) -> Result<Response<proto::CreateProjectResponse>, Status> {
   162→        let req = request.into_inner();
   163→
   164→        let storage = match req.storage_backend() {
   165→            proto::StorageBackend::LocalFile | proto::StorageBackend::Unspecified => {
   166→                let pm = self.project_manager.lock()
   167→                    .map_err(|e| Status::internal(format!("Lock error: {}", e)))?;
   168→                crate::config::StorageConfig::LocalFile {
   169→                    base_path: pm.base_path().to_path_buf(),
   170→                }
   171→            }
   172→            proto::StorageBackend::Database => {
   173→                return Err(Status::unimplemented("Database storage not yet implemented"));
   174→            }
   175→            proto::StorageBackend::S3 => {
   176→                return Err(Status::unimplemented("S3 storage not yet implemented"));
   177→            }
   178→            proto::StorageBackend::Git => {
   179→                return Err(Status::unimplemented("Git storage not yet implemented"));
   180→            }
   181→        };
   182→
   183→        let mut pm = self.project_manager.lock()
   184→            .map_err(|e| Status::internal(format!("Lock error: {}", e)))?;
   185→
   186→        pm.create_project(req.name.clone(), req.description, storage)
   187→            .map_err(|e| Status::already_exists(format!("Failed to create project: {}", e)))?;
   188→
   189→        let project_info = pm.list_projects()
   190→            .map_err(|e| Status::internal(format!("Failed to list projects: {}", e)))?
   191→            .into_iter()
   192→            .find(|p| p.name == req.name)
   193→            .ok_or_else(|| Status::internal("Project created but not found"))?;
   194→
   195→        Ok(Response::new(proto::CreateProjectResponse {
   196→            project: Some(proto::Project {
   197→                name: project_info.name,
   198→                description: project_info.description,
   199→                created_at: project_info.created_at,
   200→                node_count: project_info.node_count as u32,
   201→                edge_count: project_info.edge_count as u32,
   202→                storage: to_proto_storage_backend(&project_info.storage).into(),
   203→            }),
   204→        }))
   205→    }
