   301→    }
   302→
   303→    async fn import_project(
   304→        &self,
   305→        request: Request<proto::ImportProjectRequest>,
   306→    ) -> Result<Response<proto::ImportProjectResponse>, Status> {
   307→        let req = request.into_inner();
   308→        let spec_dir = std::path::PathBuf::from(&req.spec_directory_path);
   309→
   310→        let mut pm = self.project_manager.lock()
