   325→
   326→        Ok(Response::new(proto::ImportProjectResponse {
   327→            project: Some(proto::Project {
   328→                name: project_info.name,
   329→                description: project_info.description,
   330→                created_at: project_info.created_at,
   331→                node_count: project_info.node_count as u32,
   332→                edge_count: project_info.edge_count as u32,
   333→                storage: to_proto_storage_backend(&project_info.storage).into(),
