   341→    // ==========================================
   342→    // Node Operations
   343→    // ==========================================
   344→
   345→    async fn add_node(
   346→        &self,
   347→        request: Request<proto::AddNodeRequest>,
   348→    ) -> Result<Response<proto::AddNodeResponse>, Status> {
   349→        let req = request.into_inner();
   350→        let mut project = self.get_project("")?; // Use current project for now
   351→
   352→        let formality_layer = req.metadata.get("formality_layer")
   353→            .and_then(|s| s.parse::<u8>().ok())
   354→            .unwrap_or(0);
   355→
   356→        let node = Self::add_node_with_layer(
   357→            &mut project.repository,
   358→            req.content,
   359→            from_proto_node_kind(req.kind),
   360→            formality_layer,
   361→            req.metadata,
   362→        );
   363→
   364→        self.save_project(&project)?;
   365→
   366→        Ok(Response::new(proto::AddNodeResponse {
   367→            node: Some(to_proto_node(&node)),
   368→        }))
   369→    }
   370→
   371→    async fn get_node(
   372→        &self,
   373→        request: Request<proto::GetNodeRequest>,
   374→    ) -> Result<Response<proto::GetNodeResponse>, Status> {
   375→        let req = request.into_inner();
   376→        let project = self.get_project("")?;
   377→
   378→        let node = project.repository
   379→            .get_node(&req.id)
   380→            .ok_or_else(|| Status::not_found(format!("Node {} not found", req.id)))?;
   381→
   382→        Ok(Response::new(proto::GetNodeResponse {
   383→            node: Some(to_proto_node(node)),
   384→        }))
   385→    }
   386→
   387→    async fn list_nodes(
   388→        &self,
   389→        request: Request<proto::ListNodesRequest>,
   390→    ) -> Result<Response<proto::ListNodesResponse>, Status> {
   391→        let req = request.into_inner();
   392→        let project = self.get_project("")?;
   393→
   394→        let filter = if req.kind_filter == 0 {
   395→            None
   396→        } else {
   397→            Some(from_proto_node_kind(req.kind_filter))
   398→        };
   399→
   400→        let nodes: Vec<proto::SpecNode> = project.repository
   401→            .list_nodes(filter)
   402→            .into_iter()
   403→            .map(to_proto_node)
