     1→/// SpecRepository: Pure data persistence layer for specification graph
     2→///
     3→/// This module contains ALL pure data operations:
     4→/// - CRUD on nodes and edges
     5→/// - Graph traversal and queries
     6→/// - Search and filtering
     7→/// - Test coverage and compliance calculation
     8→/// - Temporal queries (versioning, history, diff)
     9→/// - Serialization (JSON, DOT)
    10→///
    11→/// ARCHITECTURAL CONSTRAINT:
    12→/// NO imports from crate::formal:: module allowed here.
    13→/// This is pure data layer - formal verification belongs in UDAFModel.
    14→use chrono::Utc;
    15→use petgraph::graph::{DiGraph, EdgeIndex, NodeIndex};
    16→use petgraph::visit::EdgeRef;
    17→use petgraph::Direction;
    18→use serde::{Deserialize, Serialize};
    19→use std::collections::HashMap;
    20→use uuid::Uuid;
    21→
    22→use super::*; // Import data module types
    23→
    24→/// Pure data repository for specification graph
    25→#[derive(Debug, Clone, Serialize, Deserialize)]
    26→pub struct SpecRepository {
    27→    graph: DiGraph<SpecNodeData, SpecEdgeData>,
    28→    #[serde(skip)]
    29→    id_to_index: HashMap<String, NodeIndex>,
    30→    #[serde(skip)]
    31→    edge_id_to_index: HashMap<String, EdgeIndex>,
    32→}
    33→
    34→impl Default for SpecRepository {
    35→    fn default() -> Self {
    36→        Self::new()
    37→    }
    38→}
    39→
    40→impl SpecRepository {
    41→    pub fn new() -> Self {
    42→        Self {
    43→            graph: DiGraph::new(),
    44→            id_to_index: HashMap::new(),
    45→            edge_id_to_index: HashMap::new(),
    46→        }
    47→    }
    48→
    49→    /// Rebuild lookup indices after deserialization.
    50→    pub fn rebuild_indices(&mut self) {
    51→        self.id_to_index.clear();
    52→        self.edge_id_to_index.clear();
    53→        for idx in self.graph.node_indices() {
    54→            let node = &self.graph[idx];
    55→            self.id_to_index.insert(node.id.clone(), idx);
    56→        }
    57→        for idx in self.graph.edge_indices() {
    58→            let edge = &self.graph[idx];
    59→            self.edge_id_to_index.insert(edge.id.clone(), idx);
    60→        }
    61→    }
    62→
    63→    // ========================================================================
    64→    // Node operations
    65→    // ========================================================================
    66→
    67→    pub fn add_node(
    68→        &mut self,
    69→        content: String,
    70→        kind: NodeKind,
    71→        metadata: HashMap<String, String>,
    72→    ) -> &SpecNodeData {
    73→        let id = Uuid::new_v4().to_string();
    74→        let now = Utc::now().timestamp();
    75→        let data = SpecNodeData {
    76→            id: id.clone(),
    77→            content,
    78→            kind,
    79→            metadata,
    80→            created_at: now,
    81→            modified_at: now,
    82→            formality_layer: 0, // Default to natural language
    83→        };
    84→        let idx = self.graph.add_node(data);
    85→        self.id_to_index.insert(id, idx);
    86→        &self.graph[idx]
    87→    }
    88→
    89→    /// Add a node from loaded data (preserves existing ID and timestamps)
    90→    pub fn add_node_from_loaded(&mut self, node: SpecNodeData) -> String {
    91→        let id = node.id.clone();
    92→        let idx = self.graph.add_node(node);
    93→        self.id_to_index.insert(id.clone(), idx);
    94→        id
    95→    }
    96→
    97→    pub fn get_node(&self, id: &str) -> Option<&SpecNodeData> {
    98→        self.id_to_index.get(id).map(|&idx| &self.graph[idx])
    99→    }
   100→
   101→    /// Find a node by content and kind (for deduplication)
   102→    pub fn find_node_by_content(&self, content: &str, kind: NodeKind) -> Option<&SpecNodeData> {
   103→        self.graph
   104→            .node_weights()
   105→            .find(|n| n.content == content && n.kind == kind)
   106→    }
   107→
   108→    pub fn update_node_formality(&mut self, id: &str, formality_layer: u8) -> bool {
   109→        if let Some(&idx) = self.id_to_index.get(id)
   110→            && let Some(node) = self.graph.node_weight_mut(idx) {
   111→                node.formality_layer = formality_layer;
   112→                node.modified_at = Utc::now().timestamp();
   113→                return true;
   114→            }
   115→        false
   116→    }
   117→
   118→    pub fn update_node_metadata(
   119→        &mut self,
   120→        id: &str,
   121→        key: String,
   122→        value: String,
   123→    ) -> Option<SpecNodeData> {
   124→        if let Some(&idx) = self.id_to_index.get(id)
   125→            && let Some(node) = self.graph.node_weight_mut(idx) {
   126→                node.metadata.insert(key, value);
   127→                node.modified_at = Utc::now().timestamp();
   128→                return Some(node.clone());
   129→            }
   130→        None
   131→    }
   132→
   133→    pub fn remove_node(&mut self, id: &str) -> Option<SpecNodeData> {
   134→        if let Some(&idx) = self.id_to_index.get(id) {
   135→            // Remove related edge index entries
   136→            let edge_indices: Vec<EdgeIndex> = self
   137→                .graph
   138→                .edges_directed(idx, Direction::Outgoing)
   139→                .chain(self.graph.edges_directed(idx, Direction::Incoming))
   140→                .map(|e| e.id())
   141→                .collect();
   142→            for eidx in edge_indices {
   143→                if let Some(edge_data) = self.graph.edge_weight(eidx) {
   144→                    self.edge_id_to_index.remove(&edge_data.id);
   145→                }
   146→            }
   147→
   148→            let data = self.graph.remove_node(idx)?;
   149→            self.id_to_index.remove(&data.id);
   150→
   151→            // After removal petgraph may swap indices; rebuild to stay consistent.
   152→            self.rebuild_indices();
   153→            Some(data)
   154→        } else {
   155→            None
   156→        }
   157→    }
   158→
   159→    pub fn list_nodes(&self, kind_filter: Option<NodeKind>) -> Vec<&SpecNodeData> {
   160→        self.graph
   161→            .node_weights()
   162→            .filter(|n| kind_filter.is_none() || Some(n.kind) == kind_filter)
   163→            .collect()
   164→    }
   165→
   166→    // ========================================================================
   167→    // Edge operations
   168→    // ========================================================================
   169→
   170→    pub fn add_edge(
   171→        &mut self,
   172→        source_id: &str,
   173→        target_id: &str,
   174→        kind: EdgeKind,
   175→        metadata: HashMap<String, String>,
   176→    ) -> Result<&SpecEdgeData, GraphError> {
   177→        let &src_idx = self
   178→            .id_to_index
   179→            .get(source_id)
   180→            .ok_or_else(|| GraphError::NodeNotFound(source_id.to_string()))?;
   181→        let &tgt_idx = self
   182→            .id_to_index
   183→            .get(target_id)
   184→            .ok_or_else(|| GraphError::NodeNotFound(target_id.to_string()))?;
   185→
   186→        let id = Uuid::new_v4().to_string();
   187→        let now = Utc::now().timestamp();
   188→        let data = SpecEdgeData {
   189→            id: id.clone(),
   190→            kind,
   191→            metadata,
   192→            created_at: now,
   193→        };
   194→        let eidx = self.graph.add_edge(src_idx, tgt_idx, data);
   195→        self.edge_id_to_index.insert(id, eidx);
   196→        Ok(&self.graph[eidx])
   197→    }
   198→
   199→    /// Add an edge from loaded data (preserves existing ID and timestamps)
   200→    pub fn add_edge_from_loaded(&mut self, edge: Edge) -> Result<String, GraphError> {
   201→        let &src_idx = self
   202→            .id_to_index
   203→            .get(&edge.source)
   204→            .ok_or_else(|| GraphError::NodeNotFound(edge.source.clone()))?;
   205→        let &tgt_idx = self
   206→            .id_to_index
   207→            .get(&edge.target)
   208→            .ok_or_else(|| GraphError::NodeNotFound(edge.target.clone()))?;
   209→
   210→        let id = edge.data.id.clone();
   211→        let eidx = self.graph.add_edge(src_idx, tgt_idx, edge.data);
   212→        self.edge_id_to_index.insert(id.clone(), eidx);
   213→        Ok(id)
   214→    }
   215→
   216→    pub fn remove_edge(&mut self, id: &str) -> Option<SpecEdgeData> {
   217→        if let Some(&eidx) = self.edge_id_to_index.get(id) {
   218→            let data = self.graph.remove_edge(eidx)?;
   219→            self.edge_id_to_index.remove(&data.id);
   220→            // Edge removal can invalidate other edge indices; rebuild.
   221→            self.rebuild_indices();
   222→            Some(data)
   223→        } else {
   224→            None
   225→        }
   226→    }
   227→
   228→    pub fn list_edges(&self, node_id: Option<&str>) -> Vec<(&SpecEdgeData, &str, &str)> {
   229→        self.graph
   230→            .edge_indices()
   231→            .filter_map(|eidx| {
   232→                let (src_idx, tgt_idx) = self.graph.edge_endpoints(eidx)?;
   233→                let edge_data = &self.graph[eidx];
   234→                let src_data = &self.graph[src_idx];
   235→                let tgt_data = &self.graph[tgt_idx];
   236→                if let Some(nid) = node_id
   237→                    && src_data.id != nid && tgt_data.id != nid {
   238→                        return None;
   239→                    }
   240→                Some((edge_data, src_data.id.as_str(), tgt_data.id.as_str()))
   241→            })
   242→            .collect()
   243→    }
   244→
   245→    pub fn find_edge(
   246→        &self,
   247→        source_id: &str,
   248→        target_id: &str,
   249→        kind: Option<EdgeKind>,
   250→    ) -> Option<&SpecEdgeData> {
   251→        let src_idx = self.id_to_index.get(source_id)?;
   252→        let tgt_idx = self.id_to_index.get(target_id)?;
   253→
   254→        self.graph
   255→            .edges_connecting(*src_idx, *tgt_idx)
   256→            .find(|e| kind.is_none() || Some(self.graph[e.id()].kind) == kind)
   257→            .map(|e| &self.graph[e.id()])
   258→    }
   259→
   260→    pub fn node_count(&self) -> usize {
   261→        self.graph.node_count()
   262→    }
   263→
   264→    pub fn edge_count(&self) -> usize {
   265→        self.graph.edge_count()
   266→    }
   267→
   268→    /// Iterator over all nodes (for serialization)
   269→    pub fn nodes(&self) -> impl Iterator<Item = &SpecNodeData> {
   270→        self.graph.node_weights()
   271→    }
   272→
   273→    /// Iterator over all edges with source/target IDs (for serialization)
   274→    pub fn edges(&self) -> impl Iterator<Item = Edge> + '_ {
   275→        self.graph.edge_indices().filter_map(move |eidx| {
   276→            let (src_idx, tgt_idx) = self.graph.edge_endpoints(eidx)?;
   277→            let edge_data = self.graph[eidx].clone();
   278→            let source = self.graph[src_idx].id.clone();
   279→            let target = self.graph[tgt_idx].id.clone();
   280→            Some(Edge {
   281→                source,
   282→                target,
   283→                data: edge_data,
   284→            })
   285→        })
   286→    }
   287→
   288→    // ========================================================================
   289→    // Search and filtering
   290→    // ========================================================================
   291→
   292→    /// Search nodes by content substring (case-insensitive).
   293→    pub fn search(&self, query: &str) -> Vec<&SpecNodeData> {
   294→        let q = query.to_lowercase();
   295→        self.graph
   296→            .node_weights()
   297→            .filter(|n| n.content.to_lowercase().contains(&q))
   298→            .collect()
   299→    }
   300→
   301→    /// Filter nodes by formality layer.
   302→    pub fn filter_by_layer(&self, min_layer: u8, max_layer: u8) -> Vec<&SpecNodeData> {
   303→        self.graph
   304→            .node_weights()
   305→            .filter(|n| n.formality_layer >= min_layer && n.formality_layer <= max_layer)
   306→            .collect()
   307→    }
   308→
   309→    // ========================================================================
   310→    // Relationship traversal
   311→    // ========================================================================
   312→
   313→    /// Trace all relationships for a node, returning a hierarchical structure.
   314→    /// Returns tuples of (node, edge_kind, direction) where direction is "outgoing" or "incoming".
   315→    pub fn trace_relationships(
   316→        &self,
   317→        node_id: &str,
   318→        max_depth: usize,
   319→    ) -> Vec<(SpecNodeData, EdgeKind, String, usize)> {
   320→        let mut result = Vec::new();
   321→        let mut visited = std::collections::HashSet::new();
   322→
   323→        if let Some(&start_idx) = self.id_to_index.get(node_id) {
   324→            visited.insert(start_idx);
   325→            self.trace_recursive(start_idx, max_depth, 0, &mut visited, &mut result);
   326→        }
   327→
   328→        result
   329→    }
   330→
   331→    fn trace_recursive(
   332→        &self,
   333→        idx: NodeIndex,
   334→        max_depth: usize,
   335→        current_depth: usize,
   336→        visited: &mut std::collections::HashSet<NodeIndex>,
   337→        result: &mut Vec<(SpecNodeData, EdgeKind, String, usize)>,
   338→    ) {
   339→        if max_depth > 0 && current_depth >= max_depth {
   340→            return;
   341→        }
   342→
   343→        // Traverse outgoing edges
   344→        for edge in self.graph.edges_directed(idx, Direction::Outgoing) {
   345→            let target_idx = edge.target();
   346→            let edge_data = &self.graph[edge.id()];
   347→            let target_node = &self.graph[target_idx];
   348→
   349→            result.push((
   350→                target_node.clone(),
   351→                edge_data.kind,
   352→                "outgoing".to_string(),
   353→                current_depth + 1,
   354→            ));
   355→
   356→            if !visited.contains(&target_idx) {
   357→                visited.insert(target_idx);
   358→                self.trace_recursive(target_idx, max_depth, current_depth + 1, visited, result);
   359→            }
   360→        }
   361→
   362→        // Traverse incoming edges
   363→        for edge in self.graph.edges_directed(idx, Direction::Incoming) {
   364→            let source_idx = edge.source();
   365→            let edge_data = &self.graph[edge.id()];
   366→            let source_node = &self.graph[source_idx];
   367→
   368→            result.push((
   369→                source_node.clone(),
   370→                edge_data.kind,
   371→                "incoming".to_string(),
   372→                current_depth + 1,
   373→            ));
   374→
   375→            if !visited.contains(&source_idx) {
   376→                visited.insert(source_idx);
   377→                self.trace_recursive(source_idx, max_depth, current_depth + 1, visited, result);
   378→            }
   379→        }
   380→    }
   381→
   382→    /// Find all formalizations of a given node (nodes it formalizes to).
   383→    pub fn find_formalizations(&self, node_id: &str) -> Vec<&SpecNodeData> {
   384→        if let Some(&idx) = self.id_to_index.get(node_id) {
   385→            self.graph
   386→                .edges_directed(idx, Direction::Outgoing)
   387→                .filter(|e| self.graph[e.id()].kind == EdgeKind::Formalizes)
   388→                .map(|e| &self.graph[e.target()])
   389→                .collect()
   390→        } else {
   391→            Vec::new()
   392→        }
   393→    }
   394→
   395→    /// Find the natural language source for a formalized node (reverse of formalizations).
   396→    pub fn find_natural_source(&self, node_id: &str) -> Vec<&SpecNodeData> {
   397→        if let Some(&idx) = self.id_to_index.get(node_id) {
   398→            self.graph
   399→                .edges_directed(idx, Direction::Incoming)
   400→                .filter(|e| self.graph[e.id()].kind == EdgeKind::Formalizes)
   401→                .map(|e| &self.graph[e.source()])
   402→                .collect()
   403→        } else {
   404→            Vec::new()
   405→        }
   406→    }
