   875→    /// Query graph state at a specific timestamp.
   876→    /// Returns nodes and edges that existed at that time.
   877→    pub fn query_at_timestamp(&self, timestamp: i64) -> TemporalSnapshot {
   878→        let nodes: Vec<SpecNodeData> = self
   879→            .graph
   880→            .node_weights()
   881→            .filter(|n| n.created_at <= timestamp)
   882→            .cloned()
   883→            .collect();
   884→
   885→        let edges: Vec<SpecEdgeData> = self
   886→            .graph
   887→            .edge_indices()
   888→            .filter_map(|eidx| {
   889→                let edge = &self.graph[eidx];
   890→                if edge.created_at <= timestamp {
   891→                    Some(edge.clone())
   892→                } else {
   893→                    None
   894→                }
   895→            })
   896→            .collect();
   897→
   898→        let node_count = nodes.len();
   899→        let edge_count = edges.len();
   900→
   901→        TemporalSnapshot {
   902→            timestamp,
   903→            nodes,
   904→            edges,
   905→            node_count,
   906→            edge_count,
   907→        }
   908→    }
