   983→    /// Get evolution history of a specific node.
   984→    /// Returns timeline of changes to the node.
   985→    pub fn get_node_history(&self, node_id: &str) -> Option<NodeHistory> {
   986→        let node = self.get_node(node_id)?;
   987→
   988→        let mut events = Vec::new();
   989→
   990→        // Creation event
   991→        events.push(HistoryEvent {
   992→            timestamp: node.created_at,
   993→            event_type: "created".to_string(),
   994→            description: format!("Node created: {}", node.content),
   995→        });
   996→
   997→        // Modification event (if modified after creation)
   998→        if node.modified_at > node.created_at {
   999→            events.push(HistoryEvent {
  1000→                timestamp: node.modified_at,
  1001→                event_type: "modified".to_string(),
  1002→                description: "Node content or metadata modified".to_string(),
  1003→            });
  1004→        }
  1005→
  1006→        // Edge creation events
  1007→        if let Some(&idx) = self.id_to_index.get(node_id) {
  1008→            for edge in self
  1009→                .graph
  1010→                .edges_directed(idx, Direction::Outgoing)
  1011→                .chain(self.graph.edges_directed(idx, Direction::Incoming))
  1012→            {
  1013→                let edge_data = &self.graph[edge.id()];
  1014→                events.push(HistoryEvent {
  1015→                    timestamp: edge_data.created_at,
  1016→                    event_type: "edge_added".to_string(),
  1017→                    description: format!("Edge added: {:?}", edge_data.kind),
  1018→                });
  1019→            }
  1020→        }
  1021→
  1022→        // Sort events by timestamp
  1023→        events.sort_by_key(|e| e.timestamp);
  1024→
  1025→        Some(NodeHistory {
  1026→            node: node.clone(),
  1027→            events,
  1028→        })
  1029→    }
