    39→    /// Check if inferred spec has sufficient semantic quality
    40→    fn is_high_quality_spec(spec: &InferredSpecification) -> bool {
    41→        let content = &spec.content;
    42→
    43→        // Skip low-quality test assertions that are just code artifacts
    44→        // Examples: "Invariant: g.node_count(), 1", "Invariant: fetched.kind, NodeKind::Assertion"
    45→        if content.starts_with("Invariant: ") {
    46→            // Reject if it contains Rust syntax (it's code, not a spec)
    47→            let rust_syntax_markers = [
    48→                ".iter()", ".any(", ".contains(", ".len()", ".get(",
    49→                "!(", "||", "&&", ">", "<", "==", "!=",
    50→                ".is_empty()", ".starts_with(", ".ends_with(",
    51→                "assert!", "panic!", "unwrap(", "expect(",
    52→                "{}", "[]", "\"{}\"", "format!", "println!"
    53→            ];
    54→            let has_rust_syntax = rust_syntax_markers.iter()
    55→                .any(|marker| content.contains(marker));
    56→
    57→            if has_rust_syntax {
    58→                return false;  // Rust code, not a specification
    59→            }
    60→
    61→            // Also check for semantic keywords (original filter)
    62→            let semantic_keywords = [
    63→                "must", "should", "shall", "require", "ensure", "verify", "validate",
    64→                "detect", "identify", "check", "test verifies", "system", "user",
    65→                "specification", "requirement", "constraint"
    66→            ];
    67→
    68→            let has_semantic_meaning = semantic_keywords.iter()
    69→                .any(|kw| content.to_lowercase().contains(kw));
    70→
    71→            if !has_semantic_meaning {
    72→                // Low-quality test assertion - skip it
    73→                return false;
    74→            }
    75→        }
    76→
    77→        // Skip trivial scenario names that provide no information
    78→        // Examples: "scenario {}", "coverage empty graph", "coverage no tests"
    79→        if content == "scenario {}" || content.trim().is_empty() {
    80→            return false;
    81→        }
    82→
    83→        // Skip test function names that are too short or lack strong semantic value
    84→        // Examples: "coverage empty graph", "empty graph", "no tests", "user login"
    85→        if spec.kind == NodeKind::Scenario || spec.metadata.get("extractor") == Some(&"function_name".to_string()) {
    86→            // Check minimum length (at least 25 characters for descriptive spec)
    87→            if content.len() < 25 {
    88→                return false;
    89→            }
    90→
    91→            // Must have strong semantic keywords (not just "user" or "test")
    92→            let strong_keywords = [
    93→                "must", "should", "shall", "ensure", "verify", "validate",
    94→                "detect", "identify", "check for", "when", "if",
    95→                "specification", "requirement", "constraint", "correctly", "properly",
    96→                "without", "with", "given", "then", "returns", "accepts"
    97→            ];
    98→            let has_strong_semantic = strong_keywords.iter()
    99→                .any(|kw| content.to_lowercase().contains(kw));
   100→
   101→            // Reject if no strong semantics OR if it's just a test name pattern
   102→            let is_trivial_test_name = content.to_lowercase().starts_with("scenario: ") &&
   103→                !has_strong_semantic;
   104→
   105→            if !has_strong_semantic || is_trivial_test_name {
   106→                return false;
   107→            }
   108→        }
   109→
   110→        true
   111→    }
