   113→    /// Ingest inferred specifications into the graph
   114→    pub fn ingest(&mut self, specs: Vec<InferredSpecification>) -> IngestionReport {
   115→        let mut report = IngestionReport {
   116→            nodes_created: 0,
   117→            nodes_skipped: 0,
   118→            edges_created: 0,
   119→            suggestions: Vec::new(),
   120→            contradictions_found: Vec::new(),
   121→        };
   122→
   123→        // Create nodes for high-confidence inferences (with deduplication)
   124→        let mut created_ids = Vec::new();
   125→        for spec in specs {
   126→            // Apply both confidence threshold and quality filter
   127→            if spec.confidence >= 0.7 && Self::is_high_quality_spec(&spec) {
   128→                // Check for duplicate before creating node
   129→                if let Some(existing) = self.find_node_by_content(&spec.content, spec.kind) {
   130→                    // Duplicate found - skip creation, but track for edge inference
   131→                    created_ids.push(existing.id.clone());
   132→                    report.nodes_skipped += 1;
   133→                } else {
   134→                    // New node - create it
   135→                    let mut metadata = spec.metadata.clone();
   136→                    metadata.insert("source_file".to_string(), spec.source_file.clone());
   137→                    metadata.insert("source_line".to_string(), spec.source_line.to_string());
   138→                    metadata.insert("confidence".to_string(), spec.confidence.to_string());
   139→                    metadata.insert("inferred".to_string(), "true".to_string());
   140→
   141→                    let node = self.add_node_with_layer(
   142→                        spec.content,
   143→                        spec.kind,
   144→                        spec.formality_layer,
   145→                        metadata,
   146→                    );
   147→                    created_ids.push(node.id.clone());
   148→                    report.nodes_created += 1;
   149→                }
   150→            } else {
   151→                report.nodes_skipped += 1;
   152→            }
   153→        }
   154→
   155→        // Infer relationships between newly created nodes and existing nodes
   156→        for node_id in &created_ids {
   157→            let suggestions = self.infer_relationships_for_node(node_id);
   158→
   159→            for suggestion in suggestions {
   160→                if suggestion.confidence >= 0.8 {
   161→                    // High confidence: auto-create edge
