   164→                        &suggestion.target_id,
   165→                        suggestion.kind,
   166→                        HashMap::new(),
   167→                    ).is_ok() {
   168→                        report.edges_created += 1;
   169→                    }
   170→                    // Ignore errors (node might not exist)
   171→                } else if suggestion.confidence >= 0.5 {
   172→                    // Medium confidence: suggest for human review
   173→                    report.suggestions.push(suggestion);
   174→                }
   175→            }
   176→        }
   177→
   178→        // TODO: Contradiction detection should be done via UDAFModel.detect_contradictions()
   179→        // This is a formal verification operation, not a data layer operation.
   180→        // For now, we skip contradiction detection during ingestion.
   181→        // It will be done separately via the formal layer.
   182→
   183→        report
   184→    }
