   534→                    kind: edge_kind,
   535→                    confidence,
   536→                    explanation,
   537→                });
   538→            }
   539→        }
   540→
   541→        suggestions
   542→    }
   543→
   544→    /// Calculate semantic similarity between two texts (optionally AI-enhanced)
   545→    fn calculate_semantic_similarity(&self, text1: &str, text2: &str) -> f32 {
   546→        // Start with simple keyword-based similarity
   547→        let lower1 = text1.to_lowercase();
   548→        let lower2 = text2.to_lowercase();
   549→
   550→        let words1: std::collections::HashSet<String> =
   551→            lower1.split_whitespace().map(|s| s.to_string()).collect();
   552→        let words2: std::collections::HashSet<String> =
   553→            lower2.split_whitespace().map(|s| s.to_string()).collect();
   554→
   555→        if words1.is_empty() || words2.is_empty() {
   556→            return 0.0;
   557→        }
   558→
   559→        let intersection = words1.intersection(&words2).count();
   560→        let union = words1.union(&words2).count();
   561→
   562→        intersection as f32 / union as f32
   563→    }
   564→
   565→    /// Calculate semantic similarity with AI enhancement for cross-layer comparisons
   566→    fn calculate_semantic_similarity_with_ai(
   567→        &self,
   568→        text1: &str,
   569→        layer1: u8,
   570→        text2: &str,
   571→        layer2: u8,
   572→        ai: &crate::AISemantic,
   573→    ) -> f32 {
   574→        // First try simple similarity
   575→        let simple_sim = self.calculate_semantic_similarity(text1, text2);
   576→
   577→        // For cross-layer comparisons, ALWAYS use AI if available
   578→        // Keyword overlap is meaningless across layers (U0 uses natural language, U2/U3 use technical terms)
   579→        // Example: U0 "system must detect contradictions" ↔ U2 "RPC: DetectContradictions" (overlap ~0.1, semantic ~0.9)
   580→        if layer1 != layer2 {
   581→            if let Some(ai_sim) = ai.semantic_similarity(text1, text2, layer1, layer2) {
   582→                // Trust AI heavily for cross-layer matching
   583→                // Keyword overlap is noise, semantic equivalence is signal
   584→                return simple_sim * 0.2 + ai_sim * 0.8;
   585→            }
   586→            // AI unavailable: fall back to simple similarity (will miss many connections)
   587→            return simple_sim;
   588→        }
   589→
   590→        // Same-layer comparisons: use original conservative logic
   591→        // If similarity is very high (>0.8), trust keyword matching
   592→        if simple_sim > 0.8 {
   593→            return simple_sim;
   594→        }
   595→
   596→        // For moderate similarity (0.4-0.8), use AI to disambiguate
   597→        // This catches same-layer duplicates that keyword matching misses
   598→        if simple_sim >= 0.4
   599→            && let Some(ai_sim) = ai.semantic_similarity(text1, text2, layer1, layer2) {
   600→                // Blend simple and AI similarity (weighted average)
   601→                // Give more weight to AI for disambiguation
   602→                return simple_sim * 0.3 + ai_sim * 0.7;
   603→            }
   604→
   605→        // For very low similarity (<0.4) in same layer, skip AI (too expensive, low probability)
   606→        simple_sim
   607→    }
   608→
   609→    /// Infer edge kind between two nodes
   610→    fn infer_edge_kind(
   611→        &self,
   612→        source: &crate::SpecNodeData,
   613→        target: &crate::SpecNodeData,
   614→        similarity: f32,
   615→    ) -> Option<(EdgeKind, f32, String)> {
   616→        // Rule 1: Synonym - very high similarity, same kind
   617→        // Check this FIRST because it's most specific (highest threshold)
   618→        if similarity > 0.8 && source.kind == target.kind {
   619→            return Some((
   620→                EdgeKind::Synonym,
   621→                similarity * 0.95,
   622→                "Nearly identical content".to_string(),
   623→            ));
   624→        }
   625→
   626→        // Rule 2: Formalizes - same concept, different formality levels
   627→        if similarity > 0.5 && source.formality_layer < target.formality_layer {
   628→            return Some((
   629→                EdgeKind::Formalizes,
   630→                similarity * 0.9,
   631→                format!(
   632→                    "Same concept at different formality levels ({} -> {})",
   633→                    source.formality_layer, target.formality_layer
   634→                ),
   635→            ));
   636→        }
   637→
   638→        // Rule 3: DerivesFrom - assertion derives from constraint
   639→        if similarity > 0.5
   640→            && source.kind == NodeKind::Assertion
   641→            && target.kind == NodeKind::Constraint
   642→        {
   643→            return Some((
   644→                EdgeKind::DerivesFrom,
   645→                similarity * 0.8,
   646→                "Assertion derives from constraint".to_string(),
   647→            ));
   648→        }
   649→
   650→        // Rule 4: Refines - scenario refines constraint, or same kind with high similarity
   651→        if similarity > 0.6 {
   652→            if source.kind == NodeKind::Scenario && target.kind == NodeKind::Constraint {
   653→                return Some((
   654→                    EdgeKind::Refines,
   655→                    similarity * 0.85,
   656→                    "Scenario refines constraint".to_string(),
   657→                ));
   658→            }
   659→            if source.kind == target.kind {
   660→                return Some((
   661→                    EdgeKind::Refines,
   662→                    similarity * 0.9,
   663→                    "Similar specifications (potential refinement)".to_string(),
   664→                ));
   665→            }
   666→        }
   667→
   668→        // Rule 5: Same source file suggests relationship
   669→        if let (Some(src_file), Some(tgt_file)) = (
   670→            source.metadata.get("source_file"),
   671→            target.metadata.get("source_file"),
   672→        )
   673→            && src_file == tgt_file && similarity > 0.4 {
   674→                return Some((
   675→                    EdgeKind::Refines,
   676→                    similarity * 0.7,
   677→                    "Same source file".to_string(),
   678→                ));
   679→            }
   680→
   681→        None
   682→    }
   683→}
