   685→/// Extract specifications from Rust source code
   686→pub struct RustExtractor;
   687→
   688→impl Extractor<InferredSpecification> for RustExtractor {
   689→    fn extract(&self, artifact: &ArtifactSpace) -> Vec<InferredSpecification> {
   690→        let content = match artifact.as_text() {
   691→            Some(text) => text.clone(),
   692→            None => return Vec::new(),
   693→        };
   694→        let source = artifact.source()
   695→            .map(|s| s.clone())
   696→            .unwrap_or_else(|| "unknown".to_string());
   697→
   698→        Self::extract_from_content(&content, &source).unwrap_or_default()
   699→    }
   700→}
