   702→impl RustExtractor {
   703→    /// Extract specifications from Rust file (backward-compatible path-based API)
   704→    pub fn extract(file_path: &Path) -> Result<Vec<InferredSpecification>, String> {
   705→        let content = std::fs::read_to_string(file_path)
   706→            .map_err(|e| format!("Failed to read file: {}", e))?;
   707→        let file_name = file_path.to_string_lossy().to_string();
   708→
   709→        Self::extract_from_content(&content, &file_name)
   710→    }
