   712→    /// Core extraction logic that works with string content and a source name
   713→    fn extract_from_content(content: &str, source_name: &str) -> Result<Vec<InferredSpecification>, String> {
   714→        let mut specs = Vec::new();
   715→
   716→        // Extract from function names (conventions like validate_*, check_*, require_*)
   717→        specs.extend(Self::extract_from_function_names(content, source_name)?);
   718→
   719→        // Extract from assertions (assert!, assert_eq!, debug_assert!)
   720→        specs.extend(Self::extract_from_assertions(content, source_name)?);
   721→
   722→        // Extract from test functions
   723→        specs.extend(Self::extract_from_tests(content, source_name)?);
   724→
   725→        // Extract from doc comments
   726→        specs.extend(Self::extract_from_docs(content, source_name)?);
   727→
   728→        // Extract from panic messages
   729→        specs.extend(Self::extract_from_panics(content, source_name)?);
   730→
   731→        Ok(specs)
   732→    }
   733→
   734→    fn extract_from_function_names(
   735→        content: &str,
   736→        source_name: &str,
   737→    ) -> Result<Vec<InferredSpecification>, String> {
   738→        let mut specs = Vec::new();
   739→        let file_name = source_name.to_string();
   740→
   741→        for (line_num, line) in content.lines().enumerate() {
   742→            // Match function definitions
   743→            if let Some(fn_name) = Self::extract_fn_name(line) {
   744→                // Convention-based inference
   745→                let (kind, confidence, description) = if fn_name.starts_with("validate_") {
   746→                    (NodeKind::Constraint, 0.8, format!("Must {}", fn_name.strip_prefix("validate_").unwrap().replace('_', " ")))
   747→                } else if fn_name.starts_with("check_") {
   748→                    (NodeKind::Constraint, 0.75, format!("Must {}", fn_name.strip_prefix("check_").unwrap().replace('_', " ")))
   749→                } else if fn_name.starts_with("require_") {
   750→                    (NodeKind::Constraint, 0.85, format!("Requires {}", fn_name.strip_prefix("require_").unwrap().replace('_', " ")))
   751→                } else if fn_name.starts_with("test_") {
   752→                    (NodeKind::Scenario, 0.9, fn_name.strip_prefix("test_").unwrap().replace('_', " "))
   753→                } else {
   754→                    continue;
   755→                };
   756→
   757→                specs.push(InferredSpecification {
   758→                    content: description,
   759→                    kind,
   760→                    confidence,
   761→                    source_file: file_name.clone(),
   762→                    source_line: line_num + 1,
   763→                    formality_layer: 1, // Structured (from naming convention)
   764→                    metadata: HashMap::from([
   765→                        ("function".to_string(), fn_name.to_string()),
   766→                        ("extractor".to_string(), "function_name".to_string()),
   767→                    ]),
   768→                });
   769→            }
   770→        }
   771→
   772→        Ok(specs)
   773→    }
