   803→    fn extract_from_tests(
   804→        content: &str,
   805→        source_name: &str,
   806→    ) -> Result<Vec<InferredSpecification>, String> {
   807→        let mut specs = Vec::new();
   808→        let file_name = source_name.to_string();
   809→
   810→        let mut in_test = false;
   811→        let mut test_name = String::new();
   812→        let mut test_body = String::new();
   813→        let mut test_start_line = 0;
   814→
   815→        for (line_num, line) in content.lines().enumerate() {
   816→            let trimmed = line.trim();
   817→
   818→            // Detect #[test] or #[cfg(test)]
   819→            if trimmed.starts_with("#[test]") || trimmed.contains("#[test]") {
   820→                in_test = true;
   821→                test_start_line = line_num + 1;
   822→                test_body.clear();
   823→            } else if in_test && trimmed.starts_with("fn ") {
   824→                if let Some(name) = Self::extract_fn_name(trimmed) {
   825→                    test_name = name.to_string();
   826→                }
   827→            } else if in_test && !test_name.is_empty() {
   828→                // Collect test body for AI analysis
   829→                test_body.push_str(line);
   830→                test_body.push('\n');
   831→
   832→                if trimmed == "}" {
   833→                    // End of test function
   834→
   835→                    // Extract U3 test scenario (the test itself)
   836→                    let scenario_name = test_name.strip_prefix("test_").unwrap_or(&test_name).replace('_', " ");
   837→                    specs.push(InferredSpecification {
   838→                        content: format!("Scenario: {}", scenario_name),
   839→                        kind: NodeKind::Scenario,
   840→                        confidence: 0.9,
   841→                        source_file: file_name.clone(),
   842→                        source_line: test_start_line,
   843→                        formality_layer: 3, // U3 - Executable test
   844→                        metadata: HashMap::from([
   845→                            ("test_function".to_string(), test_name.clone()),
   846→                            ("extractor".to_string(), "test".to_string()),
   847→                        ]),
   848→                    });
   849→
   850→                    // Extract U0 requirement via AI (reverse mapping f₀₃⁻¹: U3 → U0)
   851→                    if let Some(u0_spec) = Self::extract_intent_from_test_with_ai(&test_name, &test_body) {
   852→                        specs.push(InferredSpecification {
   853→                            content: u0_spec,
   854→                            kind: NodeKind::Constraint, // Root requirements are constraints
   855→                            confidence: 0.95, // AI-extracted intent is high confidence
   856→                            source_file: file_name.clone(),
   857→                            source_line: test_start_line,
   858→                            formality_layer: 0, // U0 - root specification inferred from U3
   859→                            metadata: HashMap::from([
   860→                                ("test_function".to_string(), test_name.clone()),
   861→                                ("extractor".to_string(), "ai_intent".to_string()),
   862→                                ("reverse_mapping".to_string(), "f_03_inverse".to_string()),
   863→                                ("derived_from_u3".to_string(), "true".to_string()),
   864→                            ]),
   865→                        });
   866→                    }
   867→
   868→                    in_test = false;
   869→                    test_name.clear();
   870→                    test_body.clear();
   871→                }
   872→            }
   873→        }
   874→
   875→        Ok(specs)
   876→    }
