   878→    /// Extract the INTENT behind a test using AI (reverse mapping f₀₃⁻¹: U3 → U0)
   879→    ///
   880→    /// This is the core of the reverse mapping engine. Instead of just pattern-matching
   881→    /// test names, we use AI to understand what requirement the test is verifying.
   882→    fn extract_intent_from_test_with_ai(test_name: &str, test_body: &str) -> Option<String> {
   883→        use std::process::{Command, Stdio};
   884→
   885→        // Check if claude CLI is available
   886→        let available = Command::new("claude")
   887→            .arg("--version")
   888→            .stdout(Stdio::null())
   889→            .stderr(Stdio::null())
   890→            .status()
   891→            .is_ok();
   892→
   893→        if !available {
   894→            // Fallback to simple name-based extraction if AI unavailable
   895→            return None;
   896→        }
   897→
   898→        let prompt = format!(
   899→            r#"You are analyzing a test function to extract the root specification (U0) it verifies.
   900→
   901→Test name: {}
   902→Test code:
   903→{}
   904→
   905→Task: Extract the fundamental REQUIREMENT or CONSTRAINT that this test is verifying.
   906→Output ONLY a single sentence specification in natural language, starting with "The system must..." or "System must..." or similar.
   907→
   908→Focus on:
   909→- What requirement is being tested? (not how it's tested)
   910→- What constraint must the system satisfy?
   911→- What capability must the system provide?
   912→
   913→Output format: Single sentence, no explanation, no code, just the requirement.
   914→Example output: "The system must detect contradictions when password length requirements conflict"
   915→"#,
   916→            test_name, test_body
   917→        );
   918→
   919→        let output = Command::new("claude")
   920→            .arg("-p")
   921→            .arg(&prompt)
   922→            .output()
   923→            .ok()?;
   924→
   925→        if !output.status.success() {
   926→            return None;
   927→        }
   928→
   929→        let response = String::from_utf8(output.stdout).ok()?;
   930→        let spec = response.trim();
   931→
   932→        // Validate that we got a reasonable specification
   933→        if spec.is_empty() || spec.len() < 20 || spec.len() > 500 {
   934→            return None;
   935→        }
   936→
   937→        // Check that it's a specification (contains requirement keywords)
   938→        let requirement_keywords = ["must", "shall", "should", "system", "require"];
   939→        let has_requirement = requirement_keywords.iter()
   940→            .any(|kw| spec.to_lowercase().contains(kw));
   941→
   942→        if !has_requirement {
   943→            return None;
   944→        }
   945→
   946→        Some(spec.to_string())
   947→    }
   948→
   949→    fn extract_from_docs(
   950→        content: &str,
   951→        source_name: &str,
   952→    ) -> Result<Vec<InferredSpecification>, String> {
   953→        let mut specs = Vec::new();
   954→        let file_name = source_name.to_string();
   955→
   956→        for (line_num, line) in content.lines().enumerate() {
   957→            let trimmed = line.trim();
   958→
   959→            // Match /// or //! doc comments
   960→            if let Some(doc) = trimmed.strip_prefix("///").or_else(|| trimmed.strip_prefix("//!")) {
   961→                let doc_text = doc.trim();
   962→
   963→                // Look for specification keywords
   964→                let (kind, confidence) = if doc_text.contains("must") || doc_text.contains("shall") || doc_text.contains("required") {
   965→                    (NodeKind::Constraint, 0.8)
   966→                } else if doc_text.contains("should") || doc_text.contains("expected") {
   967→                    (NodeKind::Assertion, 0.7)
   968→                } else if doc_text.contains("example") || doc_text.contains("scenario") {
   969→                    (NodeKind::Scenario, 0.6)
   970→                } else {
   971→                    continue; // Not a specification
   972→                };
   973→
   974→                if !doc_text.is_empty() {
   975→                    specs.push(InferredSpecification {
   976→                        content: doc_text.to_string(),
   977→                        kind,
   978→                        confidence,
   979→                        source_file: file_name.clone(),
   980→                        source_line: line_num + 1,
   981→                        formality_layer: 0, // Natural language
   982→                        metadata: HashMap::from([
   983→                            ("doc_comment".to_string(), "true".to_string()),
   984→                            ("extractor".to_string(), "doc".to_string()),
   985→                        ]),
   986→                    });
   987→                }
   988→            }
   989→        }
   990→
   991→        Ok(specs)
   992→    }
