  1022→    // Helper parsers
  1023→
  1024→    fn extract_fn_name(line: &str) -> Option<String> {
  1025→        let trimmed = line.trim();
  1026→        if trimmed.starts_with("fn ") || trimmed.starts_with("pub fn ") {
  1027→            let after_fn = trimmed.split("fn ").nth(1)?;
  1028→            let name = after_fn.split('(').next()?.trim();
  1029→            Some(name.to_string())
  1030→        } else {
  1031→            None
  1032→        }
  1033→    }
  1034→
  1035→    fn extract_assertion(line: &str) -> Option<String> {
  1036→        let trimmed = line.trim();
  1037→
  1038→        // Match assert!(...), assert_eq!(...), etc.
  1039→        for macro_name in &["assert!", "assert_eq!", "assert_ne!", "debug_assert!"] {
  1040→            if let Some(idx) = trimmed.find(macro_name) {
  1041→                let after_macro = &trimmed[idx + macro_name.len()..];
  1042→                if let Some(start) = after_macro.find('(')
  1043→                    && let Some(end) = after_macro.rfind(')') {
  1044→                        let assertion = &after_macro[start + 1..end];
  1045→                        return Some(assertion.trim().to_string());
  1046→                    }
  1047→            }
  1048→        }
  1049→
  1050→        None
  1051→    }
  1052→
  1053→    fn extract_panic_message(line: &str) -> Option<String> {
  1054→        let trimmed = line.trim();
  1055→
  1056→        if let Some(idx) = trimmed.find("panic!(") {
  1057→            let after_panic = &trimmed[idx + 7..];
  1058→            if let Some(start) = after_panic.find('"')
  1059→                && let Some(end) = after_panic[start + 1..].find('"') {
  1060→                    let message = &after_panic[start + 1..start + 1 + end];
  1061→                    return Some(message.to_string());
  1062→                }
  1063→        }
  1064→
  1065→        None
  1066→    }
  1067→}
