  1189→/// Extract U2 specifications from Protocol Buffer (.proto) files
  1190→pub struct ProtoExtractor;
  1191→
  1192→impl ProtoExtractor {
  1193→    /// Extract RPC interface specifications from proto file
  1194→    pub fn extract(file_path: &Path) -> Result<Vec<InferredSpecification>, String> {
  1195→        let content = std::fs::read_to_string(file_path)
  1196→            .map_err(|e| format!("Failed to read file: {}", e))?;
  1197→
  1198→        let mut specs = Vec::new();
  1199→        let file_name = file_path.to_string_lossy().to_string();
  1200→
  1201→        // Extract RPC definitions
  1202→        let mut current_comment = String::new();
  1203→        for (line_num, line) in content.lines().enumerate() {
  1204→            let trimmed = line.trim();
  1205→
  1206→            // Capture comment lines
  1207→            if trimmed.starts_with("//") {
  1208→                let comment = trimmed.trim_start_matches("//").trim();
  1209→                if !comment.is_empty() {
  1210→                    current_comment = comment.to_string();
  1211→                }
  1212→                continue;
  1213→            }
  1214→
  1215→            // Match RPC definitions: "rpc MethodName(RequestType) returns (ResponseType);"
  1216→            if trimmed.starts_with("rpc ")
  1217→                && let Some(rpc_name) = Self::extract_rpc_name(trimmed) {
  1218→                    let description = if !current_comment.is_empty() {
  1219→                        current_comment.clone()
  1220→                    } else {
  1221→                        // Generate description from RPC name
  1222→                        Self::rpc_name_to_description(&rpc_name)
  1223→                    };
  1224→
  1225→                    specs.push(InferredSpecification {
  1226→                        content: description,
  1227→                        kind: NodeKind::Assertion, // RPC interface is an assertion about behavior
  1228→                        confidence: 0.95, // High confidence - explicitly defined interface
  1229→                        source_file: file_name.clone(),
  1230→                        source_line: line_num + 1,
  1231→                        formality_layer: 2, // U2: Interface/API specification
  1232→                        metadata: HashMap::from([
  1233→                            ("rpc_name".to_string(), rpc_name.clone()),
  1234→                            ("extractor".to_string(), "proto_rpc".to_string()),
  1235→                        ]),
  1236→                    });
  1237→
  1238→                    current_comment.clear();
  1239→                }
  1240→        }
  1241→
  1242→        Ok(specs)
  1243→    }
  1244→
  1245→    fn extract_rpc_name(line: &str) -> Option<String> {
  1246→        // Parse "rpc MethodName(Request) returns (Response);"
  1247→        let after_rpc = line.strip_prefix("rpc ")?.trim();
  1248→        let name = after_rpc.split('(').next()?.trim();
  1249→        Some(name.to_string())
  1250→    }
  1251→
  1252→    fn rpc_name_to_description(rpc_name: &str) -> String {
  1253→        // Convert camelCase/PascalCase to sentence
  1254→        // AddNode -> "RPC: Add node"
  1255→        // DetectContradictions -> "RPC: Detect contradictions"
  1256→        let mut result = String::new();
  1257→        let mut prev_was_lower = false;
  1258→
  1259→        for (i, ch) in rpc_name.chars().enumerate() {
  1260→            if ch.is_uppercase() && prev_was_lower {
  1261→                result.push(' ');
  1262→                result.push(ch.to_lowercase().next().unwrap());
  1263→            } else if i == 0 {
  1264→                // First character stays as-is
  1265→                result.push(ch);
  1266→            } else {
  1267→                result.push(ch.to_lowercase().next().unwrap());
  1268→            }
  1269→            prev_was_lower = ch.is_lowercase();
  1270→        }
  1271→
  1272→        format!("RPC: {}", result)
  1273→    }
  1274→}
