  1276→/// Extract specifications from documentation files (Markdown)
  1277→pub struct DocExtractor;
  1278→
  1279→impl DocExtractor {
  1280→    /// Extract specifications from Markdown documentation
  1281→    pub fn extract(file_path: &Path) -> Result<Vec<InferredSpecification>, String> {
  1282→        let content = std::fs::read_to_string(file_path)
  1283→            .map_err(|e| format!("Failed to read file: {}", e))?;
  1284→
  1285→        let mut specs = Vec::new();
  1286→        let file_name = file_path.to_string_lossy().to_string();
  1287→
  1288→        // Process line by line
  1289→        for (line_num, line) in content.lines().enumerate() {
  1290→            let trimmed = line.trim();
  1291→
  1292→            // Skip empty lines, headings, and code blocks
  1293→            if trimmed.is_empty() || trimmed.starts_with('#') || trimmed.starts_with("```") {
  1294→                continue;
  1295→            }
  1296→
  1297→            // Look for specification patterns
  1298→            if let Some(spec) = Self::extract_specification(trimmed, &file_name, line_num + 1) {
  1299→                specs.push(spec);
  1300→            }
  1301→        }
