  1305→
  1306→    fn extract_specification(line: &str, file_name: &str, line_num: usize) -> Option<InferredSpecification> {
  1307→        // Specification markers indicating requirements/constraints
  1308→        let constraint_markers = ["must", "shall", "required", "constraint"];
  1309→        let assertion_markers = ["should", "can", "will", "provides", "supports"];
  1310→        let scenario_markers = ["when", "given", "example", "scenario"];
  1311→
  1312→        let lower = line.to_lowercase();
  1313→
  1314→        // Determine kind based on markers
  1315→        let (kind, confidence_base) = if constraint_markers.iter().any(|m| lower.contains(m)) {
  1316→            (NodeKind::Constraint, 0.85)
  1317→        } else if assertion_markers.iter().any(|m| lower.contains(m)) {
  1318→            (NodeKind::Assertion, 0.75)
  1319→        } else if scenario_markers.iter().any(|m| lower.contains(m)) {
  1320→            (NodeKind::Scenario, 0.70)
  1321→        } else {
  1322→            return None; // Not a specification
  1323→        };
  1324→
  1325→        // Skip if line is too short (likely not a complete specification)
  1326→        if line.len() < 20 {
  1327→            return None;
  1328→        }
  1329→
  1330→        // Clean up markdown formatting
  1331→        let content = Self::clean_markdown(line);
  1332→
  1333→        // Adjust confidence based on content quality
  1334→        let confidence: f32 = if content.len() > 50 && content.contains("system") {
  1335→            confidence_base + 0.1
  1336→        } else {
  1337→            confidence_base
  1338→        };
  1339→
  1340→        // Determine formality layer based on content
  1341→        let formality_layer = if lower.contains("formally") || lower.contains("proof") {
  1342→            1 // U1: More formal specification
  1343→        } else {
  1344→            0 // U0: Natural language requirement
  1345→        };
  1346→
  1347→        Some(InferredSpecification {
  1348→            content,
  1349→            kind,
  1350→            confidence: confidence.min(0.95),
  1351→            source_file: file_name.to_string(),
  1352→            source_line: line_num,
  1353→            formality_layer,
  1354→            metadata: HashMap::from([
  1355→                ("extractor".to_string(), "documentation".to_string()),
  1356→            ]),
  1357→        })
  1358→    }
  1359→
  1360→    fn clean_markdown(text: &str) -> String {
  1361→        // Remove common markdown formatting
  1362→        let mut cleaned = text.to_string();
  1363→
  1364→        // Remove bold/italic markers
  1365→        cleaned = cleaned.replace("**", "");
  1366→        cleaned = cleaned.replace("__", "");
  1367→        cleaned = cleaned.replace("*", "");
  1368→        cleaned = cleaned.replace("_", "");
  1369→
  1370→        // Remove list markers
  1371→        if let Some(stripped) = cleaned.strip_prefix("- ") {
  1372→            cleaned = stripped.to_string();
  1373→        }
  1374→        if let Some(stripped) = cleaned.strip_prefix("* ") {
  1375→            cleaned = stripped.to_string();
  1376→        }
  1377→
  1378→        // Remove numbered list markers (e.g., "1. ")
  1379→        if let Some(pos) = cleaned.find(". ")
  1380→            && cleaned[..pos].chars().all(|c| c.is_numeric()) {
  1381→                cleaned = cleaned[pos + 2..].to_string();
  1382→            }
  1383→
  1384→        cleaned.trim().to_string()
  1385→    }
  1386→}
