  1426→            kind: NodeKind::Assertion,
  1427→            confidence,
  1428→            source_file: file_name.to_string(),
  1429→            source_line: 0, // File-level property
  1430→            formality_layer: 3, // U3: Implementation fact
  1431→            metadata: HashMap::from([
  1432→                ("extractor".to_string(), "architecture".to_string()),
