   103→// --- Node types ---
   104→
   105→message SpecNode {
   106→  string id = 1;
   107→  string content = 2;
   108→  SpecNodeKind kind = 3;
   109→  map<string, string> metadata = 4;
   110→  int64 created_at = 5;
   111→  int64 modified_at = 6;
   112→  uint32 formality_layer = 7;  // 0=natural, 1=structured, 2=formal, 3=executable
   113→}
   114→
   115→enum SpecNodeKind {
   116→  SPEC_NODE_KIND_UNSPECIFIED = 0;
   117→  ASSERTION = 1;       // A concrete claim about behavior
   118→  CONSTRAINT = 2;      // A universal constraint (invariant)
   119→  SCENARIO = 3;        // An existential requirement (a path that must exist)
   120→  DEFINITION = 4;      // A term definition
   121→  DOMAIN = 5;          // A domain boundary declaration
   122→}
   123→
   124→// --- Edge types ---
   125→
   126→message SpecEdge {
   127→  string id = 1;
   128→  string source_id = 2;
   129→  string target_id = 3;
   130→  SpecEdgeKind kind = 4;
   131→  map<string, string> metadata = 5;
   132→  int64 created_at = 6;
   133→}
   134→
   135→enum SpecEdgeKind {
   136→  SPEC_EDGE_KIND_UNSPECIFIED = 0;
   137→  REFINES = 1;         // Target refines source (is more specific)
   138→  DEPENDS_ON = 2;      // Source depends on target
   139→  CONTRADICTS = 3;     // Source contradicts target
   140→  DERIVES_FROM = 4;    // Source is derived from target
   141→  SYNONYM = 5;         // Source and target are synonymous terms
   142→  COMPOSES = 6;        // Source composes with target into a higher-level spec
   143→  FORMALIZES = 7;      // Target is a more formal version of source
   144→  TRANSFORM = 8;       // Function f: maps spec from source universe to target universe
   145→}
