    71→        metadata: HashMap<String, String>,
    72→    ) -> &SpecNodeData {
    73→        let id = Uuid::new_v4().to_string();
    74→        let now = Utc::now().timestamp();
    75→        let data = SpecNodeData {
    76→            id: id.clone(),
    77→            content,
    78→            kind,
    79→            metadata,
    80→            created_at: now,
    81→            modified_at: now,
    82→            formality_layer: 0, // Default to natural language
    83→        };
    84→        let idx = self.graph.add_node(data);
    85→        self.id_to_index.insert(id, idx);
