   204→            .ok_or_else(|| GraphError::NodeNotFound(edge.source.clone()))?;
   205→        let &tgt_idx = self
   206→            .id_to_index
   207→            .get(&edge.target)
   208→            .ok_or_else(|| GraphError::NodeNotFound(edge.target.clone()))?;
   209→
   210→        let id = edge.data.id.clone();
   211→        let eidx = self.graph.add_edge(src_idx, tgt_idx, edge.data);
   212→        self.edge_id_to_index.insert(id.clone(), eidx);
