   411→
   412→    /// Find all synonym groups: nodes connected by Synonym edges.
   413→    pub fn resolve_term(&self, term: &str) -> (Vec<&SpecNodeData>, Vec<String>) {
   414→        let t = term.to_lowercase();
   415→
   416→        // Find definition nodes matching the term
   417→        let definitions: Vec<&SpecNodeData> = self
   418→            .graph
   419→            .node_weights()
   420→            .filter(|n| n.kind == NodeKind::Definition && n.content.to_lowercase().contains(&t))
   421→            .collect();
   422→
   423→        // Collect synonyms via Synonym edges
   424→        let mut synonyms = Vec::new();
   425→        for def in &definitions {
   426→            if let Some(&idx) = self.id_to_index.get(&def.id) {
   427→                for edge in self
   428→                    .graph
   429→                    .edges_directed(idx, Direction::Outgoing)
   430→                    .chain(self.graph.edges_directed(idx, Direction::Incoming))
   431→                {
   432→                    if self.graph[edge.id()].kind == EdgeKind::Synonym {
   433→                        let other_idx = if edge.source() == idx {
   434→                            edge.target()
   435→                        } else {
   436→                            edge.source()
   437→                        };
   438→                        let other = &self.graph[other_idx];
   439→                        if !synonyms.contains(&other.content) {
   440→                            synonyms.push(other.content.clone());
   441→                        }
   442→                    }
   443→                }
   444→            }
   445→        }
   446→
   447→        (definitions, synonyms)
   448→    }
   449→
   450→    /// Find potentially related terms based on co-occurrence in metadata or content.
   451→    /// This provides a lightweight semantic clustering without requiring external AI.
   452→    pub fn find_related_terms(&self, term: &str) -> Vec<(&SpecNodeData, f32)> {
   453→        let t = term.to_lowercase();
   454→        let mut scored_nodes: Vec<(&SpecNodeData, f32)> = Vec::new();
   455→
   456→        // Find nodes that mention the term
   457→        let mentioning_nodes: Vec<&SpecNodeData> = self
   458→            .graph
   459→            .node_weights()
   460→            .filter(|n| n.content.to_lowercase().contains(&t))
   461→            .collect();
   462→
   463→        if mentioning_nodes.is_empty() {
   464→            return scored_nodes;
   465→        }
   466→
   467→        // Extract significant words from mentioning nodes (excluding common words)
   468→        let stop_words = [
   469→            "the", "a", "an", "and", "or", "but", "in", "on", "at", "to", "for",
   470→        ];
   471→        let mut term_context: std::collections::HashSet<String> =
   472→            std::collections::HashSet::new();
   473→
   474→        for node in &mentioning_nodes {
   475→            for word in node.content.to_lowercase().split_whitespace() {
   476→                let clean_word = word.trim_matches(|c: char| !c.is_alphanumeric());
   477→                if clean_word.len() > 2 && !stop_words.contains(&clean_word) {
   478→                    term_context.insert(clean_word.to_string());
   479→                }
   480→            }
   481→        }
   482→
   483→        // Score all nodes based on context overlap
   484→        for node in self.graph.node_weights() {
   485→            if mentioning_nodes.contains(&node) {
   486→                continue; // Skip nodes that directly mention the term
   487→            }
   488→
   489→            let node_words: std::collections::HashSet<String> = node
   490→                .content
   491→                .to_lowercase()
   492→                .split_whitespace()
   493→                .map(|w| w.trim_matches(|c: char| !c.is_alphanumeric()).to_string())
   494→                .filter(|w| w.len() > 2 && !stop_words.contains(&w.as_str()))
   495→                .collect();
   496→
   497→            let overlap = term_context.intersection(&node_words).count();
   498→            if overlap > 0 {
   499→                let score = overlap as f32 / term_context.len().max(1) as f32;
   500→                scored_nodes.push((node, score));
   501→            }
   502→        }
   503→
   504→        // Sort by score descending
   505→        scored_nodes.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
   506→        scored_nodes
   507→    }
   508→
   509→    /// Detect potential synonym pairs based on graph structure.
   510→    /// Nodes that share similar connections might be semantically related.
   511→    pub fn detect_potential_synonyms(&self) -> Vec<(SpecNodeData, SpecNodeData, f32)> {
   512→        let mut candidates = Vec::new();
   513→        let definition_nodes: Vec<(NodeIndex, &SpecNodeData)> = self
   514→            .graph
   515→            .node_indices()
   516→            .map(|idx| (idx, &self.graph[idx]))
   517→            .filter(|(_, n)| n.kind == NodeKind::Definition)
   518→            .collect();
   519→
   520→        for i in 0..definition_nodes.len() {
   521→            for j in (i + 1)..definition_nodes.len() {
   522→                let (idx_a, node_a) = definition_nodes[i];
   523→                let (idx_b, node_b) = definition_nodes[j];
   524→
   525→                // Skip if already marked as synonyms
   526→                let already_synonyms = self
   527→                    .graph
   528→                    .edges_directed(idx_a, Direction::Outgoing)
   529→                    .chain(self.graph.edges_directed(idx_a, Direction::Incoming))
   530→                    .any(|e| {
   531→                        self.graph[e.id()].kind == EdgeKind::Synonym
   532→                            && (e.source() == idx_b || e.target() == idx_b)
   533→                    });
   534→
   535→                if already_synonyms {
   536→                    continue;
   537→                }
   538→
   539→                // Calculate structural similarity (Jaccard similarity of neighbors)
   540→                let neighbors_a: std::collections::HashSet<NodeIndex> =
   541→                    self.graph.neighbors_undirected(idx_a).collect();
   542→                let neighbors_b: std::collections::HashSet<NodeIndex> =
   543→                    self.graph.neighbors_undirected(idx_b).collect();
   544→
   545→                if neighbors_a.is_empty() && neighbors_b.is_empty() {
   546→                    continue;
   547→                }
   548→
   549→                let intersection = neighbors_a.intersection(&neighbors_b).count();
   550→                let union = neighbors_a.union(&neighbors_b).count();
   551→
   552→                if union > 0 {
   553→                    let similarity = intersection as f32 / union as f32;
   554→                    if similarity > 0.3 {
   555→                        // Threshold for potential synonyms
   556→                        candidates.push((node_a.clone(), node_b.clone(), similarity));
   557→                    }
   558→                }
   559→            }
   560→        }
   561→
   562→        candidates.sort_by(|a, b| b.2.partial_cmp(&a.2).unwrap_or(std::cmp::Ordering::Equal));
   563→        candidates
   564→    }
