   650→    /// Get test coverage report: which specifications have test links.
   651→    pub fn get_test_coverage(&self) -> TestCoverage {
   652→        let total_testable = self
   653→            .graph
   654→            .node_weights()
   655→            .filter(|n| matches!(n.kind, NodeKind::Constraint | NodeKind::Scenario))
   656→            .count();
   657→
   658→        let with_tests = self
   659→            .graph
   660→            .node_weights()
   661→            .filter(|n| {
   662→                matches!(n.kind, NodeKind::Constraint | NodeKind::Scenario)
   663→                    && n.metadata.contains_key("test_file")
   664→            })
   665→            .count();
   666→
   667→        let nodes_with_tests: Vec<SpecNodeData> = self
   668→            .graph
   669→            .node_weights()
   670→            .filter(|n| {
   671→                matches!(n.kind, NodeKind::Constraint | NodeKind::Scenario)
   672→                    && n.metadata.contains_key("test_file")
   673→            })
   674→            .cloned()
   675→            .collect();
   676→
   677→        let nodes_without_tests: Vec<SpecNodeData> = self
   678→            .graph
   679→            .node_weights()
   680→            .filter(|n| {
   681→                matches!(n.kind, NodeKind::Constraint | NodeKind::Scenario)
   682→                    && !n.metadata.contains_key("test_file")
   683→            })
   684→            .cloned()
   685→            .collect();
   686→
   687→        TestCoverage {
   688→            total_testable,
   689→            with_tests,
   690→            coverage_ratio: if total_testable > 0 {
   691→                with_tests as f32 / total_testable as f32
   692→            } else {
   693→                0.0
   694→            },
   695→            nodes_with_tests,
   696→            nodes_without_tests,
   697→        }
   698→    }
   699→
   700→    /// Calculate compliance score between a specification and code snippet.
   701→    /// Returns score 0.0-1.0 based on semantic similarity.
   702→    pub fn calculate_compliance(&self, node_id: &str, code: &str) -> Option<ComplianceScore> {
   703→        let node = self.get_node(node_id)?;
   704→
   705→        // Extract keywords from specification
   706→        let spec_keywords = self.extract_keywords(&node.content);
   707→        let code_keywords = self.extract_keywords(code);
   708→
   709→        if spec_keywords.is_empty() {
   710→            return Some(ComplianceScore {
   711→                score: 0.0,
   712→                keyword_overlap: 0.0,
   713→                structural_match: 0.0,
   714→                explanation: "Specification has no extractable keywords".to_string(),
   715→            });
   716→        }
   717→
   718→        // Calculate keyword overlap (Jaccard similarity)
   719→        let intersection = spec_keywords.intersection(&code_keywords).count();
   720→        let union = spec_keywords.union(&code_keywords).count();
   721→        let keyword_overlap = if union > 0 {
   722→            intersection as f32 / union as f32
   723→        } else {
   724→            0.0
   725→        };
   726→
   727→        // Structural matching for constraints/scenarios
   728→        let structural_match = match node.kind {
   729→            NodeKind::Constraint => self.match_constraint_structure(&node.content, code),
   730→            NodeKind::Scenario => self.match_scenario_structure(&node.content, code),
   731→            _ => 0.5, // Neutral for other types
   732→        };
   733→
   734→        // Weighted average (60% keywords, 40% structure)
   735→        let score = keyword_overlap * 0.6 + structural_match * 0.4;
   736→
   737→        let explanation = if score > 0.8 {
   738→            "Strong compliance - code closely matches specification".to_string()
   739→        } else if score > 0.5 {
   740→            "Moderate compliance - code partially matches specification".to_string()
   741→        } else if score > 0.2 {
   742→            "Weak compliance - code loosely relates to specification".to_string()
   743→        } else {
   744→            "Poor compliance - code does not match specification".to_string()
   745→        };
   746→
   747→        Some(ComplianceScore {
   748→            score,
   749→            keyword_overlap,
   750→            structural_match,
   751→            explanation,
   752→        })
   753→    }
   754→
   755→    fn extract_keywords(&self, text: &str) -> std::collections::HashSet<String> {
   756→        let stop_words = [
   757→            "the", "a", "an", "and", "or", "but", "in", "on", "at", "to", "for", "is", "are",
   758→            "was", "were", "be", "been", "being", "have", "has", "had", "do", "does", "did",
   759→            "will", "would", "should", "could", "may", "might", "must", "can", "of", "by",
   760→            "with", "from", "as", "into", "through",
   761→        ];
   762→
   763→        text.to_lowercase()
   764→            .split_whitespace()
   765→            .map(|w| w.trim_matches(|c: char| !c.is_alphanumeric()))
   766→            .filter(|w| w.len() > 2 && !stop_words.contains(w))
   767→            .map(|w| w.to_string())
   768→            .collect()
   769→    }
   770→
   771→    fn match_constraint_structure(&self, spec: &str, code: &str) -> f32 {
   772→        let spec_lower = spec.to_lowercase();
   773→        let code_lower = code.to_lowercase();
   774→
   775→        let mut score: f32 = 0.0;
   776→
   777→        // Look for constraint patterns
   778→        if (spec_lower.contains("must") || spec_lower.contains("should"))
   779→            && (code_lower.contains("assert")
   780→                || code_lower.contains("require")
   781→                || code_lower.contains("invariant"))
   782→        {
   783→            score += 0.3;
   784→        }
   785→
   786→        // Look for comparison operators
   787→        if (spec_lower.contains('>')
   788→            || spec_lower.contains('<')
   789→            || spec_lower.contains("greater")
   790→            || spec_lower.contains("less"))
   791→            && (code_lower.contains('>') || code_lower.contains('<'))
   792→        {
   793→            score += 0.2;
   794→        }
   795→
   796→        // Look for equality checks
   797→        if (spec_lower.contains("equal") || spec_lower.contains("same"))
   798→            && (code_lower.contains("==") || code_lower.contains("equals"))
   799→        {
   800→            score += 0.2;
   801→        }
   802→
   803→        // Look for boundary conditions
   804→        if (spec_lower.contains("not") || spec_lower.contains("never"))
   805→            && (code_lower.contains('!') || code_lower.contains("not"))
   806→        {
   807→            score += 0.3;
   808→        }
   809→
   810→        score.min(1.0)
   811→    }
   812→
   813→    fn match_scenario_structure(&self, spec: &str, code: &str) -> f32 {
   814→        let spec_lower = spec.to_lowercase();
   815→        let code_lower = code.to_lowercase();
   816→
   817→        let mut score: f32 = 0.0;
   818→
   819→        // Look for action words
   820→        let action_words = [
   821→            "login", "create", "update", "delete", "send", "receive", "verify",
   822→        ];
   823→        let has_action = action_words
   824→            .iter()
   825→            .any(|&w| spec_lower.contains(w) && code_lower.contains(w));
   826→        if has_action {
   827→            score += 0.4;
   828→        }
   829→
   830→        // Look for test structure
   831→        if code_lower.contains("test") || code_lower.contains("scenario") {
   832→            score += 0.2;
   833→        }
   834→
   835→        // Look for setup/action/verify pattern
   836→        let has_setup = code_lower.contains("setup") || code_lower.contains("given");
   837→        let has_action_code = code_lower.contains("when") || code_lower.contains("act");
   838→        let has_verify = code_lower.contains("assert")
   839→            || code_lower.contains("verify")
   840→            || code_lower.contains("expect");
   841→
   842→        if has_setup {
   843→            score += 0.1;
   844→        }
   845→        if has_action_code {
   846→            score += 0.15;
   847→        }
   848→        if has_verify {
   849→            score += 0.15;
   850→        }
   851→
   852→        score.min(1.0)
   853→    }
   854→
   855→    /// Get compliance report for all specifications with linked code.
   856→    pub fn get_compliance_report(&self) -> Vec<(SpecNodeData, ComplianceScore)> {
   857→        self.graph
   858→            .node_weights()
   859→            .filter(|n| n.metadata.contains_key("impl_code") || n.metadata.contains_key("test_code"))
   860→            .filter_map(|n| {
   861→                let code = n
   862→                    .metadata
   863→                    .get("impl_code")
   864→                    .or_else(|| n.metadata.get("test_code"))?;
   865→                let score = self.calculate_compliance(&n.id, code)?;
   866→                Some((n.clone(), score))
   867→            })
   868→            .collect()
   869→    }
   870→
   871→    // ========================================================================
   872→    // Temporal operations
   873→    // ========================================================================
   874→
   875→    /// Query graph state at a specific timestamp.
   876→    /// Returns nodes and edges that existed at that time.
   877→    pub fn query_at_timestamp(&self, timestamp: i64) -> TemporalSnapshot {
   878→        let nodes: Vec<SpecNodeData> = self
   879→            .graph
   880→            .node_weights()
   881→            .filter(|n| n.created_at <= timestamp)
   882→            .cloned()
   883→            .collect();
   884→
   885→        let edges: Vec<SpecEdgeData> = self
   886→            .graph
   887→            .edge_indices()
   888→            .filter_map(|eidx| {
   889→                let edge = &self.graph[eidx];
   890→                if edge.created_at <= timestamp {
   891→                    Some(edge.clone())
   892→                } else {
   893→                    None
   894→                }
   895→            })
   896→            .collect();
   897→
   898→        let node_count = nodes.len();
   899→        let edge_count = edges.len();
   900→
   901→        TemporalSnapshot {
   902→            timestamp,
   903→            nodes,
   904→            edges,
   905→            node_count,
   906→            edge_count,
   907→        }
   908→    }
   909→
   910→    /// Diff graph state between two timestamps.
   911→    /// Shows what was added, modified, or removed.
   912→    pub fn diff_timestamps(&self, from_timestamp: i64, to_timestamp: i64) -> TemporalDiff {
   913→        let from_snapshot = self.query_at_timestamp(from_timestamp);
   914→        let to_snapshot = self.query_at_timestamp(to_timestamp);
   915→
   916→        let from_node_ids: std::collections::HashSet<String> =
   917→            from_snapshot.nodes.iter().map(|n| n.id.clone()).collect();
   918→        let to_node_ids: std::collections::HashSet<String> =
   919→            to_snapshot.nodes.iter().map(|n| n.id.clone()).collect();
   920→
   921→        let added_nodes: Vec<SpecNodeData> = to_snapshot
   922→            .nodes
   923→            .iter()
   924→            .filter(|n| !from_node_ids.contains(&n.id))
   925→            .cloned()
   926→            .collect();
   927→
   928→        let removed_nodes: Vec<SpecNodeData> = from_snapshot
   929→            .nodes
   930→            .iter()
   931→            .filter(|n| !to_node_ids.contains(&n.id))
   932→            .cloned()
   933→            .collect();
   934→
   935→        let modified_nodes: Vec<(SpecNodeData, SpecNodeData)> = to_snapshot
   936→            .nodes
   937→            .iter()
   938→            .filter_map(|to_node| {
   939→                from_snapshot
   940→                    .nodes
   941→                    .iter()
   942→                    .find(|from_node| from_node.id == to_node.id)
   943→                    .and_then(|from_node| {
   944→                        if from_node.modified_at < to_node.modified_at {
   945→                            Some((from_node.clone(), to_node.clone()))
   946→                        } else {
   947→                            None
   948→                        }
   949→                    })
   950→            })
   951→            .collect();
   952→
   953→        let from_edge_ids: std::collections::HashSet<String> =
   954→            from_snapshot.edges.iter().map(|e| e.id.clone()).collect();
   955→        let to_edge_ids: std::collections::HashSet<String> =
   956→            to_snapshot.edges.iter().map(|e| e.id.clone()).collect();
   957→
   958→        let added_edges: Vec<SpecEdgeData> = to_snapshot
   959→            .edges
   960→            .iter()
   961→            .filter(|e| !from_edge_ids.contains(&e.id))
   962→            .cloned()
   963→            .collect();
   964→
   965→        let removed_edges: Vec<SpecEdgeData> = from_snapshot
   966→            .edges
   967→            .iter()
   968→            .filter(|e| !to_edge_ids.contains(&e.id))
   969→            .cloned()
   970→            .collect();
   971→
   972→        TemporalDiff {
   973→            from_timestamp,
   974→            to_timestamp,
   975→            added_nodes,
   976→            removed_nodes,
   977→            modified_nodes,
   978→            added_edges,
   979→            removed_edges,
   980→        }
   981→    }
