```

**After**:
```rust
// Project 情報を取得
let project = client.get_current_project(...).await?.project;
let repo_path = PathBuf::from(&project.storage_path);

// RepositoryClient を使って直接操作
let mut repo_client = RepositoryClient::from_project_path(&repo_path)?;

Commands::Add { content, no_infer } => {
    repo_client.add_node(content, NodeKind::Assertion)?;
    if !no_infer {
        repo_client.infer_all_relationships()?;
    }
    repo_client.save()?;
}
```

