     1→//! Unified command dispatcher (gRPC only)
     2→//!
     3→//! All commands are dispatched via gRPC to specd.
     4→//! There is no standalone mode -- specd must be running.
     5→
     6→use crate::proto::spec_oracle_client::SpecOracleClient;
     7→use crate::proto;
     8→use crate::utils::*;
     9→use crate::presentation::formatter::*;
    10→use crate::RpcCommands;
    11→use std::collections::HashMap;
    12→use tonic::Request;
    13→
    14→type Client = SpecOracleClient<tonic::transport::Channel>;
    15→
    16→/// Dispatch all commands via gRPC
    17→pub async fn dispatch(
    18→    command: crate::Commands,
    19→    mut client: Client,
    20→) -> Result<(), Box<dyn std::error::Error>> {
    21→    match command {
    22→        crate::Commands::Project(project_cmd) => {
    23→            crate::commands::project::dispatch_project(&mut client, project_cmd).await?;
    24→        }
    25→
    26→        crate::Commands::Add { content, no_infer } => {
    27→            crate::commands::add::execute_add_server(&mut client, content, no_infer).await?;
    28→        }
    29→        crate::Commands::Rpc(rpc_cmd) => {
    30→            dispatch_rpc(&mut client, rpc_cmd).await?;
    31→        }
    32→        crate::Commands::DetectContradictions => {
    33→            crate::commands::contradictions::execute_contradictions_server(&mut client).await?;
    34→        }
    35→        crate::Commands::DetectOmissions => {
    36→            crate::commands::omissions::execute_omissions_server(&mut client).await?;
    37→        }
    38→        crate::Commands::Check => {
    39→            let exit_code = crate::commands::check::execute_check_server(&mut client).await?;
    40→            if exit_code != 0 {
    41→                std::process::exit(exit_code);
    42→            }
    43→        }
    44→        crate::Commands::Summary => {
    45→            crate::commands::summary::execute_summary_server(&mut client).await?;
    46→        }
    47→        crate::Commands::Find { query, layer, status, max } => {
    48→            crate::commands::find::execute_find_server(&mut client, &query, layer, status, max).await?;
    49→        }
    50→        crate::Commands::Query { query, ai } => {
    51→            crate::commands::query::execute_query_server(&mut client, &query, ai).await?;
    52→        }
