   332→    pub async fn verify_consistency(
   333→        &self,
   334→        request: Request<proto::VerifyConsistencyRequest>,
   335→    ) -> Result<Response<proto::VerifyConsistencyResponse>, Status> {
   336→        let req = request.into_inner();
   337→        let state = self.model_state.lock()
   338→            .map_err(|e| Status::internal(format!("Lock error: {}", e)))?;
   339→
   340→        let spec_a_id = SpecId::parse(&req.spec_a_id)
   341→            .map_err(|e| Status::invalid_argument(format!("Invalid spec A ID: {}", e)))?;
   342→        let spec_b_id = SpecId::parse(&req.spec_b_id)
   343→            .map_err(|e| Status::invalid_argument(format!("Invalid spec B ID: {}", e)))?;
   344→
   345→        let aset_a = state.model.admissible_sets.get(&spec_a_id)
   346→            .ok_or_else(|| Status::not_found(format!("AdmissibleSet not found: {}", req.spec_a_id)))?;
   347→        let aset_b = state.model.admissible_sets.get(&spec_b_id)
   348→            .ok_or_else(|| Status::not_found(format!("AdmissibleSet not found: {}", req.spec_b_id)))?;
   349→
   350→        // Heuristic consistency check: look for obvious constraint conflicts
   351→        let (is_consistent, steps) = heuristic_consistency_check(aset_a, aset_b);
   352→
   353→        let status = if is_consistent {
   354→            proto::UdafProofStatus::Proven
   355→        } else {
   356→            proto::UdafProofStatus::Refuted
   357→        };
   358→
   359→        let proof = proto::UdafProofResult {
   360→            id: uuid::Uuid::new_v4().to_string(),
   361→            status: status.into(),
   362→            property_type: "consistency".to_string(),
   363→            steps,
   364→            method: "heuristic".to_string(),
   365→            metadata: HashMap::new(),
   366→        };
   367→
   368→        Ok(Response::new(proto::VerifyConsistencyResponse {
   369→            proof: Some(proof),
   370→            is_consistent,
   371→        }))
   372→    }
