   530→    pub async fn construct_u0(
   531→        &self,
   532→        request: Request<proto::ConstructU0Request>,
   533→    ) -> Result<Response<proto::ConstructU0Response>, Status> {
   534→        let req = request.into_inner();
   535→        let mut state = self.model_state.lock()
   536→            .map_err(|e| Status::internal(format!("Lock error: {}", e)))?;
   537→
   538→        // Create RootSpace from source paths
   539→        let mut root = RootSpace::new_artifact_bundle();
   540→
   541→        // Add source paths as metadata
   542→        for (i, path) in req.source_paths.iter().enumerate() {
   543→            root.meta.inner_mut().insert(
   544→                format!("source_path_{}", i),
   545→                path.clone(),
   546→            );
   547→        }
   548→        root.proof_data.artifact_count = req.source_paths.len();
   549→
   550→        // Add all non-U0 universes as source universes
   551→        for universe_id in state.model.universes.keys() {
   552→            if universe_id.layer() > 0 {
   553→                root.proof_data.add_source_universe(universe_id.as_str().to_string());
   554→            }
   555→        }
   556→
   557→        // Load repository for construct_u0
   558→        let pm = self.project_manager.lock()
   559→            .map_err(|e| Status::internal(format!("Lock error: {}", e)))?;
   560→        let current = pm.current_project()
   561→            .ok_or_else(|| Status::failed_precondition("No current project set"))?;
   562→        let project = pm.load_project(&current)
   563→            .map_err(|e| Status::internal(format!("Failed to load project: {}", e)))?;
   564→
   565→        let mut messages = Vec::new();
   566→
   567→        match state.model.construct_u0(&root, &project.repository) {
   568→            Ok(specs) => {
   569→                messages.push(format!("Successfully constructed U0 with {} extracted specifications", specs.len()));
   570→            }
   571→            Err(e) => {
   572→                messages.push(format!("Warning during U0 construction: {}", e));
   573→            }
   574→        }
   575→
   576→        // Get U0 for response
   577→        let u0_id = UniverseId::root();
   578→        let u0 = state.model.universes.get(&u0_id)
   579→            .ok_or_else(|| Status::internal("U0 not found after construction"))?;
   580→
   581→        let specs_count = u0.specifications.len() as u32;
   582→
   583→        Ok(Response::new(proto::ConstructU0Response {
   584→            u0: Some(to_proto_universe(&u0_id, u0)),
   585→            specs_extracted: specs_count,
   586→            messages,
   587→        }))
   588→    }
