   590→    pub async fn sync_model(
   591→        &self,
   592→        request: Request<proto::SyncModelRequest>,
   593→    ) -> Result<Response<proto::SyncModelResponse>, Status> {
   594→        let req = request.into_inner();
   595→        let mut state = self.model_state.lock()
   596→            .map_err(|e| Status::internal(format!("Lock error: {}", e)))?;
   597→
   598→        let pm = self.project_manager.lock()
   599→            .map_err(|e| Status::internal(format!("Lock error: {}", e)))?;
   600→        let current = pm.current_project()
   601→            .ok_or_else(|| Status::failed_precondition("No current project set"))?;
   602→        let mut project = pm.load_project(&current)
   603→            .map_err(|e| Status::internal(format!("Failed to load project: {}", e)))?;
   604→
   605→        let mut messages = Vec::new();
   606→
   607→        // Sync from repository to model
   608→        ModelSync::sync_from_repository(&mut state.model, &project.repository)
   609→            .map_err(|e| Status::internal(format!("Sync failed: {}", e)))?;
   610→
   611→        messages.push("Synchronized UDA/f model from repository".to_string());
   612→
   613→        // Optionally export proof metadata back
   614→        if req.export_proof_metadata {
   615→            ModelSync::export_proof_metadata(&state.model, &mut project.repository)
   616→                .map_err(|e| Status::internal(format!("Export failed: {}", e)))?;
   617→
   618→            // Save updated repository
   619→            pm.save_project(&project)
   620→                .map_err(|e| Status::internal(format!("Failed to save project: {}", e)))?;
