   660→
   661→fn to_proto_universe(id: &UniverseId, u: &spec_core::formal::Universe) -> proto::UdafUniverse {
   662→    let spec_ids: Vec<String> = u.specifications.iter()
   663→        .map(|s| s.as_str().to_string())
   664→        .collect();
   665→
   666→    let metadata: HashMap<String, String> = u.metadata.inner().clone();
   667→
