   962→        description: format!("Checking {} constraints from A against {} constraints from B", constraints_a.len(), constraints_b.len()),
   963→        justification: "Heuristic pairwise constraint analysis".to_string(),
   964→    });
   965→
   966→    // Check for min/max conflicts
   967→    for ca in &constraints_a {
