**既存ファイル**: `proto/spec_oracle.proto` - 26 RPCs のみ残す

#### Phase 4: spec-cli に2つのクライアントを統合

```rust
pub struct DualClient {
    udaf_client: SpecOracleClient<Channel>,      // specd:50051
    repo_client: SpecRepositoryClient<Channel>,  // spec-repository-server:50052
}

impl DualClient {
    pub async fn connect(udaf_addr: String, repo_addr: String) -> Result<Self> {
        Ok(Self {
            udaf_client: SpecOracleClient::connect(udaf_addr).await?,
            repo_client: SpecRepositoryClient::connect(repo_addr).await?,
        })
    }
}

// Commands dispatch
Commands::Add { content, no_infer } => {
    client.repo_client.add_node(...).await?;
