    current_project: Arc<RwLock<Option<String>>>,
    repositories: Arc<RwLock<HashMap<String, SpecRepository>>>,
}

impl SpecRepositoryServiceImpl {
    pub fn new() -> Self {
        Self {
            current_project: Arc::new(RwLock::new(None)),
            repositories: Arc::new(RwLock::new(HashMap::new())),
        }
    }

    async fn get_current_repository(&self) -> Result<SpecRepository> {
        let project = self.current_project.read().await
            .clone()
            .ok_or_else(|| Status::failed_precondition("No project selected"))?;

        let repos = self.repositories.read().await;
        repos.get(&project)
            .cloned()
            .ok_or_else(|| Status::not_found("Project repository not found"))
    }
}

