#[tonic::async_trait]
impl UdafService for UDAFServiceImpl {
    // 26 RPCs を実装
}
```

**specd/src/repository_service.rs** (新規):
```rust
pub struct RepositoryServiceImpl {
    project_manager: Arc<RwLock<ProjectManager>>,  // UDAFService と共有
    repositories: Arc<RwLock<HashMap<String, SpecRepository>>>,  // project_name -> SpecRepository
}

#[tonic::async_trait]
impl RepositoryService for RepositoryServiceImpl {
    // 28 RPCs を実装
}
```

**specd/src/main.rs**:
```rust
#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let addr = "[::1]:50051".parse()?;

    // 共有状態
    let project_manager = Arc::new(RwLock::new(ProjectManager::new(...)?));

    // 2つのサービス
    let udaf_svc = UDAFServiceImpl::new(project_manager.clone());
    let repo_svc = RepositoryServiceImpl::new(project_manager.clone());

    // 単一サーバーに両方のサービスを登録
    Server::builder()
        .add_service(UdafServiceServer::new(udaf_svc))
        .add_service(RepositoryServiceServer::new(repo_svc))
        .serve(addr)
