async fn get_current_project(
    &self,
    _request: Request<GetCurrentProjectRequest>,
) -> Result<Response<GetCurrentProjectResponse>, Status> {
    let pm = self.project_manager.read().await;
    let current_name = pm.current_project()
        .ok_or_else(|| Status::not_found("No current project set"))?;

    let project_info = pm.list_projects()
        .map_err(|e| Status::internal(e.to_string()))?
        .into_iter()
        .find(|p| p.name == current_name)
        .ok_or_else(|| Status::not_found("Current project not found"))?;

    // Get storage path from backend
    let storage_path = match &project_info.storage {
        StorageConfig::LocalFile { base_path } => {
            Some(base_path.join(&project_info.name).display().to_string())
        }
        _ => None,
    }.unwrap_or_default();

    Ok(Response::new(GetCurrentProjectResponse {
        project: Some(proto::Project {
            name: project_info.name,
            description: project_info.description,
            created_at: project_info.created_at,
            node_count: project_info.node_count as u32,
            edge_count: project_info.edge_count as u32,
            storage: map_storage_config(&project_info.storage),
            storage_path,
        }),
    }))
}
