## Phase 3: spec-cli に RepositoryClient を追加

### 新規モジュール: `spec-cli/src/repository_client.rs`

```rust
//! Direct access to SpecRepository without gRPC
//!
//! This module provides a client that directly manipulates the spec repository
//! on the filesystem, bypassing specd for Node/Edge operations.

use anyhow::{Context, Result};
use spec_core::data::{EdgeKind, NodeKind, SpecEdgeData, SpecNodeData, SpecRepository};
use spec_core::store::{DirectoryStore, Store};
use std::collections::HashMap;
use std::path::{Path, PathBuf};

/// Client for direct SpecRepository access
///
/// This client loads and saves the repository directly from/to the filesystem,
/// without going through specd's gRPC interface.
pub struct RepositoryClient {
    project_path: PathBuf,
    repository: SpecRepository,
}

impl RepositoryClient {
    /// Create a new RepositoryClient from a project path
    ///
    /// # Arguments
    /// * `path` - Absolute path to the project directory (e.g., ~/.specd/projects/my-project)
    ///
    /// # Returns
    /// A RepositoryClient with the loaded repository
    pub fn from_project_path(path: impl AsRef<Path>) -> Result<Self> {
        let project_path = path.as_ref().to_path_buf();
        let store = Store::from_directory(&project_path);
        let repository = store
            .load()
            .with_context(|| format!("Failed to load repository from {}", project_path.display()))?;

        Ok(Self {
            project_path,
            repository,
        })
    }

    /// Save the repository back to storage
    pub fn save(&self) -> Result<()> {
        let store = Store::from_directory(&self.project_path);
        store
            .save(&self.repository)
            .with_context(|| format!("Failed to save repository to {}", self.project_path.display()))?;
        Ok(())
    }

    // ========================================================================
    // Node operations
    // ========================================================================

    pub fn add_node(&mut self, content: String, kind: NodeKind) -> Result<String> {
        let node = self.repository.add_node(content, kind, HashMap::new());
        Ok(node.id.clone())
    }

    pub fn get_node(&self, id: &str) -> Result<&SpecNodeData> {
        self.repository
            .get_node(id)
            .ok_or_else(|| anyhow::anyhow!("Node not found: {}", id))
    }

    pub fn list_nodes(&self, kind_filter: Option<NodeKind>) -> Vec<&SpecNodeData> {
        self.repository.list_nodes(kind_filter)
    }

    pub fn remove_node(&mut self, id: &str) -> Result<()> {
        self.repository
            .remove_node(id)
            .ok_or_else(|| anyhow::anyhow!("Node not found: {}", id))?;
        Ok(())
    }

    // ========================================================================
    // Edge operations
    // ========================================================================

    pub fn add_edge(
        &mut self,
        source_id: &str,
        target_id: &str,
        kind: EdgeKind,
    ) -> Result<String> {
        let edge = self
            .repository
            .add_edge(source_id, target_id, kind, HashMap::new())
            .with_context(|| "Failed to add edge")?;
        Ok(edge.id.clone())
    }

    pub fn list_edges(&self, node_id: Option<&str>) -> Vec<(&SpecEdgeData, &str, &str)> {
        self.repository.list_edges(node_id)
    }

    pub fn remove_edge(&mut self, id: &str) -> Result<()> {
        self.repository
            .remove_edge(id)
            .ok_or_else(|| anyhow::anyhow!("Edge not found: {}", id))?;
        Ok(())
    }

    // ========================================================================
    // Query operations
    // ========================================================================

    pub fn search(&self, query: &str) -> Vec<&SpecNodeData> {
        self.repository.search(query)
    }

    pub fn filter_by_layer(&self, min: u8, max: u8) -> Vec<&SpecNodeData> {
        self.repository.filter_by_layer(min, max)
    }

    pub fn trace_relationships(
        &self,
        node_id: &str,
        max_depth: usize,
    ) -> Vec<(SpecNodeData, EdgeKind, String, usize)> {
        self.repository.trace_relationships(node_id, max_depth)
    }

    pub fn find_formalizations(&self, node_id: &str) -> Vec<&SpecNodeData> {
        self.repository.find_formalizations(node_id)
    }

    pub fn find_natural_source(&self, node_id: &str) -> Vec<&SpecNodeData> {
        self.repository.find_natural_source(node_id)
    }

    // ========================================================================
    // Analysis operations
    // ========================================================================

    pub fn detect_contradictions(&self) -> Vec<spec_core::data::Contradiction> {
        self.repository.detect_contradictions()
    }

    pub fn detect_omissions(&self) -> Vec<spec_core::data::Omission> {
        self.repository.detect_omissions()
    }

    pub fn resolve_term(&self, term: &str) -> (Vec<&SpecNodeData>, Vec<String>) {
        self.repository.resolve_term(term)
    }

    pub fn find_related_terms(&self, term: &str) -> Vec<(&SpecNodeData, f32)> {
        self.repository.find_related_terms(term)
    }

    pub fn detect_potential_synonyms(&self) -> Vec<(SpecNodeData, SpecNodeData, f32)> {
        self.repository.detect_potential_synonyms()
    }

    // ========================================================================
    // Statistics
    // ========================================================================

    pub fn node_count(&self) -> usize {
        self.repository.node_count()
    }

    pub fn edge_count(&self) -> usize {
        self.repository.edge_count()
    }

    // ========================================================================
    // Export
    // ========================================================================

    pub fn export_dot(&self) -> String {
        self.repository.export_dot()
    }
}
```

