//! UDA/f Service Implementation for specd
//!
//! Implements UDAFService gRPC operations for managing the UDA/f model
//! (Universe, Domain, AdmissibleSet, Transform).

use crate::project::ProjectManager;
use crate::proto;
use spec_core::formal::{...};
use std::sync::{Arc, RwLock};
use tonic::{Request, Response, Status};

pub struct UDAFServiceImpl {
    project_manager: Arc<RwLock<ProjectManager>>,
    model_state: Arc<RwLock<HashMap<String, UDAFModel>>>,  // project_name -> UDAFModel
}

impl UDAFServiceImpl {
    pub fn new(project_manager: Arc<RwLock<ProjectManager>>) -> Self {
        Self {
            project_manager,
            model_state: Arc::new(RwLock::new(HashMap::new())),
        }
    }

    // Helper: Get or create model for current project
    fn get_or_create_model(&self, project_name: &str) -> Result<UDAFModel, Status> {
        let mut models = self.model_state.write()
            .map_err(|e| Status::internal(format!("Lock error: {}", e)))?;

        if !models.contains_key(project_name) {
            models.insert(project_name.to_string(), UDAFModel::new());
        }

        Ok(models.get(project_name).unwrap().clone())
    }
}

