//! Repository Service Implementation for specd
//!
//! Implements RepositoryService gRPC operations for managing specification data
//! (Nodes, Edges, Queries, Temporal operations).

use crate::project::{ProjectManager, Project};
use crate::proto;
use spec_core::data::SpecRepository;
use std::sync::{Arc, RwLock};
use tonic::{Request, Response, Status};

pub struct RepositoryServiceImpl {
    project_manager: Arc<RwLock<ProjectManager>>,  // Shared with UDAFService
}

impl RepositoryServiceImpl {
    pub fn new(project_manager: Arc<RwLock<ProjectManager>>) -> Self {
        Self { project_manager }
    }

    /// Get the current project or use the specified project name
    fn get_project(&self, project_name: &str) -> Result<Project, Status> {
        let pm = self.project_manager.lock()
            .map_err(|e| Status::internal(format!("Lock error: {}", e)))?;

        let name = if project_name.is_empty() {
            pm.current_project()
                .ok_or_else(|| Status::failed_precondition("No current project set"))?
        } else {
            project_name.to_string()
        };

        pm.load_project(&name)
            .map_err(|e| Status::not_found(format!("Project not found: {}", e)))
    }

    /// Save a project back to storage
    fn save_project(&self, project: &Project) -> Result<(), Status> {
        let pm = self.project_manager.lock()
            .map_err(|e| Status::internal(format!("Lock error: {}", e)))?;

        pm.save_project(project)
            .map_err(|e| Status::internal(format!("Failed to save project: {}", e)))
    }
}

#[tonic::async_trait]
impl proto::repository_service_server::RepositoryService for RepositoryServiceImpl {
    // Implement all 28 RepositoryService RPCs
    async fn add_node(...) -> Result<Response<...>, Status> { /* ... */ }
    async fn query(...) -> Result<Response<...>, Status> { /* ... */ }
    // ... (all other repository operations)
}
```

