use repository_service::RepositoryServiceImpl;
use tonic::transport::Server;
use tracing_subscriber::EnvFilter;
use std::sync::{Arc, RwLock};

pub mod proto {
    tonic::include_proto!("spec_oracle");
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Load configuration
    let config = SpecdConfig::load_or_default()?;

    // Initialize logging
    tracing_subscriber::fmt()
        .with_env_filter(
            EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| EnvFilter::new(&config.log_level))
        )
        .init();

    tracing::info!("Starting specd...");
    tracing::info!("Projects directory: {}", config.default_path.display());

    // Initialize project manager
    let mut project_manager = ProjectManager::new(config.default_path.clone());
    project_manager.discover_projects()?;
    project_manager.ensure_default()?;

    tracing::info!("Loaded {} project(s)", project_manager.list_projects()?.len());

    // Shared state
    let project_manager = Arc::new(RwLock::new(project_manager));

    // Create two services sharing the same ProjectManager
    let udaf_svc = UDAFServiceImpl::new(project_manager.clone());
    let repo_svc = RepositoryServiceImpl::new(project_manager.clone());

    // Start gRPC server with BOTH services
    let addr = config.listen_address.parse()?;

    tracing::info!("specd listening on {}", addr);
    tracing::info!("  - UDAFService: 26 RPCs (formal verification)");
    tracing::info!("  - RepositoryService: 28 RPCs (data operations)");

    Server::builder()
        .add_service(proto::udaf_service_server::UdafServiceServer::new(udaf_svc))
        .add_service(proto::repository_service_server::RepositoryServiceServer::new(repo_svc))
        .serve(addr)
        .await?;

