     1→/// UDAF Model: The complete multi-universe specification model
     2→///
     3→/// This is the core data structure that implements the theoretical foundation
     4→/// of specORACLE as described in conversation.md and motivation.md.
     5→use serde::{Deserialize, Serialize};
     6→use std::collections::{HashMap, HashSet};
     7→use crate::formal::*;
     8→use crate::formal::projection::RootSpace;
     9→use crate::formal::transform::ObserverKind;
    10→use crate::{InferredSpecification, RustExtractor};
    11→use crate::data::SpecRepository;
    12→
    13→#[derive(Debug, Clone, Serialize, Deserialize)]
    14→pub struct UDAFModel {
    15→    /// All universes in the model (keyed by UniverseId)
    16→    #[serde(with = "super::serde_helpers::universe_map_serde")]
    17→    pub universes: HashMap<UniverseId, Universe>,
    18→
    19→    /// All domains across all universes (keyed by DomainId)
    20→    #[serde(with = "super::serde_helpers::domain_map_serde")]
    21→    pub domains: HashMap<DomainId, Domain>,
    22→
    23→    /// All admissible sets (one per specification, keyed by SpecId)
    24→    #[serde(with = "super::serde_helpers::admissible_map_serde")]
    25→    pub admissible_sets: HashMap<SpecId, AdmissibleSet>,
    26→
    27→    /// All transform functions between universes (keyed by TransformId)
    28→    #[serde(with = "super::serde_helpers::transform_map_serde")]
    29→    pub transforms: HashMap<TransformId, TransformFunction>,
    30→
    31→    /// Metadata for extensibility
    32→    pub metadata: Metadata,
    33→
    34→    /// Prover instance for formal verification (not serialized)
    35→    #[serde(skip)]
    36→    #[cfg(feature = "z3-solver")]
    37→    prover: Prover,
    38→}
    39→
    40→impl UDAFModel {
    41→    pub fn new() -> Self {
    42→        let mut model = Self {
    43→            universes: HashMap::new(),
    44→            domains: HashMap::new(),
    45→            admissible_sets: HashMap::new(),
    46→            transforms: HashMap::new(),
    47→            metadata: Metadata::new(),
    48→            #[cfg(feature = "z3-solver")]
    49→            prover: Prover::new(),
    50→        };
    51→
    52→        // Always create U0 (root universe)
    53→        let u0 = Universe::root();
    54→        model.universes.insert(u0.id.clone(), u0);
    55→
    56→        model
    57→    }
    58→
    59→    /// Add a projection universe (U1, U2, etc.)
    60→    ///
    61→    /// Returns the universe ID or an error if layer is invalid
    62→    pub fn add_universe(&mut self, layer: u8, name: String, description: String) -> Result<UniverseId, IdError> {
    63→        let universe = Universe::projection(layer, name, description)?;
    64→        let id = universe.id.clone();
    65→        self.universes.insert(id.clone(), universe);
    66→        Ok(id)
    67→    }
    68→
    69→    /// Add a domain to a universe
    70→    pub fn add_domain(&mut self, domain: Domain) -> DomainId {
    71→        let id = domain.id.clone();
    72→        self.domains.insert(id.clone(), domain);
    73→        id
    74→    }
    75→
    76→    /// Add an admissible set for a specification
    77→    pub fn add_admissible_set(&mut self, admissible_set: AdmissibleSet) -> SpecId {
    78→        let id = admissible_set.spec_id.clone();
    79→        self.admissible_sets.insert(id.clone(), admissible_set);
    80→        id
    81→    }
    82→
    83→    /// Add a transform function
    84→    pub fn add_transform(&mut self, transform: TransformFunction) -> TransformId {
    85→        let id = transform.id.clone();
    86→        self.transforms.insert(id.clone(), transform);
    87→        id
    88→    }
    89→
    90→    /// Construct U0 from all projection universes via inverse mappings
    91→    ///
    92→    /// U0 = f₀₁⁻¹(U1) ∪ f₀₂⁻¹(U2) ∪ ... ∪ f₀ₙ⁻¹(UN)
    93→    ///
    94→    /// This is the core operation that realizes the theoretical model.
    95→    /// Returns the newly extracted InferredSpecification objects that should be ingested into the graph.
    96→    pub fn construct_u0(&mut self, root: &RootSpace, graph: &SpecRepository) -> Result<Vec<InferredSpecification>, String> {
    97→        // Collect all newly extracted specifications from projection universes
    98→        let mut newly_created_specs = Vec::new();
    99→
   100→        // For each projection universe (U1, U2, U3...)
   101→        for universe_id in self.universes.keys() {
   102→            if universe_id.layer() == 0 {
   103→                continue;  // Skip U0 itself
   104→            }
   105→
   106→            // Find the inverse transform for this universe
   107→            let inverse_transform_id = TransformId::inverse(universe_id);
   108→
   109→            if let Some(transform) = self.transforms.get(&inverse_transform_id) {
   110→                // Execute the transform strategy to extract/map specifications
   111→                let extracted_specs = self.execute_transform(transform, root, graph)?;
   112→                newly_created_specs.extend(extracted_specs);
   113→            }
   114→        }
   115→
   116→        Ok(newly_created_specs)
   117→    }
   118→
   119→    /// Execute a transform strategy to extract specifications
   120→    fn execute_transform(
   121→        &self,
   122→        transform: &TransformFunction,
   123→        root: &RootSpace,
   124→        graph: &SpecRepository,
   125→    ) -> Result<Vec<InferredSpecification>, String> {
   126→        match &transform.strategy {
   127→            TransformStrategy::ASTAnalysis { language, extractor_config } => {
   128→                // Execute AST analysis for the specified language
   129→                if language == "rust" {
   130→                    self.execute_rust_ast_analysis(extractor_config, graph)
   131→                } else {
   132→                    Err(format!("Unsupported language: {}", language))
   133→                }
   134→            }
   135→            TransformStrategy::Manual { description: _ } => {
   136→                // Manual transforms don't auto-execute
   137→                Ok(Vec::new())
   138→            }
   139→            _ => {
   140→                // Other strategies not yet implemented
   141→                Ok(Vec::new())
   142→            }
   143→        }
   144→    }
   145→
   146→    /// Execute a Rust projection through the observer >> extractor composition.
   147→    ///
   148→    /// This implements the projection pipeline from paper section 2.6:
   149→    ///   RootSpace ->[obs_i]-> ArtifactSpace ->[extract_i]-> Vec<InferredSpecification>
   150→    ///
   151→    /// Steps:
   152→    /// 1. Instantiate observer from ObserverKind
   153→    /// 2. Create RustExtractor
   154→    /// 3. Observe root space to produce ArtifactSpace
   155→    /// 4. Extract InferredSpecifications from ArtifactSpace
   156→    /// 5. Filter results by min_confidence
   157→    #[allow(dead_code)]
   158→    fn execute_rust_projection(
   159→        &self,
   160→        observer_kind: &ObserverKind,
   161→        extractor_config: &HashMap<String, String>,
   162→        root: &RootSpace,
   163→        target_layer: &UniverseId,
   164→    ) -> Result<Vec<InferredSpecification>, String> {
   165→        use crate::formal::projection::Extractor as ExtractorTrait;
   166→
   167→        // Step 1: Instantiate observer from ObserverKind
   168→        let observer = observer_kind.instantiate(ArtifactKind::SourceCode);
   169→
   170→        // Step 2: Observe root space -> ArtifactSpace (obs_i: Omega -> Option Gamma_i)
   171→        let artifact = match observer.observe(root, target_layer) {
   172→            Some(a) => a,
   173→            None => return Ok(Vec::new()),
   174→        };
   175→
   176→        // Step 3: Extract specifications (extract_i: Gamma_i -> Vec<beta_i>)
   177→        let extractor = RustExtractor;
   178→        let all_specs: Vec<InferredSpecification> = extractor.extract(&artifact);
   179→
   180→        // Step 4: Filter by confidence threshold
   181→        let min_confidence = extractor_config
   182→            .get("min_confidence")
   183→            .and_then(|s| s.parse::<f32>().ok())
   184→            .unwrap_or(0.7);
   185→
   186→        let filtered: Vec<InferredSpecification> = all_specs
   187→            .into_iter()
   188→            .filter(|spec| spec.confidence >= min_confidence)
   189→            .collect();
   190→
   191→        Ok(filtered)
   192→    }
   193→
   194→    /// Execute Rust AST analysis to extract specifications from code
   195→    fn execute_rust_ast_analysis(
   196→        &self,
   197→        config: &HashMap<String, String>,
   198→        graph: &SpecRepository,
   199→    ) -> Result<Vec<InferredSpecification>, String> {
   200→        use std::path::Path;
   201→
   202→        // Get source files from config or find them in graph metadata
   203→        let source_files = self.find_rust_source_files(config, graph)?;
   204→
   205→        let mut extracted_specs = Vec::new();
   206→
   207→        for file_path in source_files {
   208→            let path = Path::new(&file_path);
   209→
   210→            // Extract specifications using RustExtractor
   211→            match RustExtractor::extract(path) {
   212→                Ok(inferred_specs) => {
   213→                    // Filter by confidence threshold from config
   214→                    let min_confidence = config
   215→                        .get("min_confidence")
   216→                        .and_then(|s| s.parse::<f32>().ok())
   217→                        .unwrap_or(0.7);
   218→
   219→                    for spec in inferred_specs {
   220→                        if spec.confidence >= min_confidence {
   221→                            // Return the actual InferredSpecification objects
   222→                            // These will be ingested into the graph
   223→                            extracted_specs.push(spec);
   224→                        }
   225→                    }
   226→                }
   227→                Err(e) => {
   228→                    eprintln!("Warning: Failed to extract from {}: {}", file_path, e);
   229→                }
   230→            }
   231→        }
   232→
   233→        Ok(extracted_specs)
   234→    }
