   367→            constraints.push(Constraint {
   368→                formal: Some(format!("<= {}", max_value)),
   369→                kind: ConstraintKind::Universal,
   370→                description: Some(description_text),
   371→                metadata: Some(meta),
   372→                meta: Some(meta_with_desc),
   373→            });
   374→        }
   375→
   376→        // Pattern 3: "minimum N" / "minimum of N"
   377→        if let Some(min_value) = self.extract_numeric_value(&lower_text, "minimum") {
   378→            let mut meta = ConstraintMetadata::new();
   379→            meta.set_pattern("minimum".to_string());
   380→            meta.set_value(min_value.to_string());
   381→            meta.set_source(text.to_string());
   382→
   383→            let description_text = format!("Minimum value: {}", min_value);
   384→            let mut meta_with_desc = meta.clone();
   385→            meta_with_desc.insert(MetadataKey::Custom("description".to_string()), description_text.clone());
   386→
   387→            constraints.push(Constraint {
   388→                formal: Some(format!(">= {}", min_value)),
   389→                kind: ConstraintKind::Universal,
   390→                description: Some(description_text),
   391→                metadata: Some(meta),
   392→                meta: Some(meta_with_desc),
   393→            });
   394→        }
   395→
   396→        // Pattern 4: "maximum N" / "maximum of N"
   397→        if let Some(max_value) = self.extract_numeric_value(&lower_text, "maximum") {
   398→            let mut meta = ConstraintMetadata::new();
   399→            meta.set_pattern("maximum".to_string());
   400→            meta.set_value(max_value.to_string());
   401→            meta.set_source(text.to_string());
   402→
   403→            let description_text = format!("Maximum value: {}", max_value);
   404→            let mut meta_with_desc = meta.clone();
   405→            meta_with_desc.insert(MetadataKey::Custom("description".to_string()), description_text.clone());
   406→
   407→            constraints.push(Constraint {
   408→                formal: Some(format!("<= {}", max_value)),
   409→                kind: ConstraintKind::Universal,
   410→                description: Some(description_text),
   411→                metadata: Some(meta),
   412→                meta: Some(meta_with_desc),
   413→            });
   414→        }
   415→
   416→        // Pattern 5: "exactly N"
   417→        if let Some(exact_value) = self.extract_numeric_value(&lower_text, "exactly") {
   418→            let mut meta = ConstraintMetadata::new();
   419→            meta.set_pattern("exactly".to_string());
   420→            meta.set_value(exact_value.to_string());
   421→            meta.set_source(text.to_string());
   422→
   423→            let description_text = format!("Exact value: {}", exact_value);
   424→            let mut meta_with_desc = meta.clone();
   425→            meta_with_desc.insert(MetadataKey::Custom("description".to_string()), description_text.clone());
   426→
   427→            constraints.push(Constraint {
   428→                formal: Some(format!("== {}", exact_value)),
   429→                kind: ConstraintKind::Universal,
   430→                description: Some(description_text),
   431→                metadata: Some(meta),
   432→                meta: Some(meta_with_desc),
   433→            });
   434→        }
   435→
   436→        // Pattern 6: "between X and Y"
   437→        if let Some((min, max)) = self.extract_range(&lower_text) {
   438→            let mut meta = ConstraintMetadata::new();
   439→            meta.set_pattern("range".to_string());
   440→            meta.set_min(min.to_string());
   441→            meta.set_max(max.to_string());
   442→            meta.set_source(text.to_string());
   443→
   444→            let description_text = format!("Range: {} to {}", min, max);
   445→            let mut meta_with_desc = meta.clone();
   446→            meta_with_desc.insert(MetadataKey::Custom("description".to_string()), description_text.clone());
   447→
   448→            constraints.push(Constraint {
   449→                formal: Some(format!(">= {} && <= {}", min, max)),
   450→                kind: ConstraintKind::Universal,
   451→                description: Some(description_text),
   452→                metadata: Some(meta),
   453→                meta: Some(meta_with_desc),
   454→            });
   455→        }
   456→
   457→        // Pattern 7: "must be" (boolean requirement)
   458→        if lower_text.contains("must be") && !lower_text.contains("at least") && !lower_text.contains("at most") {
   459→            // Extract what must be
   460→            if let Some(pos) = lower_text.find("must be") {
   461→                let after = &text[pos + 7..].trim();
   462→                if !after.is_empty() {
   463→                    let mut meta = ConstraintMetadata::new();
   464→                    meta.set_pattern("must_be".to_string());
   465→                    meta.set_value(after.to_string());
   466→                    meta.set_source(text.to_string());
   467→
   468→                    let description_text = format!("Required: {}", after);
   469→                    let mut meta_with_desc = meta.clone();
   470→                    meta_with_desc.insert(MetadataKey::Custom("description".to_string()), description_text.clone());
   471→
   472→                    constraints.push(Constraint {
   473→                        formal: Some(format!("== {}", after)),
   474→                        kind: ConstraintKind::Universal,
   475→                        description: Some(description_text),
   476→                        metadata: Some(meta),
   477→                        meta: Some(meta_with_desc),
   478→                    });
   479→                }
   480→            }
   481→        }
   482→
   483→        // Pattern 8: "must not be" / "cannot be" (boolean prohibition)
   484→        if lower_text.contains("must not") || lower_text.contains("cannot be") {
   485→            let pattern = if lower_text.contains("must not") { "must not" } else { "cannot be" };
   486→            if let Some(pos) = lower_text.find(pattern) {
   487→                let after = &text[pos + pattern.len()..].trim();
   488→                if !after.is_empty() {
   489→                    let mut meta = ConstraintMetadata::new();
   490→                    meta.set_pattern("must_not_be".to_string());
   491→                    meta.set_value(after.to_string());
   492→                    meta.set_source(text.to_string());
   493→
   494→                    let description_text = format!("Forbidden: {}", after);
   495→                    let mut meta_with_desc = meta.clone();
   496→                    meta_with_desc.insert(MetadataKey::Custom("description".to_string()), description_text.clone());
   497→
   498→                    constraints.push(Constraint {
   499→                        formal: Some(format!("!= {}", after)),
   500→                        kind: ConstraintKind::Universal,
   501→                        description: Some(description_text),
   502→                        metadata: Some(meta),
   503→                        meta: Some(meta_with_desc),
   504→                    });
   505→                }
   506→            }
   507→        }
   508→
   509→        constraints
   510→    }
