   512→    /// Extract numeric value after a keyword
   513→    fn extract_numeric_value(&self, text: &str, keyword: &str) -> Option<i64> {
   514→        if let Some(pos) = text.find(keyword) {
   515→            let after = &text[pos + keyword.len()..];
   516→            for word in after.split_whitespace() {
   517→                if let Ok(n) = word.trim_matches(|c: char| !c.is_numeric()).parse::<i64>() {
   518→                    return Some(n);
   519→                }
   520→            }
   521→        }
   522→        None
   523→    }
   524→
   525→    /// Extract range from "between X and Y" pattern
   526→    fn extract_range(&self, text: &str) -> Option<(i64, i64)> {
   527→        if let Some(pos) = text.find("between") {
   528→            let after = &text[pos + 7..];
   529→            let parts: Vec<&str> = after.split("and").collect();
   530→            if parts.len() >= 2 {
   531→                let min = self.extract_first_number(parts[0])?;
   532→                let max = self.extract_first_number(parts[1])?;
   533→                return Some((min, max));
   534→            }
   535→        }
   536→        None
   537→    }
   538→
   539→    /// Extract first number from string
   540→    fn extract_first_number(&self, s: &str) -> Option<i64> {
   541→        for word in s.split_whitespace() {
   542→            if let Ok(n) = word.trim_matches(|c: char| !c.is_numeric()).parse::<i64>() {
   543→                return Some(n);
   544→            }
   545→        }
   546→        None
   547→    }
