   549→    /// Validate all reference integrity across the model
   550→    ///
   551→    /// Checks:
   552→    /// - Universe specifications reference valid SpecIds
   553→    /// - Domain universe_id references valid UniverseIds
   554→    /// - Domain covered_by references valid SpecIds
   555→    /// - Domain subdomains references valid DomainIds
   556→    /// - AdmissibleSet universe_id references valid UniverseIds
   557→    /// - AdmissibleSet contradicts references valid SpecIds
   558→    /// - Transform source/target universes reference valid UniverseIds
   559→    ///
   560→    /// Returns Ok(()) if all references are valid, or Err with details of invalid references
   561→    pub fn validate(&self) -> Result<(), String> {
   562→        let mut errors = Vec::new();
   563→
   564→        // Collect all valid IDs for reference checking
   565→        let valid_universe_ids: HashSet<String> = self.universes.keys()
   566→            .map(|id| id.as_str().to_string())
   567→            .collect();
   568→
   569→        let valid_spec_ids: HashSet<String> = self.admissible_sets.keys()
   570→            .map(|id| id.as_str().to_string())
   571→            .collect();
   572→
   573→        let valid_domain_ids: HashSet<String> = self.domains.keys()
   574→            .map(|id| id.as_str().to_string())
   575→            .collect();
   576→
   577→        // Validate Universe references
   578→        for (universe_id, universe) in &self.universes {
   579→            // Check that all specifications in the universe exist
   580→            let invalid_specs = universe.specifications.check_integrity(&valid_spec_ids);
   581→            if !invalid_specs.is_empty() {
   582→                errors.push(format!(
   583→                    "Universe {} references non-existent specifications: {:?}",
   584→                    universe_id.as_str(),
   585→                    invalid_specs
   586→                ));
   587→            }
   588→        }
   589→
   590→        // Validate Domain references
   591→        for (domain_id, domain) in &self.domains {
   592→            // Check that universe_id exists (try meta first, fall back to old field)
   593→            let universe_id_str = if let Some(meta) = &domain.meta {
   594→                meta.get_str("universe_id").map(|s| s.as_str())
   595→            } else {
   596→                domain.universe_id.as_ref().map(|id| id.as_str())
   597→            };
   598→
   599→            if let Some(uid_str) = universe_id_str
   600→                && !valid_universe_ids.contains(uid_str) {
   601→                    errors.push(format!(
   602→                        "Domain {} references non-existent universe: {}",
   603→                        domain_id.as_str(),
   604→                        uid_str
   605→                    ));
   606→                }
   607→
   608→            // Check that all covered_by specs exist (try proof_data first, fall back to old field)
   609→            let covered_by = if let Some(proof_data) = &domain.proof_data {
   610→                Some(&proof_data.covered_by)
   611→            } else {
   612→                domain.covered_by.as_ref()
   613→            };
   614→
   615→            if let Some(covered_by_set) = covered_by {
   616→                let invalid_specs = covered_by_set.check_integrity(&valid_spec_ids);
   617→                if !invalid_specs.is_empty() {
   618→                    errors.push(format!(
   619→                        "Domain {} references non-existent specifications in covered_by: {:?}",
   620→                        domain_id.as_str(),
   621→                        invalid_specs
   622→                    ));
   623→                }
   624→            }
   625→
   626→            // Check that all subdomains exist (from meta)
   627→            if let Some(meta) = &domain.meta {
   628→                if let Some(_subdomains_str) = meta.get_str("subdomains") {
   629→                    // Note: This is a simplified check; actual subdomain validation would need proper parsing
   630→                    // For now, skip subdomain validation for new structure
   631→                }
   632→            } else if let Some(subdomains) = &domain.subdomains {
   633→                let invalid_domains = subdomains.check_integrity(&valid_domain_ids);
   634→                if !invalid_domains.is_empty() {
   635→                    errors.push(format!(
   636→                        "Domain {} references non-existent subdomains: {:?}",
   637→                        domain_id.as_str(),
   638→                        invalid_domains
   639→                    ));
   640→                }
   641→            }
   642→        }
   643→
   644→        // Validate AdmissibleSet references
   645→        for (spec_id, admissible_set) in &self.admissible_sets {
   646→            // Check that universe_id exists (try meta first, fall back to old field)
   647→            let universe_id_ref = if let Some(meta) = &admissible_set.meta {
   648→                Some(&meta.universe_id)
   649→            } else {
   650→                admissible_set.universe_id.as_ref()
   651→            };
   652→
   653→            if let Some(uid) = universe_id_ref
   654→                && !valid_universe_ids.contains(uid.as_str()) {
   655→                    errors.push(format!(
   656→                        "AdmissibleSet {} references non-existent universe: {}",
   657→                        spec_id.as_str(),
   658→                        uid.as_str()
   659→                    ));
   660→                }
   661→
   662→            // Check that all contradicts references exist (try proof_data first, fall back to old field)
   663→            let contradicts = if let Some(proof_data) = &admissible_set.proof_data {
   664→                Some(&proof_data.contradicts)
   665→            } else {
   666→                admissible_set.contradicts.as_ref()
   667→            };
   668→
   669→            if let Some(contradicts_set) = contradicts {
   670→                let invalid_contradicts = contradicts_set.check_integrity(&valid_spec_ids);
   671→                if !invalid_contradicts.is_empty() {
   672→                    errors.push(format!(
   673→                        "AdmissibleSet {} references non-existent specifications in contradicts: {:?}",
   674→                        spec_id.as_str(),
   675→                        invalid_contradicts
   676→                    ));
   677→                }
   678→            }
   679→        }
   680→
   681→        // Validate Transform references
   682→        for (transform_id, transform) in &self.transforms {
   683→            // Check that source_universe exists
   684→            if !valid_universe_ids.contains(transform.source_universe.as_str()) {
   685→                errors.push(format!(
   686→                    "Transform {} references non-existent source universe: {}",
   687→                    transform_id.as_str(),
   688→                    transform.source_universe.as_str()
   689→                ));
   690→            }
   691→
   692→            // Check that target_universe exists
   693→            if !valid_universe_ids.contains(transform.target_universe.as_str()) {
   694→                errors.push(format!(
   695→                    "Transform {} references non-existent target universe: {}",
   696→                    transform_id.as_str(),
   697→                    transform.target_universe.as_str()
   698→                ));
   699→            }
   700→        }
   701→
   702→        if errors.is_empty() {
   703→            Ok(())
   704→        } else {
   705→            Err(errors.join("\n"))
   706→        }
   707→    }
   708→}
