    24→/// Pure data repository for specification graph
    25→#[derive(Debug, Clone, Serialize, Deserialize)]
    26→pub struct SpecRepository {
    27→    graph: DiGraph<SpecNodeData, SpecEdgeData>,
    28→    #[serde(skip)]
    29→    id_to_index: HashMap<String, NodeIndex>,
    30→    #[serde(skip)]
    31→    edge_id_to_index: HashMap<String, EdgeIndex>,
    32→}
    33→
    34→impl Default for SpecRepository {
    35→    fn default() -> Self {
    36→        Self::new()
    37→    }
    38→}
    39→
    40→impl SpecRepository {
    41→    pub fn new() -> Self {
    42→        Self {
    43→            graph: DiGraph::new(),
    44→            id_to_index: HashMap::new(),
    45→            edge_id_to_index: HashMap::new(),
    46→        }
    47→    }
    48→
    49→    /// Rebuild lookup indices after deserialization.
    50→    pub fn rebuild_indices(&mut self) {
    51→        self.id_to_index.clear();
    52→        self.edge_id_to_index.clear();
    53→        for idx in self.graph.node_indices() {
    54→            let node = &self.graph[idx];
    55→            self.id_to_index.insert(node.id.clone(), idx);
    56→        }
    57→        for idx in self.graph.edge_indices() {
    58→            let edge = &self.graph[idx];
    59→            self.edge_id_to_index.insert(edge.id.clone(), idx);
    60→        }
    61→    }
    62→
    63→    // ========================================================================
    64→    // Node operations
    65→    // ========================================================================
    66→
    67→    pub fn add_node(
    68→        &mut self,
    69→        content: String,
    70→        kind: NodeKind,
    71→        metadata: HashMap<String, String>,
    72→    ) -> &SpecNodeData {
    73→        let id = Uuid::new_v4().to_string();
    74→        let now = Utc::now().timestamp();
    75→        let data = SpecNodeData {
    76→            id: id.clone(),
    77→            content,
    78→            kind,
    79→            metadata,
    80→            created_at: now,
    81→            modified_at: now,
    82→            formality_layer: 0, // Default to natural language
    83→        };
    84→        let idx = self.graph.add_node(data);
    85→        self.id_to_index.insert(id, idx);
    86→        &self.graph[idx]
    87→    }
