   650→    /// Get test coverage report: which specifications have test links.
   651→    pub fn get_test_coverage(&self) -> TestCoverage {
   652→        let total_testable = self
   653→            .graph
   654→            .node_weights()
   655→            .filter(|n| matches!(n.kind, NodeKind::Constraint | NodeKind::Scenario))
   656→            .count();
   657→
   658→        let with_tests = self
   659→            .graph
   660→            .node_weights()
   661→            .filter(|n| {
   662→                matches!(n.kind, NodeKind::Constraint | NodeKind::Scenario)
   663→                    && n.metadata.contains_key("test_file")
   664→            })
   665→            .count();
   666→
   667→        let nodes_with_tests: Vec<SpecNodeData> = self
   668→            .graph
   669→            .node_weights()
   670→            .filter(|n| {
   671→                matches!(n.kind, NodeKind::Constraint | NodeKind::Scenario)
   672→                    && n.metadata.contains_key("test_file")
   673→            })
   674→            .cloned()
   675→            .collect();
   676→
   677→        let nodes_without_tests: Vec<SpecNodeData> = self
   678→            .graph
   679→            .node_weights()
   680→            .filter(|n| {
   681→                matches!(n.kind, NodeKind::Constraint | NodeKind::Scenario)
   682→                    && !n.metadata.contains_key("test_file")
   683→            })
   684→            .cloned()
   685→            .collect();
   686→
   687→        TestCoverage {
   688→            total_testable,
   689→            with_tests,
   690→            coverage_ratio: if total_testable > 0 {
   691→                with_tests as f32 / total_testable as f32
   692→            } else {
   693→                0.0
   694→            },
   695→            nodes_with_tests,
   696→            nodes_without_tests,
   697→        }
   698→    }
