   910→    /// Diff graph state between two timestamps.
   911→    /// Shows what was added, modified, or removed.
   912→    pub fn diff_timestamps(&self, from_timestamp: i64, to_timestamp: i64) -> TemporalDiff {
   913→        let from_snapshot = self.query_at_timestamp(from_timestamp);
   914→        let to_snapshot = self.query_at_timestamp(to_timestamp);
   915→
   916→        let from_node_ids: std::collections::HashSet<String> =
   917→            from_snapshot.nodes.iter().map(|n| n.id.clone()).collect();
   918→        let to_node_ids: std::collections::HashSet<String> =
   919→            to_snapshot.nodes.iter().map(|n| n.id.clone()).collect();
   920→
   921→        let added_nodes: Vec<SpecNodeData> = to_snapshot
   922→            .nodes
   923→            .iter()
   924→            .filter(|n| !from_node_ids.contains(&n.id))
   925→            .cloned()
   926→            .collect();
   927→
   928→        let removed_nodes: Vec<SpecNodeData> = from_snapshot
   929→            .nodes
   930→            .iter()
   931→            .filter(|n| !to_node_ids.contains(&n.id))
   932→            .cloned()
   933→            .collect();
   934→
   935→        let modified_nodes: Vec<(SpecNodeData, SpecNodeData)> = to_snapshot
   936→            .nodes
   937→            .iter()
   938→            .filter_map(|to_node| {
   939→                from_snapshot
   940→                    .nodes
   941→                    .iter()
   942→                    .find(|from_node| from_node.id == to_node.id)
   943→                    .and_then(|from_node| {
   944→                        if from_node.modified_at < to_node.modified_at {
   945→                            Some((from_node.clone(), to_node.clone()))
   946→                        } else {
   947→                            None
   948→                        }
   949→                    })
   950→            })
   951→            .collect();
   952→
   953→        let from_edge_ids: std::collections::HashSet<String> =
   954→            from_snapshot.edges.iter().map(|e| e.id.clone()).collect();
   955→        let to_edge_ids: std::collections::HashSet<String> =
   956→            to_snapshot.edges.iter().map(|e| e.id.clone()).collect();
   957→
   958→        let added_edges: Vec<SpecEdgeData> = to_snapshot
   959→            .edges
   960→            .iter()
   961→            .filter(|e| !from_edge_ids.contains(&e.id))
   962→            .cloned()
   963→            .collect();
   964→
   965→        let removed_edges: Vec<SpecEdgeData> = from_snapshot
   966→            .edges
   967→            .iter()
   968→            .filter(|e| !to_edge_ids.contains(&e.id))
   969→            .cloned()
   970→            .collect();
   971→
   972→        TemporalDiff {
   973→            from_timestamp,
   974→            to_timestamp,
   975→            added_nodes,
   976→            removed_nodes,
   977→            modified_nodes,
   978→            added_edges,
   979→            removed_edges,
   980→        }
   981→    }
