  1031→    /// Track compliance trend over time for nodes with historical compliance data.
  1032→    /// Requires compliance scores stored in metadata with timestamps.
  1033→    pub fn get_compliance_trends(&self, node_id: &str) -> Option<ComplianceTrend> {
  1034→        let node = self.get_node(node_id)?;
  1035→
  1036→        // Extract compliance history from metadata (format: "compliance_<timestamp>")
  1037→        let mut data_points: Vec<ComplianceDataPoint> = node
  1038→            .metadata
  1039→            .iter()
  1040→            .filter_map(|(key, value)| {
  1041→                if key.starts_with("compliance_") {
  1042→                    let timestamp_str = key.strip_prefix("compliance_")?;
  1043→                    let timestamp: i64 = timestamp_str.parse().ok()?;
  1044→                    let score: f32 = value.parse().ok()?;
  1045→                    Some(ComplianceDataPoint { timestamp, score })
  1046→                } else {
  1047→                    None
  1048→                }
  1049→            })
  1050→            .collect();
  1051→
  1052→        if data_points.is_empty() {
  1053→            return None;
  1054→        }
  1055→
  1056→        // Sort by timestamp
  1057→        data_points.sort_by_key(|d| d.timestamp);
  1058→
  1059→        let trend_direction = if data_points.len() >= 2 {
  1060→            let first = data_points[0].score;
  1061→            let last = data_points[data_points.len() - 1].score;
  1062→            if last > first + 0.1 {
  1063→                "improving".to_string()
  1064→            } else if last < first - 0.1 {
  1065→                "degrading".to_string()
  1066→            } else {
  1067→                "stable".to_string()
  1068→            }
  1069→        } else {
  1070→            "unknown".to_string()
  1071→        };
  1072→
  1073→        Some(ComplianceTrend {
  1074→            node: node.clone(),
  1075→            data_points,
  1076→            trend_direction,
  1077→        })
  1078→    }
