  1123→    /// Export the specification graph in DOT format (Graphviz).
  1124→    /// Nodes are colored by formality layer (U0=blue, U1=green, U2=yellow, U3=red).
  1125→    /// Edges are styled by kind (Refines, Formalizes, etc.).
  1126→    pub fn export_dot(&self) -> String {
  1127→        let mut dot = String::from("digraph spec_oracle {\n");
  1128→        dot.push_str("    rankdir=LR;\n");
  1129→        dot.push_str("    node [shape=box, style=filled];\n");
  1130→        dot.push_str("    edge [fontsize=10];\n\n");
  1131→
  1132→        // Helper function to escape DOT strings
  1133→        fn escape_dot(s: &str) -> String {
  1134→            s.replace('\\', "\\\\")
  1135→                .replace('"', "\\\"")
  1136→                .replace('\n', "\\n")
  1137→        }
  1138→
  1139→        // Helper function to truncate content
  1140→        fn truncate(s: &str, max_len: usize) -> String {
  1141→            if s.len() > max_len {
  1142→                format!("{}...", &s[..max_len])
  1143→            } else {
  1144→                s.to_string()
  1145→            }
  1146→        }
  1147→
  1148→        // Helper function to get layer color
  1149→        fn layer_color(layer: u8) -> &'static str {
  1150→            match layer {
  1151→                0 => "lightblue",   // U0: natural language
  1152→                1 => "lightgreen",  // U1: structured/formal
  1153→                2 => "lightyellow", // U2: interface/API
  1154→                3 => "lightcoral",  // U3: implementation
  1155→                _ => "white",
  1156→            }
  1157→        }
  1158→
  1159→        // Helper function to get layer label
  1160→        fn layer_label(layer: u8) -> &'static str {
  1161→            match layer {
  1162→                0 => "U0",
  1163→                1 => "U1",
  1164→                2 => "U2",
  1165→                3 => "U3",
  1166→                _ => "U?",
  1167→            }
  1168→        }
  1169→
  1170→        // Helper function to get kind abbreviation
  1171→        fn kind_abbr(kind: NodeKind) -> &'static str {
  1172→            match kind {
  1173→                NodeKind::Assertion => "A",
  1174→                NodeKind::Constraint => "C",
  1175→                NodeKind::Scenario => "S",
  1176→                NodeKind::Definition => "D",
  1177→                NodeKind::Domain => "Dom",
  1178→            }
  1179→        }
  1180→
  1181→        // Add nodes
  1182→        for node in self.graph.node_weights() {
  1183→            let layer = node.formality_layer;
  1184→            let color = layer_color(layer);
  1185→            let layer_lbl = layer_label(layer);
  1186→            let kind_lbl = kind_abbr(node.kind);
  1187→            let content_short = truncate(&node.content, 50);
  1188→            let label = format!("[{}] {} {}", layer_lbl, kind_lbl, content_short);
  1189→
  1190→            dot.push_str(&format!(
  1191→                "    \"{}\" [label=\"{}\", fillcolor=\"{}\"];\n",
  1192→                escape_dot(&node.id),
  1193→                escape_dot(&label),
  1194→                color
  1195→            ));
  1196→        }
  1197→
  1198→        dot.push('\n');
  1199→
  1200→        // Add edges
  1201→        for edge_idx in self.graph.edge_indices() {
  1202→            if let Some((source_idx, target_idx)) = self.graph.edge_endpoints(edge_idx)
  1203→                && let Some(edge) = self.graph.edge_weight(edge_idx)
  1204→                    && let (Some(source_node), Some(target_node)) = (
  1205→                        self.graph.node_weight(source_idx),
  1206→                        self.graph.node_weight(target_idx),
  1207→                    ) {
  1208→                        let edge_style = match edge.kind {
  1209→                            EdgeKind::Refines => "solid",
  1210→                            EdgeKind::Formalizes => "bold",
  1211→                            EdgeKind::DerivesFrom => "dashed",
  1212→                            EdgeKind::Transform => "dotted",
  1213→                            EdgeKind::Contradicts => "bold, color=red",
  1214→                            EdgeKind::DependsOn => "dashed",
  1215→                            EdgeKind::Synonym => "dotted, color=gray",
  1216→                            EdgeKind::Composes => "solid",
  1217→                        };
  1218→
  1219→                        let edge_label = format!("{:?}", edge.kind);
  1220→
  1221→                        dot.push_str(&format!(
  1222→                            "    \"{}\" -> \"{}\" [label=\"{}\", style=\"{}\"];\n",
  1223→                            escape_dot(&source_node.id),
  1224→                            escape_dot(&target_node.id),
  1225→                            edge_label,
  1226→                            edge_style
  1227→                        ));
  1228→                    }
