// ==========================================
// UDA/f Model Operations (NEW)
// ==========================================

// Universe Operations
rpc CreateUniverse(CreateUniverseRequest) returns (CreateUniverseResponse);
rpc GetUniverse(GetUniverseRequest) returns (GetUniverseResponse);
rpc ListUniverses(ListUniversesRequest) returns (ListUniversesResponse);
rpc DeleteUniverse(DeleteUniverseRequest) returns (DeleteUniverseResponse);

message Universe {
  string id = 1;              // UniverseId
  uint32 layer = 2;           // 0=U0, 1=U1, 2=U2, 3=U3, ...
  string name = 3;
  string description = 4;
  map<string, string> metadata = 5;
}

// Domain Operations
rpc CreateDomain(CreateDomainRequest) returns (CreateDomainResponse);
rpc GetDomain(GetDomainRequest) returns (GetDomainResponse);
rpc ListDomains(ListDomainsRequest) returns (ListDomainsResponse);
rpc UpdateDomainConstraints(UpdateDomainConstraintsRequest)
    returns (UpdateDomainConstraintsResponse);

message Domain {
  string id = 1;              // DomainId
  string universe_id = 2;
  string name = 3;
  string description = 4;
  repeated Constraint boundary_constraints = 5;
  map<string, string> metadata = 6;
}

// AdmissibleSet Operations
rpc CreateAdmissibleSet(CreateAdmissibleSetRequest)
    returns (CreateAdmissibleSetResponse);
rpc GetAdmissibleSet(GetAdmissibleSetRequest)
    returns (GetAdmissibleSetResponse);
rpc VerifyConsistency(VerifyConsistencyRequest)
    returns (VerifyConsistencyResponse);
rpc VerifyImplication(VerifyImplicationRequest)
    returns (VerifyImplicationResponse);

message AdmissibleSet {
  string spec_id = 1;
  repeated Constraint constraints = 2;
  repeated string contradicts = 3;  // Spec IDs
  map<string, string> metadata = 4;
}

message Constraint {
  string formal = 1;          // SMT-LIB or formal representation
  ConstraintKind kind = 2;
  string description = 3;
}

enum ConstraintKind {
  UNIVERSAL = 0;
  EXISTENTIAL = 1;
  IMPLICATION = 2;
  EQUIVALENCE = 3;
}

// Transform Operations
rpc CreateTransform(CreateTransformRequest) returns (CreateTransformResponse);
rpc ListTransforms(ListTransformsRequest) returns (ListTransformsResponse);
rpc ExecuteTransform(ExecuteTransformRequest) returns (ExecuteTransformResponse);
rpc VerifyTransformSoundness(VerifyTransformSoundnessRequest)
    returns (VerifyTransformSoundnessResponse);

message Transform {
  string id = 1;
  string source_universe_id = 2;
  string target_universe_id = 3;
  TransformKind kind = 4;
  TransformStrategy strategy = 5;
  map<string, string> metadata = 6;
}

enum TransformKind {
  FORWARD = 0;   // f: U_source → U_target
  INVERSE = 1;   // f⁻¹: U_target → U_source (construct U0)
  PARALLEL = 2;  // f: U_i → U_j (both > 0)
}

enum TransformStrategy {
  AST_ANALYSIS = 0;
  NLP_INFERENCE = 1;
  FORMAL_VERIFICATION = 2;
  TYPE_ANALYSIS = 3;
  MANUAL = 4;
  PROJECTION = 5;  // Observer >> Extractor composition
}

// Projection Operations (Core Reverse Mapping)
rpc ConstructU0(ConstructU0Request) returns (ConstructU0Response);
rpc ExecuteProjection(ExecuteProjectionRequest)
    returns (ExecuteProjectionResponse);

message ConstructU0Request {
  string project = 1;
  RootSpace root_space = 2;
  bool execute_transforms = 3;
}

message ConstructU0Response {
  repeated InferredSpecification specs = 1;
  IngestionReport ingestion_report = 2;
}

message RootSpace {
  string id = 1;
  RootSpaceKind kind = 2;
  repeated string artifact_paths = 3;  // For ArtifactBundle
  map<string, string> metadata = 4;
}

enum RootSpaceKind {
  ARTIFACT_BUNDLE = 0;  // Code, tests, docs at a point in time
  TRACE = 1;            // Behavioral observations
}

message InferredSpecification {
  string content = 1;
  string source_universe = 2;
  float confidence = 3;
  string extraction_method = 4;
  map<string, string> metadata = 5;
}

// Verification Operations
rpc ProveProperty(ProvePropertyRequest) returns (ProvePropertyResponse);
rpc DetectContradictionsWithProver(DetectContradictionsWithProverRequest)
    returns (DetectContradictionsResponse);
rpc DetectOmissionsWithDomains(DetectOmissionsWithDomainsRequest)
    returns (DetectOmissionsResponse);

message ProvePropertyRequest {
  string project = 1;
  Property property = 2;
}

message Property {
  oneof kind {
    ConsistencyProperty consistency = 1;
    SatisfiabilityProperty satisfiability = 2;
    ImplicationProperty implication = 3;
    CompletenessProperty completeness = 4;
    TransformSoundnessProperty transform_soundness = 5;
  }
}

message ProvePropertyResponse {
  ProofStatus status = 1;
  Proof proof = 2;
  string counterexample = 3;
}

enum ProofStatus {
  PROVEN = 0;
  REFUTED = 1;
  UNKNOWN = 2;
  PENDING = 3;
}
