use ini::Ini;
use std::path::PathBuf;

#[derive(Debug, Clone)]
pub struct SpecdConfig {
    pub listen_address: String,
    pub log_level: String,
    pub default_storage: String,
    pub default_path: PathBuf,
}

impl SpecdConfig {
    pub fn load(path: &Path) -> Result<Self> {
        let conf = Ini::load_from_file(path)?;

        let specd_section = conf.section(Some("specd"))
            .ok_or_else(|| anyhow!("Missing [specd] section"))?;
        let projects_section = conf.section(Some("projects"))
            .ok_or_else(|| anyhow!("Missing [projects] section"))?;

        Ok(Self {
            listen_address: specd_section.get("listen_address")
                .unwrap_or("[::1]:50051").to_string(),
            log_level: specd_section.get("log_level")
                .unwrap_or("info").to_string(),
            default_storage: projects_section.get("default_storage")
                .unwrap_or("local").to_string(),
            default_path: PathBuf::from(projects_section.get("default_path")
                .unwrap_or("~/.specd/projects")),
        })
    }

    pub fn default_config_path() -> PathBuf {
        dirs::home_dir()
            .unwrap_or_else(|| PathBuf::from("."))
            .join(".specd")
            .join("config.ini")
    }

    pub fn load_or_default() -> Result<Self> {
        let config_path = Self::default_config_path();
        if config_path.exists() {
            Self::load(&config_path)
        } else {
            Ok(Self::default())
        }
    }
}

impl Default for SpecdConfig {
    fn default() -> Self {
        Self {
            listen_address: "[::1]:50051".to_string(),
            log_level: "info".to_string(),
            default_storage: "local".to_string(),
            default_path: dirs::home_dir()
                .unwrap_or_else(|| PathBuf::from("."))
                .join(".specd")
                .join("projects"),
        }
